// Base de datos de hechizos — SRD 5e (2014) + suplementos públicos citados donde corresponde.
// Alcance: hechizos usados por las 6 fichas D&D de la campaña + lista completa de Druida
// (para el futuro personaje Circle of Spores). Fuentes: 5thsrd.org, 5esrd.com, dnd5e.wikidot.com,
// D&D Beyond, Roll20 Compendium (consultadas vía búsqueda pública durante la investigación).
const SPELLS = [
// ===== CANTRIPS (Nivel 0) =====
{name:"Druidcraft", nivel:0, edicion:"ambas", etiquetas:["utilidad"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, S", duracion:"Instantáneo", clases:["Druida"], desc:"Creás uno de varios efectos menores de la naturaleza: predecir el clima, hacer brotar/marchitar una planta pequeña, crear una luz o sonido sensorial inofensivo, o encender/apagar una llama pequeña."},
{name:"Guidance", nivel:0, edicion:"ambas", etiquetas:["buff"], escuela:"Adivinación", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S", duracion:"Conc., hasta 1 min", clases:["Clérigo","Druida"], desc2024:"Tocás a una criatura voluntaria y elegís una habilidad; hasta que termine el conjuro (concentración, hasta 1 min), la criatura suma 1d4 a toda prueba de característica que use esa habilidad.", desc:"Tocás a una criatura voluntaria; una vez antes de que termine el conjuro, puede tirar 1d4 y sumarlo a una prueba de característica de su elección.", buff:{activo:false, efectos:[{tipo:"dado", objetivo:"pruebas", dado:{count:1, sides:4}}]}},
{name:"Mending", nivel:0, edicion:"ambas", etiquetas:["utilidad"], escuela:"Transmutación", tiempo:"1 minuto", alcance:"Toque", componentes:"V, S, M (dos piedras imán)", duracion:"Instantáneo", clases:["Bardo","Clérigo","Druida","Hechicero","Mago"], desc:"Reparás una rotura o rasgadura simple en un objeto tocado (hasta 1 pie en cualquier dimensión), sin dejar rastro del daño anterior."},
{name:"Poison Spray", nivel:0, edicion:"ambas", etiquetas:["daño","veneno","salvación"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"10 ft", componentes:"V, S", duracion:"Instantáneo", clases:["Druida","Hechicero","Brujo","Mago"], desc2024:"En 2024: alcance 30 ft (en lugar de 10 ft) y es de escuela Necromancia. Rociás niebla tóxica sobre una criatura a tu alcance: tirada de ataque de conjuro a distancia; si impacta, sufre 1d12 daño de veneno (en vez de salvación de Constitución). El daño sube a 2d12 en nivel 5, 3d12 en nivel 11 y 4d12 en nivel 17.", desc:"Proyectás veneno hacia una criatura a tu alcance; salvación de Constitución o sufre 1d12 daño de veneno (escala con nivel de personaje)."},
{name:"Produce Flame", nivel:0, edicion:"ambas", etiquetas:["daño","fuego","ataque"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"Personal", componentes:"V, S", duracion:"10 minutos", clases:["Druida"], desc2024:"En 2024: se lanza como acción adicional. Una llama en tu mano (10 min) no da calor ni enciende nada; emite luz brillante en 20 ft y tenue otros 20 ft. Mientras dure, con una acción de Magia la arrojás a una criatura u objeto a 60 ft (ataque de conjuro a distancia, 1d8 de fuego; +1d8 a niveles 5/11/17). El conjuro termina si lo lanzás de nuevo.", desc:"Una llama aparece en tu mano y no te daña; podés usarla como luz (10 ft brillante) o arrojarla a un objetivo a 30 ft (ataque de conjuro, 1d8 fuego, escala con nivel de personaje)."},
{name:"Resistance", nivel:0, edicion:"ambas", etiquetas:["buff"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S, M (una capa en miniatura)", duracion:"Conc., hasta 1 min", clases:["Clérigo","Druida"], desc2024:"Tocás a una criatura voluntaria y elegís un tipo de daño (ácido, contundente, de frío, de fuego, de relámpago, necrótico, perforante, de veneno, radiante, cortante o de trueno). Cuando la criatura sufra daño de ese tipo antes de que termine el conjuro, reduce el daño total en 1d4. Una criatura solo puede beneficiarse de este conjuro una vez por turno.", desc:"Tocás a una criatura voluntaria; una vez antes de que termine el conjuro, puede tirar 1d4 y sumarlo a una salvación de su elección.", buff:{activo:false, efectos:[{tipo:"dado", objetivo:"salvaciones", dado:{count:1, sides:4}}]}},
{name:"Shillelagh", nivel:0, edicion:"ambas", etiquetas:["buff","arma"], escuela:"Transmutación", tiempo:"1 Acción Adicional", alcance:"Toque", componentes:"V, S, M (muérdago, trébol y el arma)", duracion:"1 minuto", clases:["Druida"], desc2024:"En 2024: alcance Personal y el material es solo muérdago. Un Club o Quarterstaff que sostenés se imbuye de poder natural: usás tu característica de lanzamiento en vez de Fuerza para ataque y daño cuerpo a cuerpo con él, y su dado de daño pasa a d8. Si el ataque inflige daño, podés elegir daño de fuerza o el tipo normal del arma. Termina antes si lo lanzás otra vez o soltás el arma. Mejora de truco: el dado de daño pasa a d10 (nivel 5), d12 (nivel 11) y 2d6 (nivel 17).", desc:"Un bastón o garrote que sostenés se imbuye de magia natural: usás tu característica de lanzamiento (en vez de Fuerza) para ataque y daño cuerpo a cuerpo con esa arma, y su dado de daño pasa a 1d8."},
{name:"Light", nivel:0, edicion:"ambas", etiquetas:["utilidad"], escuela:"Evocación", tiempo:"1 Acción", alcance:"Toque", componentes:"V, M (una luciérnaga o musgo fosforescente)", duracion:"1 hora", clases:["Bardo","Clérigo","Hechicero","Mago"], desc2024:"En 2024: el objeto tocado debe ser Grande o menor y no estar puesto ni llevado por otra criatura (ya no hay salvación de Destreza contra un objeto de una criatura hostil). Emite luz brillante en 20 ft y tenue 20 ft más, del color que elijas; cubrirlo con algo opaco la bloquea y termina si lo lanzás de nuevo.", desc:"Un objeto tocado emite luz brillante en 20 ft (y tenue 20 ft más), de un color a elección; se puede cubrir para bloquearla."},
{name:"Sacred Flame", nivel:0, edicion:"ambas", etiquetas:["daño","radiante","salvación"], escuela:"Evocación", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S", duracion:"Instantáneo", clases:["Clérigo"], desc:"Fuego radiante cae sobre una criatura a tu alcance (ignora cobertura). Salvación de Destreza o sufre 1d8 daño radiante (escala con nivel de personaje)."},
{name:"Fire Bolt", nivel:0, edicion:"ambas", etiquetas:["daño","fuego","ataque"], escuela:"Evocación", tiempo:"1 Acción", alcance:"120 ft", componentes:"V, S", duracion:"Instantáneo", clases:["Hechicero","Mago"], desc:"Ataque de conjuro a distancia; en un impacto, el objetivo sufre 1d10 daño de fuego (escala con nivel de personaje) y los objetos inflamables no equipados pueden prenderse fuego."},
{name:"Ray of Frost", nivel:0, edicion:"ambas", etiquetas:["daño","frío","ataque"], escuela:"Evocación", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S", duracion:"Instantáneo", clases:["Hechicero","Mago"], desc:"Ataque de conjuro a distancia; en un impacto, 1d8 daño de frío (escala con nivel de personaje) y la velocidad del objetivo se reduce 10 ft hasta el inicio de tu próximo turno."},
{name:"Mage Hand", nivel:0, edicion:"ambas", etiquetas:["utilidad"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, S", duracion:"1 minuto", clases:["Bardo","Hechicero","Brujo","Mago"], desc:"Una mano espectral aparece en un punto a tu alcance; puede manipular objetos livianos, abrir/cerrar cosas simples o mover objetos hasta 30 ft. No puede atacar ni activar objetos mágicos."},
{name:"Minor Illusion", nivel:0, edicion:"ambas", etiquetas:["utilidad","ilusión"], escuela:"Ilusión", tiempo:"1 Acción", alcance:"30 ft", componentes:"S, M (un poco de lana)", duracion:"1 minuto", clases:["Bardo","Hechicero","Brujo","Mago"], desc2024:"Creás un sonido o la imagen de un objeto (cubo de hasta 5 ft) a 30 ft durante 1 minuto. Termina solo si lanzás el conjuro de nuevo (ya no se descarta con una acción). Una criatura que use la acción Estudiar puede descubrir la ilusión con una prueba de Inteligencia (Investigación) contra tu CD; si lo logra, la ilusión se ve tenue para ella.", desc:"Creás un sonido o una imagen visual (no ambos) de un objeto que quepa en un cubo de 5 ft, que persiste hasta el final del conjuro o hasta usar una acción para descartarlo."},
{name:"Prestidigitation", nivel:0, edicion:"ambas", etiquetas:["utilidad"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"10 ft", componentes:"V, S", duracion:"Hasta 1 hora", clases:["Bardo","Hechicero","Brujo","Mago"], desc:"Truco de magia menor a elección: chispa sensorial, apagar una vela, limpiar/ensuciar un objeto pequeño, saborizar comida, marcar un objeto, o crear una imagen inofensiva de 1 pie por 1 turno."},
{name:"Booming Blade", nivel:0, etiquetas:["daño","trueno","arma"], escuela:"Evocación", tiempo:"1 Acción", alcance:"Personal (arma cuerpo a cuerpo, 5 ft)", componentes:"V, M (un arma cuerpo a cuerpo)", duracion:"1 turno", clases:["Hechicero","Brujo","Mago"], desc:"Hacés un ataque cuerpo a cuerpo con arma; en un impacto, daño normal del arma + energía resonante alrededor del objetivo — si se mueve antes de tu próximo turno, sufre 1d8 daño de trueno extra (escala con nivel de personaje)."},
{name:"Mind Sliver", nivel:0, etiquetas:["daño","psíquico","salvación"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"60 ft", componentes:"V", duracion:"Hasta el final de tu próximo turno", clases:["Hechicero","Brujo","Mago"], desc:"Salvación de Inteligencia o el objetivo sufre 1d6 daño psíquico (escala con nivel de personaje) y resta 1d4 a la próxima tirada de salvación que haga antes del final de tu próximo turno."},
{name:"Eldritch Blast", nivel:0, edicion:"ambas", etiquetas:["daño","fuerza","ataque"], escuela:"Evocación", tiempo:"1 Acción", alcance:"120 ft", componentes:"V, S", duracion:"Instantáneo", clases:["Brujo"], desc2024:"Lanzás un rayo de energía crepitante; tirada de ataque de conjuro a distancia contra una criatura u objeto en alcance. Si impacta, 1d10 de daño de fuerza. Mejora de truco: dos rayos a nivel 5, tres a nivel 11 y cuatro a nivel 17; podés dirigirlos al mismo objetivo o a distintos, con una tirada de ataque por rayo.", desc:"Un rayo crepitante de energía; ataque de conjuro a distancia, 1d10 daño de fuerza en un impacto. A nivel 5, 11 y 17 lanzás un rayo extra (podés apuntar a objetivos distintos)."},
{name:"Acid Splash", nivel:0, edicion:"ambas", etiquetas:["daño", "ácido", "salvación"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S", duracion:"Instantáneo", clases:["Hechicero", "Mago"], desc:"Lanzás una burbuja de ácido: elegís una criatura en alcance, o dos criaturas a 5 ft una de otra; cada una hace salvación de Destreza o sufre 1d6 daño de ácido. El daño sube a 2d6 en nivel de personaje 5, 3d6 en 11 y 4d6 en 17.", desc2024:"En 2024 (escuela Evocación): la burbuja estalla en un punto del alcance (60 ft) como esfera de 5 ft de radio, en vez de apuntar a una o dos criaturas; cada criatura en ella hace salvación de Destreza o sufre 1d6 daño de ácido (2d6 en nivel 5, 3d6 en 11, 4d6 en 17)."},
{name:"Chill Touch", nivel:0, edicion:"ambas", etiquetas:["daño", "necrótico", "ataque"], escuela:"Necromancia", tiempo:"1 Acción", alcance:"120 ft", componentes:"V, S", duracion:"1 turno", clases:["Hechicero", "Brujo", "Mago"], desc:"Creás una mano esquelética espectral junto a una criatura a tu alcance y hacés una tirada de ataque de conjuro a distancia. Si impacta, sufre 1d8 daño necrótico y no puede recuperar PG hasta el inicio de tu próximo turno. Si es un no-muerto, además tiene desventaja en sus ataques contra vos hasta el final de tu próximo turno. El daño aumenta en 1d8 en los niveles de personaje 5 (2d8), 11 (3d8) y 17 (4d8).", desc2024:"Tirada de ataque de conjuro cuerpo a cuerpo contra un objetivo a tu alcance (Toque, duración instantánea). Si impacta, sufre 1d10 daño necrótico y no puede recuperar PG hasta el final de tu próximo turno. Ya no hay penalizador especial para no-muertos. El daño aumenta en 1d10 en los niveles de personaje 5 (2d10), 11 (3d10) y 17 (4d10)."},
{name:"Dancing Lights", nivel:0, edicion:"ambas", etiquetas:["ilusión", "utilidad"], escuela:"Evocación", tiempo:"1 Acción", alcance:"120 ft", componentes:"V, S, M (un poco de fósforo o wychwood, o un gusano luminoso)", duracion:"Conc., hasta 1 min", clases:["Bardo", "Hechicero", "Mago"], desc:"Creás hasta cuatro luces del tamaño de una antorcha a tu alcance, con apariencia de antorchas, linternas u orbes brillantes que flotan durante la duración; también podés combinarlas en una forma brillante vagamente humanoide de tamaño Mediano. Cada luz emite luz tenue en 10 ft de radio. Como acción adicional en tu turno, movés las luces hasta 60 ft a un punto a tu alcance; cada luz debe estar a 20 ft o menos de otra luz del conjuro, y se apaga si excede su alcance."},
{name:"Elementalism", nivel:0, edicion:"2024", etiquetas:["utilidad"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, S", duracion:"Instantáneo", clases:["Druida", "Hechicero", "Mago"], desc:"Controlás los elementos y creás uno de estos efectos a tu alcance. Invocar Aire: una brisa que agita telas, polvo y hojas y cierra puertas y postigos abiertos (no los sostenidos), en un cubo de 5 ft. Invocar Tierra: una capa fina de polvo o arena en un área de 5 ft por lado, o una palabra escrita con tu letra en tierra o arena. Invocar Fuego: una nube fina de brasas inofensivas y humo de color y aroma a elección en un cubo de 5 ft; las brasas encienden velas, antorchas o lámparas y el aroma dura 1 minuto. Invocar Agua: una llovizna fría que humedece levemente criaturas y objetos en un cubo de 5 ft, o 1 taza de agua limpia en un recipiente abierto o sobre una superficie (se evapora en 1 minuto). Moldear Elemento: tierra, arena, fuego, humo, niebla o agua que quepa en un cubo de 1 ft adopta una forma tosca (p. ej. una criatura) durante 1 hora."},
{name:"Message", nivel:0, edicion:"ambas", etiquetas:["utilidad"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"120 ft", componentes:"V, S, M (un trozo corto de alambre de cobre)", duracion:"1 turno", clases:["Bardo", "Hechicero", "Mago"], desc:"Señalás con el dedo a una criatura en alcance y le susurrás un mensaje; solo el objetivo lo oye y puede responder en un susurro que solo vos oís. Podés lanzarlo a través de objetos sólidos si conocés al objetivo y sabés que está del otro lado. Lo bloquean el silencio mágico, 1 ft de piedra, 1 pulgada de metal común, una lámina fina de plomo o 3 ft de madera. No necesita línea recta: rodea esquinas y pasa por aberturas.", desc2024:"En 2024 también lo lanzan los Druidas y no requiere componente verbal (solo S, M: un alambre de cobre). Señalás a una criatura en alcance y le susurrás un mensaje que solo ella oye y puede responder en susurro. Podés lanzarlo a través de objetos sólidos si conocés al objetivo y sabés que está del otro lado; lo bloquean el silencio mágico, 1 ft de piedra, metal o madera, o una lámina fina de plomo."},
{name:"Shocking Grasp", nivel:0, edicion:"ambas", etiquetas:["daño", "rayo", "ataque"], escuela:"Evocación", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S", duracion:"Instantáneo", clases:["Hechicero", "Mago"], desc:"Un chispazo salta de tu mano; ataque de conjuro cuerpo a cuerpo contra una criatura que intentás tocar, con ventaja si lleva armadura de metal. Si impacta, 1d8 de daño de rayo y la criatura no puede usar reacciones hasta el comienzo de su próximo turno. El daño sube a 2d8 (nivel 5), 3d8 (nivel 11) y 4d8 (nivel 17).", desc2024:"En 2024: ataque de conjuro cuerpo a cuerpo (ya sin ventaja contra armadura de metal); si impacta, 1d8 de daño de rayo y la criatura no puede hacer Ataques de oportunidad hasta el comienzo de su próximo turno (en vez de perder reacciones). Mejora de truco: 2d8 (nivel 5), 3d8 (nivel 11), 4d8 (nivel 17)."},
{name:"Sorcerous Burst", nivel:0, edicion:"2024", etiquetas:["daño", "ataque", "ácido", "frío", "fuego", "rayo", "veneno", "psíquico", "trueno"], escuela:"Evocación", tiempo:"1 Acción", alcance:"120 ft", componentes:"V, S", duracion:"Instantáneo", clases:["Hechicero"], desc:"Lanzás energía hechicera contra una criatura u objeto a tu alcance: tirada de ataque de conjuro a distancia; si impacta, sufre 1d8 de daño del tipo que elijas: ácido, frío, fuego, relámpago, veneno, psíquico o trueno. Si sacás un 8 en un d8 de este hechizo, podés tirar otro d8 y sumarlo al daño; la cantidad máxima de d8 extra que podés sumar al lanzarlo es igual a tu modificador de característica de lanzamiento. El daño sube a 2d8 en nivel 5, 3d8 en nivel 11 y 4d8 en nivel 17."},
{name:"Spare the Dying", nivel:0, edicion:"ambas", etiquetas:["utilidad", "curación"], escuela:"Necromancia", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S", duracion:"Instantáneo", clases:["Clérigo"], desc:"Tocás a una criatura viva que tiene 0 PG: queda estabilizada. No tiene efecto sobre muertos vivientes ni constructos.", desc2024:"En 2024: alcance 15 ft (se duplica a nivel 5 (30 ft), 11 (60 ft) y 17 (120 ft)) y también está en la lista de Druida. Elegís a una criatura a alcance que tenga 0 PG y no esté muerta; queda Estable. Ya no excluye a muertos vivientes ni constructos."},
{name:"Starry Wisp", nivel:0, edicion:"2024", etiquetas:["daño", "radiante", "ataque"], escuela:"Evocación", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S", duracion:"Instantáneo", clases:["Bardo", "Druida"], desc:"Lanzás una mota de luz contra una criatura u objeto a 60 ft (ataque de conjuro a distancia). Si impacta, sufre 1d8 daño radiante y hasta el final de tu próximo turno emite luz tenue en 10 ft y no puede beneficiarse de la condición Invisible. El daño aumenta 1d8 en los niveles de personaje 5 (2d8), 11 (3d8) y 17 (4d8)."},
{name:"Thaumaturgy", nivel:0, edicion:"ambas", etiquetas:["utilidad"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"30 ft", componentes:"V", duracion:"1 minuto", clases:["Clérigo"], desc:"Manifestás una maravilla menor, señal de poder sobrenatural, con uno de estos efectos en alcance: tu voz retumba hasta tres veces más fuerte durante 1 min; hacés que las llamas titilen, se aviven, se apaguen o cambien de color 1 min; temblores inofensivos en el suelo 1 min; un sonido instantáneo desde un punto a elección (trueno, graznido de cuervo, susurros ominosos); abrís o cerrás de golpe una puerta o ventana sin traba; alterás el aspecto de tus ojos 1 min. Si lo lanzás varias veces, podés tener hasta tres efectos de 1 min activos y descartar uno con una acción.", desc2024:"En 2024 los efectos tienen nombre (Ojos Alterados, Voz Retumbante, Juego de Fuego, Mano Invisible, Sonido Fantasma, Temblores) y funcionan igual, con una novedad: con Voz Retumbante tenés ventaja en pruebas de Carisma (Intimidación) mientras dure. Hasta tres efectos de 1 min a la vez si lo lanzás varias veces."},
{name:"True Strike", nivel:0, edicion:"ambas", etiquetas:["buff", "adivinación", "arma", "daño", "radiante"], escuela:"Adivinación", tiempo:"1 Acción", alcance:"30 ft", componentes:"S", duracion:"Conc., hasta 1 turno", clases:["Bardo", "Hechicero", "Brujo", "Mago"], desc:"Señalás a un objetivo a tu alcance y obtenés una breve visión de sus defensas: en tu próximo turno tenés ventaja en tu primera tirada de ataque contra él, siempre que el conjuro no haya terminado.", desc2024:"Cambia por completo: tiempo de lanzamiento 1 acción, alcance Personal, componentes S y M (un arma con la que seas competente y que valga 1+ pc), duración instantánea. Hacés un ataque con el arma usada para lanzarlo, usando tu característica de lanzamiento para ataque y daño en lugar de Fuerza o Destreza; el daño puede ser radiante o el normal del arma (a elección). Mejora de truco: en los niveles 5 (1d6), 11 (2d6) y 17 (3d6) el ataque inflige daño radiante extra."},
{name:"Vicious Mockery", nivel:0, edicion:"ambas", etiquetas:["daño", "psíquico", "salvación", "control"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"60 ft", componentes:"V", duracion:"Instantáneo", clases:["Bardo"], desc:"Lanzás una sarta de insultos con sutiles encantamientos a una criatura que veas a tu alcance. Si puede oírte (aunque no te entienda), debe superar una tirada de salvación de Sabiduría o sufre 1d4 daño psíquico y tiene desventaja en la próxima tirada de ataque que haga antes del final de su siguiente turno. El daño aumenta en 1d4 en los niveles de personaje 5 (2d4), 11 (3d4) y 17 (4d4).", desc2024:"En 2024: el objetivo es una criatura que veas u oigas a tu alcance (ya no necesita oírte) y el daño base es 1d6. Debe superar una tirada de salvación de Sabiduría o sufre 1d6 daño psíquico y tiene desventaja en la próxima tirada de ataque que haga antes del final de su siguiente turno. El daño aumenta en 1d6 en los niveles de personaje 5 (2d6), 11 (3d6) y 17 (4d6)."},

// ===== NIVEL 1 =====
{name:"Animal Friendship", nivel:1, edicion:"ambas", etiquetas:["control"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, S, M (golosina)", duracion:"24 horas", clases:["Bardo","Druida","Ranger"], desc2024:"Elegís una Bestia que veas a 30 ft; debe superar una salvación de Sabiduría o queda Hechizada 24 horas (ya no hace falta que te vea y oiga, ni existe el límite de Inteligencia 4). Termina si vos o un aliado le hacen daño. A niveles superiores: una Bestia adicional por cada nivel de espacio por encima de 1.", desc:"Encantás a una bestia (salvación de Sabiduría) para que no te ataque mientras dure el conjuro."},
{name:"Charm Person", nivel:1, edicion:"ambas", etiquetas:["control"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, S", duracion:"1 hora", clases:["Bardo","Druida","Hechicero","Brujo","Mago"], desc2024:"En 2024: un humanoide que veas en alcance hace salvación de Sabiduría (con ventaja si vos o tus aliados lo están combatiendo); si falla queda Hechizado hasta que termine el hechizo o hasta que vos o tus aliados lo dañen, y te considera Amistoso. Al terminar, sabe que lo hechizaste. A niveles superiores: una criatura adicional por nivel de espacio por encima de 1.", desc:"Un humanoide hace salvación de Sabiduría o queda hechizado, considerándote un conocido amistoso durante la duración."},
{name:"Create or Destroy Water", nivel:1, edicion:"ambas", etiquetas:["utilidad"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, S, M (gota de agua o pizca de arena)", duracion:"Instantáneo", clases:["Clérigo","Druida"], desc2024:"En 2024: el componente material es una mezcla de agua y arena, y al caer como lluvia en el cubo de 30 ft el agua apaga las llamas expuestas en esa zona. Elegís: Crear Agua (hasta 10 galones de agua limpia en un recipiente abierto, o lluvia en un cubo de 30 ft) o Destruir Agua (hasta 10 galones en un recipiente abierto, o niebla en un cubo de 30 ft). A niveles superiores: +10 galones por nivel de espacio por encima de 1, o el cubo crece 5 ft por nivel.", desc:"Creás o destruís hasta 10 galones de agua (o dispersás niebla en un área)."},
{name:"Cure Wounds", nivel:1, edicion:"ambas", etiquetas:["curación"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S", duracion:"Instantáneo", clases:["Bardo","Clérigo","Druida","Paladín","Ranger"], desc2024:"En 2024: una criatura que tocás recupera 2d8 + tu modificador de característica de lanzamiento en PG (en vez de 1d8). A niveles superiores: la curación aumenta 2d8 por cada nivel de espacio por encima de 1.", desc:"Una criatura tocada recupera 1d8 + tu mod. de característica de lanzamiento HP (escala con nivel de espacio usado).", upcast:{tipo:"dado", nivelBase:1, dado:{count:1, sides:8}}},
{name:"Detect Magic", nivel:1, edicion:"ambas", etiquetas:["utilidad"], escuela:"Adivinación", tiempo:"1 Acción", alcance:"Personal", componentes:"V, S", duracion:"Conc., hasta 10 min", clases:["Bardo","Clérigo","Druida","Paladín","Ranger","Hechicero","Mago"], desc2024:"En 2024: percibís efectos mágicos a 30 ft de vos; con la acción Magia ves un aura tenue alrededor de lo que los porte y, si el efecto es un hechizo, sabés su escuela. Lo bloquean 1 ft de piedra, tierra o madera, 1 pulgada de metal o una lámina fina de plomo. También lo aprende el Brujo.", desc:"Percibís la presencia de magia a 30 ft; con una acción, ves un aura tenue alrededor de la fuente e identificás su escuela."},
{name:"Detect Poison and Disease", nivel:1, edicion:"ambas", etiquetas:["utilidad"], escuela:"Adivinación", tiempo:"1 Acción", alcance:"Personal", componentes:"V, S, M (hoja de acebo)", duracion:"Conc., hasta 10 min", clases:["Clérigo","Druida","Paladín","Ranger"], desc2024:"Detectás la ubicación de venenos, criaturas ponzoñosas o venenosas y contagios mágicos a 30 ft (ya no enfermedades en general), e identificás su tipo. Lo bloquean 1 ft de piedra, tierra o madera, 1 pulgada de metal o una lámina fina de plomo.", desc:"Detectás la presencia y ubicación de venenos, criaturas venenosas y enfermedades a 30 ft."},
{name:"Entangle", nivel:1, edicion:"ambas", etiquetas:["control","salvación"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"90 ft", componentes:"V, S", duracion:"Conc., hasta 1 min", clases:["Druida"], desc2024:"Plantas brotan en un cuadrado de 20 ft dentro del alcance (90 ft) y vuelven el terreno difícil. Cada criatura en el área (salvo vos) debe superar una salvación de Fuerza o queda Apresada hasta que termine el conjuro; puede usar una acción para una prueba de Fuerza (Atletismo) contra tu CD y, si tiene éxito, se libera. En 2024 también está en la lista del Explorador.", desc:"Enredaderas cubren un área de 20x20 ft; las criaturas ahí hacen salvación de Fuerza o quedan apresadas, con la zona convirtiéndose en terreno difícil."},
{name:"Faerie Fire", nivel:1, edicion:"ambas", etiquetas:["control","salvación"], escuela:"Evocación", tiempo:"1 Acción", alcance:"60 ft", componentes:"V", duracion:"Conc., hasta 1 min", clases:["Druida"], desc:"Objetos y criaturas en un cubo de 20 ft se contornean de luz (salvación de Destreza para evitarlo); no pueden beneficiarse de estar invisibles, y los ataques contra ellos tienen ventaja."},
{name:"Fog Cloud", nivel:1, edicion:"ambas", etiquetas:["control"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"120 ft", componentes:"V, S", duracion:"Conc., hasta 1 hora", clases:["Druida","Ranger","Hechicero","Mago"], desc:"Una esfera de niebla de 20 ft de radio bloquea la visión, obstruyendo la visión más allá de 5 ft."},
{name:"Goodberry", nivel:1, edicion:"ambas", etiquetas:["curación"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S, M (una rama de acebo)", duracion:"Instantáneo", clases:["Druida","Ranger"], desc2024:"En 2024: diez bayas aparecen en tu mano (duración 24 horas). Una criatura puede usar una acción adicional para comer una: restituye 1 PG y alimenta por un día. Las bayas no comidas desaparecen al terminar el conjuro.", desc:"Hasta 10 bayas mágicas aparecen; cada una alimenta como una comida y cura 1 HP al comerla (máx. 10 por período de 24 horas)."},
{name:"Healing Word", nivel:1, edicion:"ambas", etiquetas:["curación"], escuela:"Abjuración", tiempo:"1 Acción Adicional", alcance:"60 ft", componentes:"V", duracion:"Instantáneo", clases:["Bardo","Clérigo","Druida"], desc2024:"En 2024 la criatura que elijas y veas a tu alcance recupera 2d4 + tu modificador de característica de lanzamiento PG (ya no excluye muertos vivientes ni constructos). A niveles superiores: la curación aumenta en 2d4 por cada nivel de espacio por encima del 1.º.", desc:"Una criatura a tu alcance recupera 1d4 + tu mod. de característica de lanzamiento HP (escala con nivel de espacio usado).", upcast:{tipo:"dado", nivelBase:1, dado:{count:1, sides:4}}},
{name:"Jump", nivel:1, edicion:"ambas", etiquetas:["buff"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S, M (pata de saltamontes)", duracion:"1 minuto", clases:["Druida","Ranger","Hechicero","Mago"], desc2024:"Tocás a una criatura voluntaria; una vez en cada uno de sus turnos hasta que termine el conjuro (1 minuto, acción adicional), puede saltar hasta 30 ft gastando 10 ft de movimiento (ya no triplica la distancia de salto). A niveles superiores: una criatura adicional por cada nivel de espacio por encima de 1.", desc:"La distancia de salto de la criatura tocada se triplica durante la duración."},
{name:"Longstrider", nivel:1, edicion:"ambas", etiquetas:["buff"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S, M (pizca de tierra)", duracion:"1 hora", clases:["Bardo","Druida","Ranger","Mago"], desc:"La velocidad de la criatura tocada aumenta 10 ft durante la duración.", buff:{activo:false, efectos:[{tipo:"plano", objetivo:"velocidad", valor:10}]}},
{name:"Purify Food and Drink", nivel:1, edicion:"ambas", etiquetas:["utilidad"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"10 ft", componentes:"V, S", duracion:"Instantáneo", clases:["Clérigo","Druida","Paladín"], desc2024:"Eliminás el veneno y la podredumbre (ya no la enfermedad) de la comida y bebida no mágica en una esfera de 5 ft de radio centrada en un punto a tu alcance (10 ft).", desc:"Toda la comida y bebida no mágica en un cubo de 5 ft a tu alcance queda purificada de veneno y contaminación."},
{name:"Speak with Animals", nivel:1, edicion:"ambas", etiquetas:["utilidad"], escuela:"Adivinación", tiempo:"1 Acción", alcance:"Personal", componentes:"V, S", duracion:"10 minutos", clases:["Bardo","Druida","Ranger"], desc2024:"Durante 10 minutos comprendés y te comunicás verbalmente con bestias, y además podés usar con ellas cualquiera de las opciones de habilidad de la acción Influir. La mayoría tiene poco que decir fuera de la supervivencia o la compañía, pero como mínimo puede darte información sobre lugares y monstruos cercanos y lo que percibió en el último día. En 2024 también es conjuro de Brujo.", desc:"Ganás la capacidad de comprender bestias y comunicarte con ellas con palabras simples e ideas."},
{name:"Thunderwave", nivel:1, edicion:"ambas", etiquetas:["daño","trueno","salvación"], escuela:"Evocación", tiempo:"1 Acción", alcance:"Personal (cubo 15 ft)", componentes:"V, S", duracion:"Instantáneo", clases:["Bardo","Druida","Hechicero","Mago"], desc:"Una onda de fuerza tonante emana de vos; cada criatura en un cubo de 15 ft hace salvación de Constitución, sufriendo 2d8 daño de trueno (mitad si salva) y siendo empujada 10 ft."},
{name:"Bless", nivel:1, edicion:"ambas", etiquetas:["buff"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, S, M (gota de agua bendita)", duracion:"Conc., hasta 1 min", clases:["Clérigo","Paladín"], desc:"Hasta 3 criaturas a tu elección suman 1d4 a sus tiradas de ataque y salvaciones mientras dure el conjuro.", buff:{activo:false, efectos:[{tipo:"dado", objetivo:"ataque", dado:{count:1, sides:4}}, {tipo:"dado", objetivo:"salvaciones", dado:{count:1, sides:4}}]}},
{name:"Burning Hands", nivel:1, edicion:"ambas", etiquetas:["daño","fuego","salvación"], escuela:"Evocación", tiempo:"1 Acción", alcance:"Personal (cono 15 ft)", componentes:"V, S", duracion:"Instantáneo", clases:["Hechicero","Mago"], desc:"Cada criatura en un cono de 15 ft hace salvación de Destreza, sufriendo 3d6 daño de fuego (mitad si salva); enciende objetos inflamables no equipados."},
{name:"Guiding Bolt", nivel:1, edicion:"ambas", etiquetas:["daño","radiante","ataque"], escuela:"Evocación", tiempo:"1 Acción", alcance:"120 ft", componentes:"V, S", duracion:"1 turno", clases:["Clérigo"], desc:"Ataque de conjuro a distancia; en un impacto, 4d6 daño radiante, y el próximo ataque contra el objetivo antes del final de tu próximo turno tiene ventaja."},
{name:"Command", nivel:1, edicion:"ambas", etiquetas:["control"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"60 ft", componentes:"V", duracion:"1 turno", clases:["Clérigo","Paladín"], desc2024:"En 2024 la duración es Instantáneo, se suma el Bardo y desaparecen las restricciones (no afecta a no-muertos, que no entiendan tu idioma o que la orden los dañe) y las órdenes libres. Decís una orden de una palabra a una criatura que veas en alcance; hace salvación de Sabiduría o la cumple en su próximo turno. Opciones: Approach (se acerca por la ruta más directa y termina su turno si queda a 5 ft), Drop (suelta lo que sostiene y termina su turno), Flee (gasta su turno alejándose lo más rápido posible), Grovel (queda Derribada y termina su turno), Halt (en su turno no se mueve ni realiza acciones ni acciones adicionales). A niveles superiores: afectás a una criatura adicional por cada nivel de espacio por encima de 1.", desc:"Una criatura que pueda oírte hace salvación de Sabiduría o obedece una orden de una sola palabra en su próximo turno (Acercarse, Soltar, Caer, Huir, Detenerse)."},
{name:"Absorb Elements", nivel:1, etiquetas:["buff"], escuela:"Abjuración", tiempo:"1 Reacción", alcance:"Personal", componentes:"S", duracion:"1 turno", clases:["Druida","Ranger","Hechicero","Mago"], desc:"Al recibir daño de ácido/frío/fuego/rayo/trueno, ganás resistencia a ese tipo hasta el final del conjuro; tu próximo golpe cuerpo a cuerpo antes del final de tu próximo turno agrega 1d6 de ese daño."},
{name:"Disguise Self", nivel:1, edicion:"ambas", etiquetas:["ilusión"], escuela:"Ilusión", tiempo:"1 Acción", alcance:"Personal", componentes:"V, S", duracion:"1 hora", clases:["Bardo","Hechicero","Mago"], desc2024:"En 2024 el conjuro dura 1 hora y no se puede descartar con una acción; podés parecer más pesado o más liviano (no más delgado/grueso) y debés adoptar una forma con la misma disposición básica de miembros. Para descubrir el disfraz, una criatura debe usar la acción Estudiar para inspeccionar tu apariencia y superar una prueba de Inteligencia (Investigación) contra tu CD de conjuros.", desc:"Alterás tu apariencia (incluyendo ropa/equipo) hasta el final de la duración o hasta usar una acción para descartarlo; una investigación activa puede detectar el engaño."},
{name:"Alarm", nivel:1, edicion:"ambas", etiquetas:["utilidad"], escuela:"Abjuración", tiempo:"1 minuto", alcance:"30 ft", componentes:"V, S, M (campanita e hilo de plata)", duracion:"8 horas", clases:["Ranger","Mago"], desc:"Marcás un área de hasta 20 ft de cubo; si una criatura Diminuta o mayor (es decir, cualquiera) entra sin permiso, recibís una alerta mental (audible si estás a 1 milla) o suena una campana (si es audible)."},
{name:"Heroism", nivel:1, edicion:"ambas", etiquetas:["buff"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S", duracion:"Conc., hasta 1 min", clases:["Bardo","Paladín"], desc2024:"Una criatura voluntaria tocada es inmune a la condición Asustado y gana PG temporales iguales a tu modificador de característica de lanzamiento al comienzo de cada uno de sus turnos (hasta 1 minuto, concentración). A niveles superiores: una criatura adicional por cada nivel de espacio por encima de 1.", desc:"Una criatura voluntaria tocada es inmune al miedo y gana HP temporales igual a tu mod. de característica de lanzamiento al comienzo de cada uno de sus turnos."},
{name:"Compelled Duel", nivel:1, etiquetas:["control"], escuela:"Encantamiento", tiempo:"1 Acción Adicional", alcance:"30 ft", componentes:"V", duracion:"Conc., hasta 1 min", clases:["Paladín"], desc:"Desafiás a una criatura (salvación de Sabiduría); si falla, tiene desventaja en ataques contra cualquiera que no seas vos y debe hacer una nueva salvación para alejarse más de 30 ft de vos."},
{name:"Magic Missile", nivel:1, edicion:"ambas", etiquetas:["daño","fuerza"], escuela:"Evocación", tiempo:"1 Acción", alcance:"120 ft", componentes:"V, S", duracion:"Instantáneo", clases:["Hechicero","Mago"], desc:"Creás 3 dardos de fuerza brillante que impactan automáticamente, 1d4+1 daño de fuerza cada uno (repartibles entre objetivos; +1 dardo por nivel de espacio usado sobre el 1º)."},
{name:"Shield", nivel:1, edicion:"ambas", etiquetas:["buff"], escuela:"Abjuración", tiempo:"1 Reacción", alcance:"Personal", componentes:"V, S", duracion:"1 turno", clases:["Hechicero","Mago"], desc:"Al ser atacado o alcanzado por Magic Missile, ganás +5 a la CA hasta el inicio de tu próximo turno (incluyendo contra el ataque que lo activó) e inmunidad a Magic Missile.", buff:{activo:false, efectos:[{tipo:"plano", objetivo:"ca", valor:5}]}},
{name:"Armor of Agathys", nivel:1, etiquetas:["buff","daño","frío"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"Personal", componentes:"V, S, M (agua helada o escarcha)", duracion:"1 hora", clases:["Brujo"], desc:"Ganás 5 HP temporales; mientras duren, cualquier criatura que te golpee cuerpo a cuerpo sufre 5 daño de frío (escala con nivel de espacio usado)."},
{name:"Hex", nivel:1, edicion:"2024", etiquetas:["buff","daño","necrótico"], escuela:"Encantamiento", tiempo:"1 Acción Adicional", alcance:"90 ft", componentes:"V, S, M (cráneo de animal pequeño)", duracion:"Conc., hasta 1 hora", clases:["Brujo"], desc:"Maldecís a una criatura: tus ataques contra ella agregan 1d6 daño necrótico, y elegís una característica en la que tiene desventaja en pruebas.", buff:{activo:false, efectos:[{tipo:"dado", objetivo:"dano", dado:{count:1, sides:6}}]}},
{name:"Sleep", nivel:1, edicion:"ambas", etiquetas:["control"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"90 ft", componentes:"V, S, M (arena, pétalos o un grillo)", duracion:"1 minuto", clases:["Bardo","Hechicero","Mago"], desc2024:"En 2024: alcance 60 ft, requiere concentración (hasta 1 min). Cada criatura a elección en una esfera de 5 ft de radio hace salvación de Sabiduría o queda Incapacitada hasta el final de su próximo turno, cuando repite la salvación; si falla la segunda, queda Inconsciente por la duración. Termina en un objetivo si recibe daño o alguien a 5 ft usa una acción para sacudirlo. Las criaturas que no duermen (como los elfos) o inmunes al Agotamiento superan la salvación automáticamente. Ya no usa una reserva de PG.", desc:"Tirás 5d8; las criaturas en un radio de 20 ft (de menor a mayor HP actual) quedan dormidas hasta cubrir ese total de HP o hasta que algo las despierte."},
{name:"Hunter's Mark", nivel:1, edicion:"ambas", etiquetas:["buff","daño"], escuela:"Adivinación", tiempo:"1 Acción Adicional", alcance:"90 ft", componentes:"V", duracion:"Conc., hasta 1 hora", clases:["Ranger"], desc2024:"Marcás a una criatura que veas a 90 ft; mientras dure (concentración, hasta 1 hora), le hacés 1d6 de daño de fuerza extra cada vez que la impactás con una tirada de ataque (cualquiera), y tenés ventaja en pruebas de Sabiduría (Percepción o Supervivencia) para hallarla. Si baja a 0 PG, con una acción adicional movés la marca a otra criatura que veas a 90 ft. Con espacio de nivel 3-4 la concentración dura hasta 8 horas; con nivel 5+, hasta 24 horas.", desc:"Marcás una criatura; tus ataques de arma contra ella agregan 1d6 daño extra, y tenés ventaja en pruebas de Sabiduría (Percepción)/Supervivencia para rastrearla.", buff:{activo:false, efectos:[{tipo:"dado", objetivo:"dano", dado:{count:1, sides:6}}]}},
{name:"Web", nivel:1, edicion:"ambas", etiquetas:["control","salvación"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S, M (telaraña)", duracion:"Conc., hasta 1 hora", clases:["Hechicero","Mago"], desc2024:"Telarañas pegajosas llenan un cubo de 20 ft a 60 ft (terreno difícil, zona poco oscurecida; si no están ancladas, el conjuro termina al inicio de tu próximo turno). La primera vez en un turno que una criatura entra o empieza su turno ahí, debe superar una salvación de Destreza o queda Apresada; puede usar una acción para una prueba de Fuerza (Atletismo) contra tu CD y liberarse. Las telarañas son inflamables: un cubo de 5 ft expuesto al fuego arde en 1 asalto y causa 2d4 de daño de fuego a quien empiece su turno en él.", desc:"Telarañas gruesas llenan un cubo de 20 ft (terreno difícil, inflamable); las criaturas ahí hacen salvación de Destreza o quedan apresadas."},
{name:"Dissonant Whispers", nivel:1, edicion:"2024", etiquetas:["daño","psíquico","salvación"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"60 ft", componentes:"V", duracion:"Instantáneo", clases:["Bardo"], desc:"Susurrás una frase discordante; el objetivo hace salvación de Sabiduría, sufre 3d6 daño psíquico (mitad si salva) y debe usar su reacción para alejarse de vos lo más posible."},
{name:"Bane", nivel:1, edicion:"ambas", etiquetas:["control", "salvación"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, S, M (una gota de sangre)", duracion:"Conc., hasta 1 min", clases:["Bardo", "Clérigo"], desc:"Hasta tres criaturas a tu elección que veas a tu alcance hacen una salvación de Carisma. Cada vez que un objetivo que falló la salvación haga una tirada de ataque o de salvación antes de que termine el hechizo, debe tirar 1d4 y restar el resultado de esa tirada. A niveles superiores: afectás a una criatura adicional por cada nivel de espacio por encima de 1.", desc2024:"En 2024 el hechizo también está en la lista de Brujo. Hasta tres criaturas a tu elección que veas a tu alcance hacen cada una una salvación de Carisma. Cada vez que un objetivo que falló la salvación haga una tirada de ataque o de salvación antes de que termine el hechizo, resta 1d4 de esa tirada. A niveles superiores: una criatura adicional por cada nivel de espacio por encima de 1."},
{name:"Chromatic Orb", nivel:1, edicion:"2024", etiquetas:["daño", "ataque", "ácido", "frío", "fuego", "rayo", "veneno", "trueno"], escuela:"Evocación", tiempo:"1 Acción", alcance:"90 ft", componentes:"V, S, M (un diamante que valga 50+ po)", duracion:"Instantáneo", clases:["Hechicero", "Mago"], desc:"Lanzás una esfera de energía a un objetivo a tu alcance: elegís ácido, frío, fuego, relámpago, veneno o trueno y hacés una tirada de ataque de conjuro a distancia. Si impacta, sufre 3d8 daño del tipo elegido. Si sacás el mismo número en dos o más d8, la esfera salta a otro objetivo a tu elección a 30 ft del primero (nueva tirada de ataque y de daño); no puede saltar de nuevo salvo que uses un espacio de nivel 2+. A niveles superiores: +1d8 por nivel de espacio sobre 1. La esfera puede saltar un máximo de veces igual al nivel del espacio gastado, y una criatura solo puede ser objetivo una vez por lanzamiento."},
{name:"Color Spray", nivel:1, edicion:"ambas", etiquetas:["control", "ilusión"], escuela:"Ilusión", tiempo:"1 Acción", alcance:"Personal (cono de 15 ft)", componentes:"V, S, M (una pizca de polvo o arena de color rojo, amarillo y azul)", duracion:"1 turno", clases:["Hechicero", "Mago"], desc:"Un despliegue deslumbrante de luces de colores brota de tu mano. Tirás 6d10: el total es la cantidad de PG de criaturas que el conjuro puede afectar. Las criaturas en un cono de 15 ft que nace de vos se afectan en orden ascendente de PG actuales (ignorando inconscientes y las que no pueden ver). Empezando por la de menos PG, cada criatura afectada queda Cegada hasta que termine el conjuro; restá sus PG del total antes de pasar a la siguiente, y los PG de una criatura deben ser iguales o menores al total restante para afectarla. A niveles superiores: tirás 2d10 adicionales por cada nivel de espacio por encima del 1.º.", desc2024:"En 2024 ya no se tiran PG: cada criatura en un cono de 15 ft que nace de vos debe superar una tirada de salvación de Constitución o queda Cegada hasta el final de tu siguiente turno. Es instantáneo (sin escalado) y también está en la lista del Bardo."},
{name:"Comprehend Languages", nivel:1, edicion:"ambas", etiquetas:["adivinación", "utilidad"], escuela:"Adivinación", tiempo:"1 Acción (ritual)", alcance:"Personal", componentes:"V, S, M (una pizca de hollín y sal)", duracion:"1 hora", clases:["Bardo", "Hechicero", "Brujo", "Mago"], desc:"Durante 1 hora entendés el significado literal de cualquier idioma hablado que oigas, y de cualquier idioma escrito que veas si tocás la superficie donde está escrito (unos 1 minuto por página). No descifra mensajes secretos ni glifos como un sigilo arcano que no sean parte de un idioma escrito.", desc2024:"En 2024: además de los idiomas hablados, entendés el significado literal de cualquier idioma que veas hecho con señas. La lectura de textos sigue requiriendo tocar la superficie (1 minuto por página). No descifra símbolos ni mensajes secretos."},
{name:"Detect Evil and Good", nivel:1, edicion:"ambas", etiquetas:["adivinación", "utilidad"], escuela:"Adivinación", tiempo:"1 Acción", alcance:"Personal", componentes:"V, S", duracion:"Conc., hasta 10 min", clases:["Clérigo", "Paladín"], desc:"Mientras dure, sabés si hay una aberración, celestial, elemental, feérico, infernal o muerto viviente a 30 ft de vos y dónde está. También sabés si hay un lugar u objeto a 30 ft consagrado o profanado mágicamente. Lo bloquean 1 ft de piedra, 1 pulgada de metal común, una lámina fina de plomo o 3 ft de madera o tierra.", desc2024:"En 2024: detectás la ubicación de aberraciones, celestiales, elementales, feéricos, infernales y muertos vivientes a 30 ft, y percibís si el conjuro Hallow está activo ahí y dónde. Lo bloquean 1 ft de piedra, tierra o madera, 1 pulgada de metal o una lámina fina de plomo."},
{name:"Divine Favor", nivel:1, edicion:"ambas", etiquetas:["buff", "daño", "radiante", "arma"], escuela:"Evocación", tiempo:"1 Acción Adicional", alcance:"Personal", componentes:"V, S", duracion:"Conc., hasta 1 min", clases:["Paladín"], desc:"Tu plegaria te llena de radiante poder divino. Hasta que termine el conjuro, tus ataques con arma infligen 1d4 de daño radiante adicional al impactar.", desc2024:"En 2024: es de escuela Transmutación y ya no requiere concentración; dura 1 minuto. Tus ataques con arma infligen 1d4 de daño radiante adicional al impactar."},
{name:"Divine Smite", nivel:1, edicion:"2024", etiquetas:["daño", "radiante", "arma"], escuela:"Evocación", tiempo:"1 Acción Adicional", alcance:"Personal", componentes:"V", duracion:"Instantáneo", clases:["Paladín"], desc:"Se lanza como acción adicional inmediatamente después de impactar a un objetivo con un arma cuerpo a cuerpo o un Golpe Sin Armas. El objetivo sufre 2d8 de daño radiante adicional por el ataque; el daño aumenta en 1d8 si el objetivo es un Infernal o un No-muerto. A niveles superiores: +1d8 por cada nivel de espacio por encima de 1."},
{name:"Ensnaring Strike", nivel:1, edicion:"2024", etiquetas:["control", "salvación", "daño", "perforante", "arma"], escuela:"Conjuración", tiempo:"1 Acción Adicional (justo después de golpear a una criatura con un arma)", alcance:"Personal", componentes:"V", duracion:"Conc., hasta 1 min", clases:["Ranger"], desc:"Al impactar, enredaderas aferran al objetivo, que hace salvación de Fuerza (ventaja si es Grande o mayor). Si falla, queda Apresado hasta que termine el conjuro; si salva, las enredaderas se marchitan y el conjuro termina. Apresado, sufre 1d6 daño perforante al inicio de cada uno de sus turnos. El objetivo o una criatura a su alcance puede usar una acción para una prueba de Fuerza (Atletismo) contra tu CD de conjuro; si la supera, el conjuro termina. A niveles superiores: +1d6 de daño por cada nivel de espacio por encima de 1."},
{name:"Expeditious Retreat", nivel:1, edicion:"ambas", etiquetas:["buff", "utilidad"], escuela:"Transmutación", tiempo:"1 Acción Adicional", alcance:"Personal", componentes:"V, S", duracion:"Conc., hasta 10 min", clases:["Hechicero", "Brujo", "Mago"], desc:"Te movés a un ritmo increíble: al lanzarlo, y luego como acción adicional en cada uno de tus turnos mientras dure, podés realizar la acción Correr."},
{name:"False Life", nivel:1, edicion:"ambas", etiquetas:["buff", "protección"], escuela:"Necromancia", tiempo:"1 Acción", alcance:"Personal", componentes:"V, S, M (una pequeña cantidad de alcohol o licor destilado)", duracion:"1 hora", clases:["Hechicero", "Mago"], desc:"Fortalecido por un facsímil nigromántico de vida, ganás 1d4 + 4 PG temporales durante la duración. A niveles superiores: ganás 5 PG temporales adicionales por cada nivel de espacio por encima del 1.º.", desc2024:"En 2024 ganás 2d4 + 4 PG temporales (el conjuro es instantáneo, sin duración). A niveles superiores: 5 PG temporales adicionales por cada nivel de espacio por encima del 1.º."},
{name:"Feather Fall", nivel:1, edicion:"ambas", etiquetas:["protección", "utilidad"], escuela:"Transmutación", tiempo:"1 Reacción", alcance:"60 ft", componentes:"V, M (una pluma pequeña o un poco de plumón)", duracion:"1 minuto", clases:["Bardo", "Hechicero", "Mago"], desc:"Reacción cuando vos o una criatura que veas a 60 ft cae. Elegís hasta cinco criaturas que caen dentro del alcance: su velocidad de descenso baja a 60 ft por asalto hasta que termine el hechizo. Si una criatura aterriza antes de que termine, no sufre daño por caída (y puede caer de pie) y el hechizo termina para ella."},
{name:"Find Familiar", nivel:1, edicion:"ambas", etiquetas:["invocación", "utilidad"], escuela:"Conjuración", tiempo:"1 hora (ritual)", alcance:"10 ft", componentes:"V, S, M (10 gp de carbón, incienso y hierbas que se consumen en un brasero de latón)", duracion:"Instantáneo", clases:["Mago"], desc:"Obtenés un familiar, un espíritu con forma animal a elección (murciélago, gato, cangrejo, rana, halcón, lagarto, pulpo, búho, serpiente venenosa, pez, rata, cuervo, caballito de mar, araña o comadreja) con sus estadísticas, pero Celestial, Feérico o Infernal. Actúa por su cuenta pero obedece, tira su propia iniciativa y no puede atacar. A 0 PG desaparece y reaparece al relanzar el conjuro. A menos de 100 ft hay comunicación telepática; con una acción ves y oís por él hasta tu próximo turno (quedás ciego y sordo para tus sentidos). Podés descartarlo temporal o definitivamente, y hacerlo reaparecer con una acción a 30 ft. Solo un familiar; relanzarlo cambia su forma. Puede entregar conjuros de toque usando su reacción (a menos de 100 ft).", desc2024:"En 2024: la lista de formas incluye Murciélago, Gato, Rana, Halcón, Lagarto, Pulpo, Búho, Rata, Cuervo, Araña, Comadreja u otra Bestia de CR 0. Ver por sus ojos cuesta una acción adicional; descartarlo y hacerlo reaparecer usa la acción Magia. El material es incienso encendido de 10+ gp que el conjuro consume. Es tu aliado, tira su iniciativa, no ataca y puede entregar conjuros de toque con su reacción (a menos de 100 ft). Al desaparecer deja lo que llevaba."},
{name:"Floating Disk", nivel:1, edicion:"ambas", etiquetas:["invocación", "utilidad"], escuela:"Conjuración", tiempo:"1 Acción (ritual)", alcance:"30 ft", componentes:"V, S, M (una gota de mercurio)", duracion:"1 hora", clases:["Mago"], desc:"Creás un plano de fuerza circular y horizontal de 3 ft de diámetro y 1 pulgada de grosor que flota 3 ft sobre el suelo en un espacio libre que veas a tu alcance. Aguanta hasta 500 libras; si se le pone más peso, el hechizo termina y todo cae. Permanece inmóvil mientras estés a 20 ft o menos; si te alejás más, te sigue para quedar a 20 ft de vos. Cruza terreno irregular, escaleras y pendientes, pero no desniveles de 10 ft o más (no cruza ni sale de un foso de 10 ft). Si te alejás más de 100 ft del disco, el hechizo termina."},
{name:"Grease", nivel:1, edicion:"ambas", etiquetas:["control", "invocación"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S, M (un trozo de cuero de cerdo o manteca)", duracion:"1 minuto", clases:["Mago"], desc:"Grasa resbaladiza cubre el suelo en un cuadrado de 10 ft centrado en un punto del alcance y lo vuelve terreno difícil. Al aparecer, cada criatura en el área hace salvación de Destreza o cae Derribada; también la hace cualquier criatura que entre al área o termine su turno ahí.", desc2024:"En 2024: la grasa es ininflamable y también la aprende el Hechicero; el resto funciona igual (cuadrado de 10 ft, terreno difícil, salvación de Destreza o Derribado al aparecer, al entrar y al terminar el turno ahí)."},
{name:"Hellish Rebuke", nivel:1, edicion:"ambas", etiquetas:["daño", "fuego", "salvación"], escuela:"Evocación", tiempo:"1 Reacción", alcance:"60 ft", componentes:"V, S", duracion:"Instantáneo", clases:["Brujo"], desc:"Reacción al recibir daño de una criatura que veas a 60 ft: la envolvés momentáneamente en llamas infernales y hace salvación de Destreza, sufriendo 2d10 daño de fuego (mitad si salva). A niveles superiores: +1d10 de daño por cada nivel de espacio por encima de 1."},
{name:"Hideous Laughter", nivel:1, edicion:"ambas", etiquetas:["control", "salvación"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, S, M (pastelitos diminutos y una pluma que se agita en el aire)", duracion:"Conc., hasta 1 min", clases:["Bardo", "Mago"], desc:"Una criatura que veas a alcance percibe todo como graciosísimo y cae en ataques de risa: hace salvación de Sabiduría o queda Derribada e Incapacitada y no puede levantarse mientras dure. Las criaturas con Inteligencia 4 o menos no se ven afectadas. Al final de cada uno de sus turnos y cada vez que sufre daño, repite la salvación (con ventaja si fue por daño); si la supera, el conjuro termina.", desc2024:"En 2024 también está en la lista de Brujo, ya no excluye a criaturas con Inteligencia 4 o menos y escala. Una criatura que veas a alcance hace salvación de Sabiduría; si falla, queda Derribada e Incapacitada mientras dure, ríe sin control si puede reír y no puede ponerse de pie por sí misma. Al final de cada uno de sus turnos y cada vez que sufre daño repite la salvación (con ventaja si fue por daño); si la supera, el conjuro termina. A niveles superiores: podés elegir una criatura adicional por cada nivel de espacio por encima de 1."},
{name:"Ice Knife", nivel:1, edicion:"2024", etiquetas:["daño", "perforante", "frío", "ataque", "salvación"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"60 ft", componentes:"S, M (una gota de agua o un trozo de hielo)", duracion:"Instantáneo", clases:["Druida", "Hechicero", "Mago"], desc:"Creás una astilla de hielo y la arrojás a una criatura en alcance: tirada de ataque de conjuro a distancia; con impacto sufre 1d10 daño perforante. Acierte o falle, la astilla estalla: el objetivo y cada criatura a 5 ft de él hacen salvación de Destreza o sufren 2d6 daño de frío. A niveles superiores: el daño de frío sube 1d6 por cada nivel de espacio por encima de 1."},
{name:"Identify", nivel:1, edicion:"ambas", etiquetas:["adivinación", "utilidad"], escuela:"Adivinación", tiempo:"1 minuto (ritual)", alcance:"Toque", componentes:"V, S, M (una perla que valga al menos 100 po y una pluma de búho)", duracion:"Instantáneo", clases:["Bardo", "Mago"], desc:"Tocás un objeto durante todo el lanzamiento. Si es un objeto mágico o imbuido de magia, conocés sus propiedades y cómo usarlas, si requiere sintonización y cuántas cargas tiene; también qué conjuros lo afectan y, si fue creado por un conjuro, cuál. Si en cambio tocás a una criatura, sabés qué conjuros la están afectando."},
{name:"Illusory Script", nivel:1, edicion:"ambas", etiquetas:["ilusión", "utilidad"], escuela:"Ilusión", tiempo:"1 minuto (ritual)", alcance:"Toque", componentes:"S, M (tinta a base de plomo valuada en al menos 10 po, que el conjuro consume)", duracion:"10 días", clases:["Bardo", "Brujo", "Mago"], desc:"Escribís sobre pergamino, papel u otro material adecuado e imbuís el texto con una ilusión que dura toda la duración. Para vos y las criaturas que designes al lanzarlo, la escritura parece normal, de tu puño y letra, y transmite lo que quisiste. Para todos los demás parece escrita en un alfabeto desconocido o mágico, ininteligible; o podés hacerla parecer un mensaje totalmente distinto, con otra letra y otro idioma que conozcas. Si se disipa el conjuro, desaparecen el texto original y la ilusión. Una criatura con visión verdadera puede leer el mensaje oculto."},
{name:"Inflict Wounds", nivel:1, edicion:"ambas", etiquetas:["daño", "necrótico", "ataque", "salvación"], escuela:"Necromancia", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S", duracion:"Instantáneo", clases:["Clérigo"], desc:"Hacés una tirada de ataque de conjuro cuerpo a cuerpo contra una criatura a tu alcance; si impacta, sufre 3d10 daño necrótico. A niveles superiores: +1d10 de daño por cada nivel de espacio por encima de 1.", desc2024:"En 2024 ya no hay tirada de ataque: la criatura que tocás hace salvación de Constitución y sufre 2d10 daño necrótico (mitad si salva). A niveles superiores: +1d10 de daño por cada nivel de espacio por encima de 1."},
{name:"Mage Armor", nivel:1, edicion:"ambas", etiquetas:["protección", "buff"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S, M (un trozo de cuero curtido)", duracion:"8 horas", clases:["Hechicero", "Mago"], desc:"Tocás a una criatura voluntaria que no lleve armadura; una fuerza mágica protectora la rodea y su CA base pasa a ser 13 + su modificador de Destreza. El conjuro termina si el objetivo se pone una armadura o si lo disipás con una acción."},
{name:"Protection from Evil and Good", nivel:1, edicion:"ambas", etiquetas:["protección", "buff"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S, M (agua bendita, o plata y hierro en polvo, que el hechizo consume)", duracion:"Conc., hasta 10 min", clases:["Clérigo", "Paladín", "Brujo", "Mago"], desc:"Una criatura voluntaria que tocás queda protegida contra aberraciones, celestiales, elementales, feéricos, infernales y muertos vivientes. Esas criaturas tienen desventaja en sus tiradas de ataque contra el objetivo, y este no puede ser hechizado, asustado ni poseído por ellas. Si ya lo estaba, tiene ventaja en cualquier nueva salvación contra ese efecto.", desc2024:"En 2024: el material pasa a ser un frasco de agua bendita de al menos 25 po, que el hechizo consume, y también lo aprende el Druida; la protección es la misma (desventaja para atacar al objetivo y no puede ser poseído, Hechizado ni Asustado por esas criaturas)."},
{name:"Ray of Sickness", nivel:1, edicion:"2024", etiquetas:["daño", "veneno", "ataque", "control"], escuela:"Necromancia", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S", duracion:"Instantáneo", clases:["Hechicero", "Mago"], desc:"Disparás un rayo verdoso a una criatura a tu alcance. Hacés una tirada de ataque de conjuro a distancia: si impacta, el objetivo sufre 2d8 daño de veneno y queda Envenenado hasta el final de tu siguiente turno. A niveles superiores: el daño aumenta en 1d8 por cada nivel de espacio por encima del 1.º."},
{name:"Sanctuary", nivel:1, edicion:"ambas", etiquetas:["protección", "salvación"], escuela:"Abjuración", tiempo:"1 Acción Adicional", alcance:"30 ft", componentes:"V, S, M (un pequeño espejo de plata)", duracion:"1 minuto", clases:["Clérigo"], desc:"Protegés a una criatura en alcance. Hasta que termine, cualquier criatura que la apunte con un ataque o un hechizo dañino debe hacer antes una salvación de Sabiduría; si falla, debe elegir un nuevo objetivo o pierde el ataque o hechizo. No protege contra efectos de área (como la explosión de una bola de fuego). Si la criatura protegida ataca o lanza un hechizo que afecta a una criatura enemiga, el hechizo termina.", desc2024:"En 2024 el material es un trozo de vidrio de un espejo, y protege contra quien la apunte con una tirada de ataque o un hechizo que cause daño (salvación de Sabiduría o elige otro objetivo o pierde el ataque/hechizo); no protege contra áreas de efecto. Termina si la criatura protegida hace una tirada de ataque, lanza un hechizo o inflige daño."},
{name:"Searing Smite", nivel:1, edicion:"2024", etiquetas:["daño", "fuego", "salvación", "arma"], escuela:"Evocación", tiempo:"1 Acción Adicional (justo después de impactar con un arma cuerpo a cuerpo o un ataque sin armas)", alcance:"Personal", componentes:"V", duracion:"1 minuto", clases:["Paladín"], desc:"Al impactar, el objetivo sufre 1d6 de daño de fuego adicional por el ataque. Al comienzo de cada uno de sus turnos hasta que termine el conjuro, sufre 1d6 de daño de fuego y hace una salvación de Constitución: si falla, el conjuro continúa; si la supera, termina. A niveles superiores: todo el daño aumenta 1d6 por cada nivel de espacio por encima de 1."},
{name:"Shield of Faith", nivel:1, edicion:"ambas", etiquetas:["protección", "buff"], escuela:"Abjuración", tiempo:"1 Acción Adicional", alcance:"60 ft", componentes:"V, S, M (un pequeño pergamino con un fragmento de texto sagrado escrito)", duracion:"Conc., hasta 10 min", clases:["Clérigo", "Paladín"], desc:"Un campo reluciente rodea a una criatura a tu elección a alcance, otorgándole un bonificador de +2 a la CA mientras dure."},
{name:"Silent Image", nivel:1, edicion:"ambas", etiquetas:["ilusión"], escuela:"Ilusión", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S, M (un trozo de vellón)", duracion:"Conc., hasta 10 min", clases:["Bardo", "Hechicero", "Mago"], desc:"Creás la imagen de un objeto, criatura u otro fenómeno visible, no mayor que un cubo de 15 ft, en un punto a 60 ft. Es puramente visual (sin sonido, olor ni otros efectos). Con tu acción podés moverla a otro punto del alcance, adaptando su aspecto para que el movimiento parezca natural. La interacción física revela que es una ilusión; una criatura que use su acción para examinarla la descubre con una prueba de Inteligencia (Investigación) contra tu CD, y entonces ve a través de ella."},
{name:"Unseen Servant", nivel:1, edicion:"ambas", etiquetas:["invocación", "utilidad"], escuela:"Conjuración", tiempo:"1 Acción (ritual)", alcance:"60 ft", componentes:"V, S, M (un trozo de cuerda y un poco de madera)", duracion:"1 hora", clases:["Bardo", "Brujo", "Mago"], desc:"Creás una fuerza invisible, sin mente ni forma que cumple tareas simples hasta que termine el hechizo. Aparece en un espacio libre del suelo en alcance; tiene CA 10, 1 PG y Fuerza 2, y no puede atacar (a 0 PG el hechizo termina). Una vez por turno, como acción adicional, le ordenás mentalmente moverse hasta 15 ft e interactuar con un objeto: traer cosas, limpiar, remendar, doblar ropa, encender fuegos, servir comida y vino. Si la tarea lo alejaría más de 60 ft de vos, el hechizo termina."},

// ===== NIVEL 2 =====
{name:"Animal Messenger", nivel:2, edicion:"ambas", etiquetas:["utilidad"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, S, M (golosina)", duracion:"24 horas (o más, según nivel de espacio)", clases:["Bardo","Druida","Ranger"], desc2024:"Una Bestia Diminuta que veas a 30 ft debe superar una salvación de Carisma o intenta entregar tu mensaje (si su VD no es 0, supera la salvación automáticamente). Indicás un lugar que hayas visitado y un destinatario según una descripción general, y un mensaje de hasta 25 palabras. Viaja 24 horas: unas 25 mi, o 50 mi si vuela. Al llegar entrega el mensaje imitando tu comunicación; si no llega antes de que termine el conjuro, el mensaje se pierde y vuelve a donde lo lanzaste. A niveles superiores: la duración aumenta 48 horas por nivel sobre el 2º.", desc:"Un animal diminuto voluntario lleva un mensaje de hasta 25 palabras a un lugar/destino que describís."},
{name:"Barkskin", nivel:2, edicion:"ambas", etiquetas:["buff"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S, M (un poco de corteza)", duracion:"Conc., hasta 1 hora", clases:["Druida","Ranger"], desc2024:"En 2024 se lanza como acción adicional, dura 1 hora sin requerir concentración, y la criatura voluntaria tocada tiene CA 17 si su CA es menor (en vez de un mínimo de 16).", desc:"La piel de la criatura tocada se endurece; su CA no puede ser menor a 16, sin importar armadura."},
{name:"Darkvision", nivel:2, edicion:"ambas", etiquetas:["buff"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S, M (zanahoria seca o ágata pulida)", duracion:"8 horas", clases:["Druida","Ranger","Hechicero","Mago"], desc2024:"En 2024 la criatura voluntaria que tocás obtiene visión en la oscuridad con alcance de 150 ft (en vez de 60 ft) durante 8 horas.", desc:"La criatura tocada gana visión en la oscuridad a 60 ft durante la duración."},
{name:"Enhance Ability", nivel:2, edicion:"ambas", etiquetas:["buff"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S, M (pluma, piel de gato o grillo)", duracion:"Conc., hasta 1 hora", clases:["Bardo","Clérigo","Druida","Hechicero"], desc2024:"En 2024 se simplifica: tocás a una criatura y elegís Fuerza, Destreza, Inteligencia, Sabiduría o Carisma; mientras dure, tiene ventaja en las pruebas de característica con esa característica (ya no hay Resistencia del Oso, PG temporales ni capacidad de carga duplicada ni efectos secundarios, y Constitución no se puede elegir). A niveles superiores: una criatura adicional por nivel de espacio por encima de 2, y podés elegir una característica distinta para cada objetivo.", desc:"Otorgás ventaja en pruebas de una característica elegida a la criatura tocada, más un efecto secundario según la característica."},
{name:"Find Traps", nivel:2, edicion:"ambas", etiquetas:["utilidad"], escuela:"Adivinación", tiempo:"1 Acción", alcance:"120 ft", componentes:"V, S", duracion:"Instantáneo", clases:["Clérigo","Druida","Ranger"], desc:"Sentís la presencia de cualquier trampa a tu alcance (mágica o mecánica), aunque no su ubicación exacta."},
{name:"Flame Blade", nivel:2, edicion:"ambas", etiquetas:["daño","fuego","ataque"], escuela:"Evocación", tiempo:"1 Acción Adicional", alcance:"Personal", componentes:"V, S, M (hoja de sumac)", duracion:"Conc., hasta 10 min", clases:["Druida"], desc2024:"En 2024 también la tiene el Hechicero. Evocás una hoja de fuego en tu mano libre (si la soltás desaparece, pero la volvés a evocar con una acción adicional). Como acción de Magia hacés un ataque de conjuro cuerpo a cuerpo: si impacta, daño de fuego igual a 3d6 + tu modificador de característica de lanzamiento. Emite luz brillante en 10 ft y luz tenue 10 ft más. A niveles superiores: el daño aumenta en 1d6 por cada nivel de espacio por encima del 2.º.", desc:"Una hoja de fuego aparece en tu mano; ataque cuerpo a cuerpo con conjuro, 3d6 daño de fuego, ilumina 10 ft."},
{name:"Flaming Sphere", nivel:2, edicion:"ambas", etiquetas:["daño","fuego","salvación"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S, M (cera y mecha)", duracion:"Conc., hasta 1 min", clases:["Druida","Mago"], desc:"Una esfera de fuego de 5 ft aparece; podés moverla 30 ft/turno con acción adicional, chocando con criaturas para 2d6 daño de fuego (salvación de Destreza para mitad)."},
{name:"Gust of Wind", nivel:2, edicion:"ambas", etiquetas:["control"], escuela:"Evocación", tiempo:"1 Acción", alcance:"Personal (línea 60 ft)", componentes:"V, S, M (abanico o pluma)", duracion:"Conc., hasta 1 min", clases:["Druida","Hechicero","Mago"], desc2024:"En 2024: cada criatura que esté en la línea (no solo la que empieza su turno ahí) hace salvación de Fuerza o es empujada 15 ft lejos de vos, y la criatura que termina su turno en la línea repite la salvación. Apaga velas y llamas similares sin protección; las llamas protegidas (faroles) tienen 50% de apagarse. Cambiás la dirección con una acción adicional en tus turnos posteriores. El hechizo también está en la lista de Explorador.", desc:"Una línea de viento de 60x10 ft empuja criaturas (salvación de Fuerza o 15 ft de empuje) y apaga llamas pequeñas en el área."},
{name:"Heat Metal", nivel:2, edicion:"ambas", etiquetas:["daño","fuego"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S, M (imán de hierro)", duracion:"Conc., hasta 1 min", clases:["Druida"], desc:"Un objeto de metal tocado se pone al rojo vivo; quien lo esté tocando sufre 2d8 daño de fuego y debe soltarlo si puede."},
{name:"Hold Person", nivel:2, edicion:"ambas", etiquetas:["control","salvación"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S, M (trozo de hierro forjado)", duracion:"Conc., hasta 1 min", clases:["Bardo","Clérigo","Druida","Hechicero","Brujo","Mago"], desc:"Un humanoide hace salvación de Sabiduría o queda paralizado durante la duración (repite salvación cada turno)."},
{name:"Lesser Restoration", nivel:2, edicion:"ambas", etiquetas:["utilidad"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S", duracion:"Instantáneo", clases:["Bardo","Clérigo","Druida","Paladín","Ranger"], desc2024:"En 2024 se lanza como acción adicional y ya no cura enfermedades: tocás a una criatura y terminás una condición sobre ella (Cegado, Ensordecido, Paralizado o Envenenado).", desc:"Terminás con una enfermedad o una condición (ceguera, sordera, paralizado o envenenado) que afecta a la criatura tocada."},
{name:"Locate Animals or Plants", nivel:2, edicion:"ambas", etiquetas:["utilidad"], escuela:"Adivinación", tiempo:"1 Acción", alcance:"Personal", componentes:"V, S, M (trébol)", duracion:"Instantáneo", clases:["Bardo","Druida","Ranger"], desc:"Sabés la dirección y distancia hacia el ejemplar más cercano de un tipo específico de bestia o planta a 5 millas."},
{name:"Locate Object", nivel:2, edicion:"ambas", etiquetas:["utilidad"], escuela:"Adivinación", tiempo:"1 Acción", alcance:"Personal", componentes:"V, S, M (bifurcación de metal)", duracion:"Conc., hasta 10 min", clases:["Bardo","Clérigo","Druida","Paladín","Ranger","Hechicero","Mago"], desc:"Sentís la dirección hacia un objeto específico (o tipo de objeto) conocido, a 1000 ft."},
{name:"Moonbeam", nivel:2, edicion:"ambas", etiquetas:["daño","radiante","salvación"], escuela:"Evocación", tiempo:"1 Acción", alcance:"120 ft", componentes:"V, S, M (piedra pulida por agua)", duracion:"Conc., hasta 1 min", clases:["Druida"], desc2024:"En 2024 el cilindro (5 ft de radio, 40 ft de alto) aparece con luz tenue y lo movés hasta 60 ft con una acción de Magia en turnos posteriores. Al aparecer, cada criatura dentro hace salvación de Constitución: si falla sufre 2d10 daño radiante (mitad si salva) y, si está transformada (p. ej. por Polymorph), vuelve a su forma verdadera y no puede cambiar de forma hasta salir del cilindro. También hacen la salvación al entrar el área en su espacio, al entrar o al terminar su turno allí, una sola vez por turno. A niveles superiores: +1d10 por cada nivel de espacio por encima de 2.", desc:"Un rayo de luz plateada cae en un cilindro de 5 ft; cada criatura ahí hace salvación de Constitución, sufriendo 2d10 daño radiante (mitad si salva); podés moverlo 60 ft por acción."},
{name:"Pass without Trace", nivel:2, edicion:"ambas", etiquetas:["buff"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"Personal", componentes:"V, S, M (ceniza y hojas de menta)", duracion:"Conc., hasta 1 hora", clases:["Druida","Ranger"], desc2024:"Irradiás un aura de ocultamiento (emanación de 30 ft) durante 1 hora (concentración). Mientras estén en el aura, vos y cada criatura que elijas tienen +10 a las pruebas de Destreza (Sigilo) y no dejan rastros.", desc:"Un manto de sombra rodea a un grupo (30 ft); cada uno gana +10 a pruebas de Destreza (Sigilo) y no puede ser rastreado excepto por medios mágicos."},
{name:"Protection from Poison", nivel:2, edicion:"ambas", etiquetas:["buff"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S", duracion:"1 hora", clases:["Clérigo","Druida","Paladín","Ranger"], desc2024:"Tocás a una criatura y terminás su condición de Envenenado. Durante 1 hora tiene ventaja en las tiradas de salvación para evitar o terminar la condición de Envenenado y resistencia al daño de veneno.", desc:"Neutralizás un veneno en la criatura tocada (o le das ventaja en salvaciones contra veneno y resistencia a daño de veneno durante la duración)."},
{name:"Spike Growth", nivel:2, edicion:"ambas", etiquetas:["daño","perforante","control"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"150 ft", componentes:"V, S, M (siete espinas o astillas)", duracion:"Conc., hasta 10 min", clases:["Druida","Ranger"], desc2024:"En 2024: la zona es una esfera de 20 ft de radio. Una criatura que no vea el área al lanzarlo debe usar la acción Buscar y superar una prueba de Sabiduría (Percepción o Supervivencia) contra tu CD de conjuros para reconocer el terreno como peligroso antes de entrar; el resto no cambia (terreno difícil y 2d4 daño perforante por cada 5 ft recorridos).", desc:"El terreno en un radio de 20 ft se cubre de espinas ocultas; moverse ahí cuesta el cuádruple de movimiento y causa 2d4 daño perforante cada 5 ft recorridos."},
{name:"Aid", nivel:2, edicion:"ambas", etiquetas:["buff"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, S, M (hoja de trébol blanco)", duracion:"8 horas", clases:["Clérigo","Paladín"], desc:"Hasta 3 criaturas suman 5 a su HP máximo y actual durante la duración (escala con nivel de espacio usado).", buff:{activo:false, efectos:[{tipo:"plano", objetivo:"hp-max", valor:5}]}},
{name:"Magic Weapon", nivel:2, edicion:"ambas", etiquetas:["buff"], escuela:"Transmutación", tiempo:"1 Acción Adicional", alcance:"Toque", componentes:"V, S", duracion:"Conc., hasta 1 hora", clases:["Paladín","Hechicero","Mago"], desc2024:"Tocás un arma no mágica: se vuelve mágica con +1 a tiradas de ataque y daño durante 1 hora. En 2024 ya no requiere concentración y termina antes si lo lanzás de nuevo; también lo tienen el Explorador y el Hechicero. El bono sube a +2 con espacio de nivel 3-5 y a +3 con nivel 6+.", desc:"Un arma no mágica tocada se vuelve mágica con +1 a tiradas de ataque y daño (+2 o +3 con espacios superiores).", buff:{activo:false, efectos:[{tipo:"plano", objetivo:"ataque", valor:1}]}},
{name:"Zone of Truth", nivel:2, edicion:"ambas", etiquetas:["control"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S", duracion:"10 minutos", clases:["Bardo","Clérigo","Paladín"], desc:"Creás una zona mágica de 15 ft de radio; las criaturas ahí que fallen una salvación de Carisma no pueden decir mentiras deliberadas dentro de la zona."},
{name:"See Invisibility", nivel:2, edicion:"ambas", etiquetas:["buff"], escuela:"Adivinación", tiempo:"1 Acción", alcance:"Personal", componentes:"V, S, M (talco y plata)", duracion:"1 hora", clases:["Hechicero","Mago"], desc:"Ves criaturas y objetos invisibles como si fueran visibles, y ves dentro del Plano Etéreo."},
{name:"Misty Step", nivel:2, edicion:"ambas", etiquetas:["utilidad","teletransporte"], escuela:"Conjuración", tiempo:"1 Acción Adicional", alcance:"Personal", componentes:"V", duracion:"Instantáneo", clases:["Hechicero","Brujo","Mago"], desc:"Te envolvés en niebla plateada y te teletransportás hasta 30 ft a un espacio libre que puedas ver."},
{name:"Suggestion", nivel:2, edicion:"ambas", etiquetas:["control"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, M (hilo de seda)", duracion:"Conc., hasta 8 horas", clases:["Bardo","Hechicero","Brujo","Mago"], desc2024:"En 2024 sugerís un curso de acción en no más de 25 palabras a una criatura que veas a tu alcance y que pueda oírte y entenderte; debe sonar realizable y no implicar daño evidente al objetivo ni a sus aliados. El objetivo debe superar una tirada de salvación de Sabiduría o queda Hechizado durante la duración o hasta que vos o tus aliados le inflijan daño; sigue la sugerencia lo mejor que pueda, y si la actividad se completa antes, el conjuro termina para él.", desc:"Sugerís un curso de acción razonable a una criatura que pueda oírte (salvación de Sabiduría) o lo sigue durante la duración."},
{name:"Rope Trick", nivel:2, edicion:"ambas", etiquetas:["utilidad"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S, M (polvo de cuerno pulverizado)", duracion:"1 hora", clases:["Mago"], desc:"Una cuerda tocada se para en el aire; subiendo por ella, hasta 8 criaturas Medianas pueden entrar a un espacio extradimensional invisible desde fuera."},
{name:"Acid Arrow", nivel:2, edicion:"ambas", etiquetas:["daño", "ácido", "ataque"], escuela:"Evocación", tiempo:"1 Acción", alcance:"90 ft", componentes:"V, S, M (hoja de ruibarbo en polvo y el estómago de una víbora)", duracion:"Instantáneo", clases:["Mago"], desc:"Una flecha verde reluciente vuela hacia un objetivo en alcance y estalla en un rocío de ácido; ataque de conjuro a distancia. Si impacta, 4d4 de daño de ácido de inmediato y 2d4 de daño de ácido al final de su próximo turno. Si falla, la flecha lo salpica con la mitad del daño inicial y no hay daño posterior. A niveles superiores: el daño (inicial y posterior) aumenta 1d4 por cada nivel de espacio por encima de 2."},
{name:"Alter Self", nivel:2, edicion:"ambas", etiquetas:["buff", "utilidad"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"Personal", componentes:"V, S", duracion:"Conc., hasta 1 hora", clases:["Hechicero", "Mago"], desc:"Asumís otra forma; elegís una opción al lanzarlo y, mientras dure, podés usar una acción para cambiarla por otra. Adaptación acuática: respirás bajo el agua y ganás velocidad de nado igual a tu velocidad al caminar. Cambiar apariencia: decidís tu aspecto (altura, peso, rasgos, voz, etc.), incluso de otra raza, sin cambiar tus estadísticas; no podés cambiar de tamaño ni de forma básica, y podés volver a cambiarla con una acción. Armas naturales: tus golpes sin armas infligen 1d6 contundente, perforante o cortante según el arma elegida (garras, colmillos, cuernos…), sos competente con ellos, son mágicos y tenés +1 a ataque y daño con ellos.", desc2024:"En 2024 usás la acción Magia para cambiar de opción. Adaptación acuática y Cambiar apariencia funcionan igual (esta última con otra especie en vez de raza). Armas naturales: elegís garras (cortante), colmillos (perforante), cuernos (perforante) o pezuñas (contundente); tus golpes sin armas con esa parte infligen 1d6 de ese tipo y usás tu modificador de característica de lanzamiento (en vez de Fuerza) para ataque y daño; ya no dan competencia ni +1 mágico."},
{name:"Arcane Lock", nivel:2, edicion:"ambas", etiquetas:["protección", "utilidad"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S, M (polvo de oro por valor de al menos 25 po, que el hechizo consume)", duracion:"Hasta que se disipe", clases:["Mago"], desc:"Tocás una puerta, ventana, portón, cofre u otra entrada cerrada y queda trabada mientras dure. Vos y las criaturas que designes al lanzarlo pueden abrirla normalmente. Podés fijar una contraseña que, dicha a 5 ft del objeto, suprime el hechizo 1 minuto. Si no, es infranqueable hasta que se rompa o se disipe/suprima el hechizo; lanzar knock sobre el objeto lo suprime 10 minutos. Además la CD para romperlo o forzar sus cerraduras aumenta en 10.", desc2024:"En 2024: la cerradura mágica no puede abrirse por medios no mágicos. Vos y las criaturas que designes pueden abrir y cerrar el objeto a pesar de ella. Una contraseña dicha a 5 ft del objeto lo destraba 1 minuto. Ya no aumenta en 10 la CD para romperlo ni forzarlo."},
{name:"Arcanist's Magic Aura", nivel:2, edicion:"ambas", etiquetas:["ilusión", "utilidad"], escuela:"Ilusión", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S, M (un pequeño cuadrado de seda)", duracion:"24 horas", clases:["Mago"], desc:"Colocás una ilusión sobre una criatura voluntaria o un objeto que nadie lleve puesto o cargue, de modo que los conjuros de adivinación revelen información falsa. Elegís uno o ambos efectos. Falsa aura: cambiás cómo ven el objetivo los efectos que detectan auras mágicas (Detect Magic): un objeto no mágico parece mágico, uno mágico parece no mágico, o su aura parece de una escuela a elección; en un objeto podés hacer evidente la falsa magia a quien lo manipule. Máscara: cambiás cómo lo ven los efectos que detectan tipos de criatura (Divine Sense, Symbol); elegís un tipo de criatura o alineamiento y lo tratan como tal. Si lo lanzás sobre el mismo objetivo cada día durante 30 días con el mismo efecto, la ilusión dura hasta que se disipe.", desc2024:"Ahora cada objetivo recibe un solo efecto fijo: una criatura voluntaria obtiene Máscara (elegís un tipo de criatura distinto del real y los conjuros y efectos mágicos la tratan como de ese tipo) y un objeto sin portar obtiene Falsa aura (parece mágico, no mágico o de una escuela a elección). Ya no se pueden combinar ni elegir, ni se ofrece la opción de alineamiento ni de hacer evidente la falsa magia. Dura 24 horas; si se lanza sobre el mismo objetivo cada día durante 30 días, dura hasta que se disipe."},
{name:"Augury", nivel:2, edicion:"ambas", etiquetas:["adivinación", "utilidad"], escuela:"Adivinación", tiempo:"1 minuto (ritual)", alcance:"Personal", componentes:"V, S, M (palitos, huesos o fichas similares especialmente marcados, valuados en al menos 25 po)", duracion:"Instantáneo", clases:["Clérigo"], desc:"Tirando palitos con gemas, huesos de dragón, cartas ornamentadas u otra herramienta de adivinación, recibís un presagio de una entidad de otro mundo sobre los resultados de un curso de acción que planeás tomar en los próximos 30 minutos. El DM elige entre: Weal (resultados buenos), Woe (malos), Weal and woe (buenos y malos) o Nada (ni especialmente buenos ni malos). No tiene en cuenta circunstancias que puedan cambiar el resultado, como otros conjuros o perder/ganar un compañero. Si lo lanzás dos o más veces antes de completar un descanso largo, cada lanzamiento posterior al primero tiene un 25% acumulativo de dar una lectura aleatoria (el DM tira en secreto).", desc2024:"En 2024 también lo tienen Druida y Mago. El DM elige el presagio entre Woe (resultados malos), Weal (buenos), Weal and woe (buenos y malos) o Indifference (ni buenos ni malos). Si lo lanzás más de una vez antes de terminar un descanso largo, cada lanzamiento posterior al primero tiene un 25% acumulativo de que no obtengas respuesta (en vez de una lectura aleatoria)."},
{name:"Blindness/Deafness", nivel:2, edicion:"ambas", etiquetas:["control", "salvación"], escuela:"Necromancia", tiempo:"1 Acción", alcance:"30 ft", componentes:"V", duracion:"1 minuto", clases:["Bardo", "Clérigo", "Hechicero", "Mago"], desc:"Elegís una criatura que veas en alcance; hace una salvación de Constitución. Si falla, queda Cegada o Ensordecida (a tu elección) durante la duración. Al final de cada uno de sus turnos puede repetir la salvación; si la supera, el conjuro termina. A niveles superiores: una criatura adicional por cada nivel de espacio por encima de 2.", desc2024:"En 2024: es de escuela Transmutación y el alcance es de 120 ft. Una criatura que veas hace salvación de Constitución; si falla, queda Cegada o Ensordecida (a tu elección) 1 minuto, repitiendo la salvación al final de cada uno de sus turnos (si la supera, termina). A niveles superiores: una criatura adicional por cada nivel de espacio por encima de 2."},
{name:"Blur", nivel:2, edicion:"ambas", etiquetas:["ilusión", "protección"], escuela:"Ilusión", tiempo:"1 Acción", alcance:"Personal", componentes:"V", duracion:"Conc., hasta 1 min", clases:["Hechicero", "Mago"], desc:"Tu cuerpo se vuelve borroso y ondulante para quienes te ven. Mientras dure, cualquier criatura tiene desventaja en las tiradas de ataque contra vos. Un atacante es inmune a este efecto si no depende de la vista (como con visión ciega) o si puede ver a través de ilusiones (como con visión verdadera)."},
{name:"Branding Smite", nivel:2, edicion:"2014", etiquetas:["daño", "radiante", "arma", "buff"], escuela:"Evocación", tiempo:"1 Acción Adicional", alcance:"Personal", componentes:"V", duracion:"Conc., hasta 1 min", clases:["Paladín"], desc:"La próxima vez que impactes a una criatura con un ataque con arma antes de que termine el conjuro, el arma reluce con radiancia astral: el ataque inflige 2d6 daño radiante extra. El objetivo se vuelve visible si estaba invisible, emite luz tenue en 5 ft de radio y no puede volverse invisible hasta que termine el conjuro. A niveles superiores: +1d6 de daño extra por cada nivel de espacio por encima de 2."},
{name:"Calm Emotions", nivel:2, edicion:"ambas", etiquetas:["control", "salvación"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S", duracion:"Conc., hasta 1 min", clases:["Bardo", "Clérigo"], desc:"Cada humanoide en una esfera de 20 ft de radio centrada en un punto a 60 ft hace salvación de Carisma (puede elegir fallar). Si falla, elegís un efecto: suprimir cualquier efecto que lo tenga Hechizado o Asustado (se reanuda al terminar el conjuro si su duración no expiró), o volverlo indiferente hacia las criaturas que elijas y hacia las que es hostil. La indiferencia termina si lo atacan o dañan con un conjuro, o si ve dañar a un amigo; al terminar el conjuro vuelve a ser hostil, salvo decisión del DM.", desc2024:"En 2024: cada humanoide en la esfera de 20 ft debe superar una salvación de Carisma o sufre (elegís por criatura) uno de estos efectos: inmunidad a Hechizado y Asustado hasta que termine el conjuro (si ya lo estaba, esas condiciones quedan suprimidas), o indiferencia hacia criaturas que elijas y hacia las que es hostil, que termina si recibe daño o ve dañar a sus aliados; al terminar el conjuro su actitud vuelve a la normal. Ya no puede elegir fallar la salvación."},
{name:"Continual Flame", nivel:2, edicion:"ambas", etiquetas:["utilidad"], escuela:"Evocación", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S, M (polvo de rubí por valor de 50 po, que el hechizo consume)", duracion:"Hasta que se disipe", clases:["Clérigo", "Mago"], desc:"Una llama, tan brillante como una antorcha, brota de un objeto que tocás. Parece una llama común, pero no da calor ni consume oxígeno. Puede cubrirse u ocultarse, pero no sofocarse ni apagarse.", desc2024:"En 2024: la llama emite luz brillante en 20 ft y tenue 20 ft más; no da calor ni consume combustible, y puede cubrirse u ocultarse pero no sofocarse ni apagarse. El material cuesta 50+ po (se consume) y también lo aprende el Druida."},
{name:"Darkness", nivel:2, edicion:"ambas", etiquetas:["control", "utilidad"], escuela:"Evocación", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, M (pelo de murciélago y una gota de brea o un trozo de carbón)", duracion:"Conc., hasta 10 min", clases:["Hechicero", "Brujo", "Mago"], desc:"Oscuridad mágica se extiende desde un punto a tu alcance y llena una esfera de 15 ft de radio, doblando esquinas. Las criaturas con visión en la oscuridad no ven a través de ella y la luz no mágica no la ilumina. Si el punto está en un objeto que sostenés o que nadie lleva puesto ni carga, la oscuridad emana del objeto y se mueve con él; taparlo por completo con algo opaco (un cuenco, un yelmo) la bloquea. Si el área se superpone con luz creada por un conjuro de nivel 2 o menor, ese conjuro se disipa.", desc2024:"La oscuridad llena una esfera de 15 ft de radio desde un punto a tu alcance. Alternativamente se lanza sobre un objeto que nadie lleve puesto ni cargue (ya no uno que sostengas), y la oscuridad llena una emanación de 15 ft desde él; taparlo con algo opaco la bloquea. Si se superpone con luz brillante o luz tenue de un conjuro de nivel 2 o menor, ese conjuro se disipa."},
{name:"Detect Thoughts", nivel:2, edicion:"ambas", etiquetas:["adivinación"], escuela:"Adivinación", tiempo:"1 Acción", alcance:"Personal", componentes:"V, S, M (una moneda de cobre)", duracion:"Conc., hasta 1 min", clases:["Bardo", "Hechicero", "Mago"], desc:"Podés leer los pensamientos de ciertas criaturas. Al lanzarlo y con tu acción en cada turno, te concentrás en una criatura que veas a 30 ft; si tiene Inteligencia 3 o menos o no habla ningún idioma, no se ve afectada. Primero conocés sus pensamientos superficiales; con una acción podés pasar a otra criatura o sondear más hondo: el objetivo hace salvación de Sabiduría, y si falla descubrís su razonamiento, estado emocional y algo que lo preocupa, ama u odia; si salva, el hechizo termina. En ambos casos sabe que lo sondeás y, mientras no cambies de criatura, puede usar su acción para una prueba de Inteligencia enfrentada a la tuya y terminar el hechizo si gana. También detectás criaturas pensantes ocultas a 30 ft (bloquean 2 ft de roca, 2 pulgadas de metal salvo plomo o una lámina fina de plomo); no detectás Int 3 o menos ni a las que no hablan.", desc2024:"En 2024 activás uno de dos efectos y podés activar cualquiera con una acción de Magia en turnos posteriores. Sentir pensamientos: percibís a 30 ft la presencia de criaturas con idiomas o telepáticas (sin leer sus pensamientos); lo bloquean 1 ft de piedra, tierra o madera, 1 pulgada de metal o una lámina fina de plomo. Leer pensamientos: elegís una criatura a 30 ft (vista o detectada) y sabés qué tiene más en mente; si no conoce idiomas ni es telepática, no aprendés nada. En tu siguiente turno podés sondear más hondo: salvación de Sabiduría; si falla, discernís su razonamiento, emociones y algo que lo preocupa, ama u odia; si salva, el hechizo termina. El objetivo sabe que lo sondeás y puede usar su acción para una prueba de Inteligencia (Arcanos) contra tu CD de conjuro, terminando el hechizo si tiene éxito."},
{name:"Dragon's Breath", nivel:2, edicion:"2024", etiquetas:["buff", "daño", "salvación"], escuela:"Transmutación", tiempo:"1 Acción Adicional", alcance:"Toque", componentes:"V, S, M (un chile picante)", duracion:"Conc., hasta 1 min", clases:["Hechicero", "Mago"], desc:"Tocás a una criatura voluntaria y elegís ácido, frío, fuego, relámpago (rayo) o veneno. Hasta que termine el conjuro, el objetivo puede usar la acción Magia para exhalar un cono de 15 ft: cada criatura ahí hace salvación de Destreza y sufre 3d6 de daño del tipo elegido (mitad si salva). A niveles superiores: el daño aumenta 1d6 por cada nivel de espacio por encima de 2."},
{name:"Enlarge/Reduce", nivel:2, edicion:"ambas", etiquetas:["buff", "control", "salvación"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, S, M (una pizca de polvo de hierro)", duracion:"Conc., hasta 1 min", clases:["Hechicero", "Mago"], desc:"Una criatura u objeto (no vestido ni portado) que veas a alcance crece o se encoge. Si no es voluntaria, hace salvación de Constitución y no sufre efecto si la supera. Lo que lleve puesto o cargue cambia de tamaño con ella; un objeto soltado vuelve a la normalidad. Agrandar: tamaño y dimensiones se duplican (peso x8, una categoría más), ventaja en pruebas y salvaciones de Fuerza, y sus armas infligen 1d4 daño extra. Reducir: tamaño a la mitad (peso 1/8, una categoría menos), desventaja en pruebas y salvaciones de Fuerza, y sus armas infligen 1d4 menos de daño (mínimo 1). Si falta espacio, alcanza el tamaño máximo posible.", desc2024:"En 2024 también está en las listas de Bardo y Druida. Funciona igual (salvación de Constitución si no es voluntaria; Agrandar: una categoría de tamaño más, ventaja en pruebas y salvaciones de Fuerza, +1d4 de daño; Reducir: una categoría menos, desventaja en las mismas tiradas, -1d4 de daño, mínimo 1), pero el daño extra o reducido también se aplica a los ataques sin armas, y un arma arrojada o munición vuelve a su tamaño normal justo después de impactar o fallar."},
{name:"Enthrall", nivel:2, edicion:"ambas", etiquetas:["control", "salvación"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S", duracion:"1 minuto", clases:["Bardo", "Brujo"], desc:"Tejés palabras que distraen: las criaturas de tu elección que veas a 60 ft y puedan oírte hacen salvación de Sabiduría. Las que no pueden ser hechizadas la superan automáticamente, y si vos o tus compañeros están combatiendo a una criatura, tiene ventaja en la salvación. Si falla, tiene desventaja en pruebas de Sabiduría (Percepción) para percibir a cualquier criatura que no seas vos, hasta que termine el conjuro o deje de oírte. Termina si quedás incapacitado o no podés hablar.", desc2024:"En 2024: requiere concentración (hasta 1 min). Las criaturas de tu elección que veas a 60 ft hacen salvación de Sabiduría; las que vos o tus compañeros estén combatiendo la superan automáticamente. Si falla, la criatura tiene un penalizador de -10 a las pruebas de Sabiduría (Percepción) y a su Percepción pasiva hasta que termine el conjuro."},
{name:"Find Steed", nivel:2, edicion:"ambas", etiquetas:["invocación", "buff"], escuela:"Conjuración", tiempo:"10 minutos", alcance:"30 ft", componentes:"V, S", duracion:"Instantáneo", clases:["Paladín"], desc:"Invocás un espíritu con forma de montura inteligente, fuerte y leal (caballo de guerra, poni, camello, alce o mastín, u otra a criterio del DM) en un espacio libre del alcance. Tiene las estadísticas de esa forma, pero es celestial, feérico o infernal a elección; si su Inteligencia es 5 o menos pasa a 6 y entiende un idioma tuyo. Te sirve de montura y, montado, tus hechizos que te tengan solo a vos como objetivo también lo afectan. Al llegar a 0 PG desaparece; podés despedirlo con una acción, y volver a lanzarlo lo trae restaurado a su máximo de PG. Telepatía a 1 mi. Solo una montura a la vez; con una acción podés liberarla.", desc2024:"En 2024: se lanza con 1 Acción. Invocás un ser de otro mundo con las estadísticas «Otherworldly Steed» (Grande, a elegir celestial, feérico o infernal); si ya tenías una, la reemplaza. Comparte tu iniciativa y actúa como montura controlada; si estás Incapacitado actúa justo después de vos y te protege. CA 10 + nivel del espacio, PG 5 + 10 por nivel, Vel 60 ft (y vuelo 60 ft con espacio de nivel 4+); telepatía a 1 mi. Life Bond: si recuperás PG con un hechizo de nivel 1+, y estás a 5 ft, recupera lo mismo. Otherworldly Slam: ataque cuerpo a cuerpo (tu bono de ataque de conjuro), 1d8 + nivel de daño radiante/psíquico/necrótico. Acción adicional, 1 vez por descanso largo: Fell Glare (infernal; salvación de Sabiduría a 60 ft o Asustado), Fey Step (feérico; teletransporta a montura y jinete 60 ft), Healing Touch (celestial; 2d8 + nivel PG a una criatura a 5 ft). Desaparece a 0 PG o si morís."},
{name:"Gentle Repose", nivel:2, edicion:"ambas", etiquetas:["utilidad", "protección"], escuela:"Necromancia", tiempo:"1 Acción (ritual)", alcance:"Toque", componentes:"V, S, M (una pizca de sal y una moneda de cobre sobre cada ojo del cadáver, que deben permanecer ahí durante la duración)", duracion:"10 días", clases:["Clérigo", "Mago"], desc:"Tocás un cadáver u otros restos: durante 10 días queda protegido de la descomposición y no puede volverse no-muerto. Además extiende el límite de tiempo para revivirlo, ya que los días bajo este conjuro no cuentan contra el límite de conjuros como Raise Dead."},
{name:"Invisibility", nivel:2, edicion:"ambas", etiquetas:["buff", "ilusión"], escuela:"Ilusión", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S, M (una pestaña envuelta en goma arábiga)", duracion:"Conc., hasta 1 hora", clases:["Bardo", "Hechicero", "Brujo", "Mago"], desc:"Una criatura que tocás queda Invisible hasta que termine el hechizo; lo que lleve puesto o cargado también es invisible mientras esté sobre ella. Termina para el objetivo que ataque o lance un hechizo. A niveles superiores: una criatura adicional por cada nivel de espacio por encima de 2.", desc2024:"En 2024: el objetivo tiene la condición Invisible y el hechizo termina inmediatamente después de que haga una tirada de ataque, inflija daño o lance un hechizo. A niveles superiores: una criatura adicional por cada nivel de espacio por encima de 2."},
{name:"Knock", nivel:2, edicion:"ambas", etiquetas:["utilidad"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"60 ft", componentes:"V", duracion:"Instantáneo", clases:["Bardo", "Hechicero", "Mago"], desc:"Elegís un objeto que veas a tu alcance (puerta, caja, cofre, grilletes, candado u otro con un medio mundano o mágico que impida el acceso). Si está cerrado con una cerradura mundana, atascado o trabado, queda abierto, liberado o destrabado; si tiene varias cerraduras, solo se abre una. Si está sellado con Arcane Lock, ese conjuro queda suprimido 10 minutos y el objeto puede abrirse y cerrarse normalmente. Al lanzarlo, un golpe fuerte emana del objeto y se oye hasta a 300 ft."},
{name:"Levitate", nivel:2, edicion:"ambas", etiquetas:["control", "utilidad"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S, M (un pequeño lazo de cuero o un alambre de oro doblado en forma de copa con un mango largo)", duracion:"Conc., hasta 10 min", clases:["Hechicero", "Mago"], desc:"Una criatura u objeto que veas en alcance se eleva hasta 20 ft en vertical y queda suspendido mientras dure; puede levitar un objetivo de hasta 500 libras. Una criatura involuntaria que supere una salvación de Constitución no se ve afectada. El objetivo solo puede moverse empujando o tirando de un objeto o superficie fija a su alcance (como escalar). En tu turno podés cambiar su altitud hasta 20 ft; si sos el objetivo, subís o bajás como parte de tu movimiento, y si no, usás tu acción para moverlo, dentro del alcance. Al terminar, el objetivo desciende suavemente si sigue en el aire.", desc2024:"En 2024 solo afecta a una criatura u objeto suelto (el límite de 500 libras se aplica a objetos). Una criatura involuntaria que supere una salvación de Constitución no se ve afectada. El objetivo se eleva hasta 20 ft y queda suspendido; solo se mueve empujando o tirando de superficies fijas a su alcance. En tu turno cambiás su altitud hasta 20 ft; si no sos el objetivo, usás una acción de Magia para moverlo dentro del alcance. Al terminar, desciende suavemente."},
{name:"Magic Mouth", nivel:2, edicion:"ambas", etiquetas:["ilusión", "utilidad"], escuela:"Ilusión", tiempo:"1 minuto (ritual)", alcance:"30 ft", componentes:"V, S, M (un panal de miel y polvo de jade por valor de al menos 10 po, que el conjuro consume)", duracion:"Hasta que se disipe", clases:["Bardo", "Mago"], desc:"Implantás un mensaje de hasta 25 palabras (que puede tardar hasta 10 minutos en decirse) en un objeto que veas a alcance y que no lleve otra criatura, y fijás una condición que lo dispare, basada en circunstancias visuales o audibles a 30 ft del objeto. Al cumplirse, aparece una boca mágica (en la boca del objeto, si la tiene) que recita el mensaje con tu voz y tono. Al lanzarlo decidís si el conjuro termina tras decir el mensaje o si lo repite cada vez que ocurra la condición."},
{name:"Mind Spike", nivel:2, edicion:"2024", etiquetas:["daño", "psíquico", "salvación", "adivinación"], escuela:"Adivinación", tiempo:"1 Acción", alcance:"120 ft", componentes:"S", duracion:"Conc., hasta 1 hora", clases:["Hechicero", "Brujo", "Mago"], desc:"Clavás una lanza de energía psiónica en la mente de una criatura que veas en alcance: salvación de Sabiduría, sufre 3d8 daño psíquico (mitad si salva). Si falla, además siempre sabés dónde está mientras dure, siempre que estén en el mismo plano; no puede esconderse de vos y, si está Invisible, no obtiene beneficio de esa condición contra vos. A niveles superiores: el daño sube 1d8 por cada nivel de espacio por encima de 2."},
{name:"Mirror Image", nivel:2, edicion:"ambas", etiquetas:["ilusión", "protección"], escuela:"Ilusión", tiempo:"1 Acción", alcance:"Personal", componentes:"V, S", duracion:"1 minuto", clases:["Hechicero", "Brujo", "Mago"], desc:"Aparecen tres duplicados ilusorios tuyos en tu espacio que se mueven contigo e imitan tus acciones. Podés usar tu acción para disiparlos. Cada vez que una criatura te ataca, tirás 1d20 para ver si el ataque va a un duplicado: con 3 duplicados necesitás 6 o más, con 2 duplicados 8 o más, con 1 duplicado 11 o más. La CA de un duplicado es 10 + tu modificador de Destreza; si un ataque lo impacta, se destruye (solo un ataque que lo impacte puede destruirlo; ignora cualquier otro daño o efecto). El conjuro termina al destruirse los tres. No afecta a quien no pueda ver, use otros sentidos (como sentido ciego) o perciba las ilusiones como falsas (visión verdadera).", desc2024:"Cada vez que una criatura te impacta con una tirada de ataque, tirás 1d6 por cada duplicado restante; si alguno saca 3 o más, el ataque impacta a un duplicado en lugar de a vos y ese duplicado se destruye. Los duplicados ignoran cualquier otro daño o efecto. Termina al destruirse los tres. No afecta a una criatura Cegada ni a una con sentido ciego o visión verdadera. En 2024 también es conjuro de Bardo."},
{name:"Phantasmal Force", nivel:2, edicion:"2024", etiquetas:["ilusión", "control", "daño", "psíquico", "salvación"], escuela:"Ilusión", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S, M (un poco de lana)", duracion:"Conc., hasta 1 min", clases:["Bardo", "Hechicero", "Mago"], desc:"Intentás crear una ilusión en la mente de una criatura que veas a tu alcance, que hace una salvación de Inteligencia. Si falla, creás un objeto, criatura u otro fenómeno fantasmal de hasta un cubo de 10 ft que solo el objetivo percibe, con sonido, temperatura y otros estímulos. El objetivo puede usar la acción Estudiar y hacer una prueba de Inteligencia (Investigación) contra tu CD; si la supera, descubre que es una ilusión y el hechizo termina. Mientras esté afectado, trata el fantasma como real y racionaliza los resultados ilógicos. Si el fantasma representa una criatura o peligro dañino, en cada uno de tus turnos puede infligirle 2d8 de daño psíquico si está en su área o a 5 ft; el objetivo percibe el daño con un tipo acorde a la ilusión."},
{name:"Prayer of Healing", nivel:2, edicion:"ambas", etiquetas:["curación"], escuela:"Evocación", tiempo:"10 minutos", alcance:"30 ft", componentes:"V", duracion:"Instantáneo", clases:["Clérigo"], desc:"Hasta seis criaturas a tu elección que veas a alcance recuperan 2d8 + tu modificador de característica de lanzamiento en PG. No tiene efecto sobre muertos vivientes ni constructos. A niveles superiores: la curación aumenta 1d8 por cada nivel de espacio por encima de 2.", desc2024:"En 2024 también está en la lista de Paladín y es de Abjuración. Hasta cinco criaturas a tu elección que permanezcan a alcance durante todo el lanzamiento obtienen los beneficios de un descanso corto y recuperan 2d8 PG (sin sumar tu modificador). Una criatura no puede ser afectada de nuevo hasta que termine un descanso largo. A niveles superiores: la curación aumenta 1d8 por cada nivel de espacio por encima de 2."},
{name:"Ray of Enfeeblement", nivel:2, edicion:"ambas", etiquetas:["control", "ataque"], escuela:"Necromancia", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S", duracion:"Conc., hasta 1 min", clases:["Brujo", "Mago"], desc:"Un rayo negro sale de tu dedo hacia una criatura en alcance: tirada de ataque de conjuro a distancia. Con impacto, mientras dure el objetivo hace solo la mitad del daño con ataques de arma que usen Fuerza. Al final de cada uno de sus turnos puede hacer salvación de Constitución; si la supera, el hechizo termina.", desc2024:"En 2024 ya no hay tirada de ataque: el objetivo hace salvación de Constitución. Si la supera, tiene desventaja en la próxima tirada de ataque que haga hasta el inicio de tu próximo turno. Si falla, tiene desventaja en las pruebas de d20 basadas en Fuerza durante la duración y resta 1d8 a todas sus tiradas de daño; repite la salvación al final de cada uno de sus turnos y, si la supera, el hechizo termina."},
{name:"Scorching Ray", nivel:2, edicion:"ambas", etiquetas:["daño", "fuego", "ataque"], escuela:"Evocación", tiempo:"1 Acción", alcance:"120 ft", componentes:"V, S", duracion:"Instantáneo", clases:["Hechicero", "Mago"], desc:"Creás tres rayos de fuego y los lanzás contra objetivos a tu alcance, a uno solo o a varios. Hacés una tirada de ataque de conjuro a distancia por cada rayo; si impacta, el objetivo sufre 2d6 daño de fuego. A niveles superiores: creás un rayo adicional por cada nivel de espacio por encima del 2.º."},
{name:"Shatter", nivel:2, edicion:"ambas", etiquetas:["daño", "trueno", "salvación"], escuela:"Evocación", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S, M (una pizca de mica)", duracion:"Instantáneo", clases:["Bardo", "Hechicero", "Brujo", "Mago"], desc:"Un estruendo doloroso y repentino estalla en un punto a 60 ft; cada criatura en una esfera de 10 ft de radio hace salvación de Constitución, sufriendo 3d8 de daño de trueno (mitad si salva). Las criaturas de materia inorgánica (piedra, cristal, metal) tienen desventaja en la salvación. Un objeto no mágico que no esté vestido ni llevado también sufre el daño. A niveles superiores: +1d8 por cada nivel de espacio por encima de 2.", desc2024:"En 2024: ya no es lista del Brujo (Bardo, Hechicero, Mago). Mismo estruendo en una esfera de 10 ft de radio a 60 ft: salvación de Constitución, 3d8 de daño de trueno (mitad si salva); solo los Constructos tienen desventaja en la salvación (ya no toda criatura inorgánica). Los objetos no mágicos no llevados también sufren el daño. A niveles superiores: +1d8 por nivel por encima de 2."},
{name:"Shining Smite", nivel:2, edicion:"2024", etiquetas:["daño", "radiante", "arma", "control"], escuela:"Transmutación", tiempo:"1 Acción Adicional", alcance:"Personal", componentes:"V", duracion:"Conc., hasta 1 min", clases:["Paladín"], desc:"Se lanza como acción adicional inmediatamente después de impactar a una criatura con un arma cuerpo a cuerpo o un Golpe Sin Armas. El objetivo sufre 2d6 de daño radiante adicional por el ataque. Mientras dure, el objetivo emite luz brillante en un radio de 5 ft, las tiradas de ataque contra él tienen ventaja y no puede beneficiarse de la condición Invisible. A niveles superiores: +1d6 de daño por cada nivel de espacio por encima de 2."},
{name:"Silence", nivel:2, edicion:"ambas", etiquetas:["control", "utilidad"], escuela:"Ilusión", tiempo:"1 Acción (ritual)", alcance:"120 ft", componentes:"V, S", duracion:"Conc., hasta 10 min", clases:["Bardo", "Clérigo", "Ranger"], desc:"Mientras dure, no se puede crear ni atravesar ningún sonido en una esfera de 20 ft de radio centrada en un punto a alcance. Toda criatura u objeto completamente dentro es inmune al daño de trueno, y las criaturas quedan Ensordecidas mientras estén completamente dentro. Lanzar un conjuro con componente verbal es imposible ahí."},
{name:"Spider Climb", nivel:2, edicion:"ambas", etiquetas:["buff", "utilidad"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S, M (una gota de betún y una araña)", duracion:"Conc., hasta 1 hora", clases:["Hechicero", "Brujo", "Mago"], desc:"Hasta que termine el conjuro, una criatura voluntaria que tocás puede moverse hacia arriba, abajo y a través de superficies verticales, y cabeza abajo por los techos, dejando las manos libres. Además gana una velocidad de trepar igual a su velocidad caminando.", desc2024:"En 2024: igual (superficies verticales y techos, manos libres, velocidad de trepar igual a su Velocidad), pero a niveles superiores: podés afectar a una criatura adicional por cada nivel de espacio sobre el 2º."},
{name:"Spiritual Weapon", nivel:2, edicion:"ambas", etiquetas:["daño", "fuerza", "ataque", "invocación"], escuela:"Evocación", tiempo:"1 Acción Adicional", alcance:"60 ft", componentes:"V, S", duracion:"1 minuto", clases:["Clérigo"], desc:"Creás un arma espectral flotante a tu alcance con la forma que elijas (un clérigo de una deidad con arma asociada la asemeja a ella); dura hasta que termine el conjuro o lo lances de nuevo. Al lanzarlo hacés un ataque de conjuro cuerpo a cuerpo contra una criatura a 5 ft del arma: si impacta, sufre daño de fuerza igual a 1d8 + tu modificador de característica de lanzamiento. Como acción adicional en tu turno, movés el arma hasta 20 ft y repetís el ataque. A niveles superiores: +1d8 por cada dos niveles de espacio sobre 2.", desc2024:"Ahora requiere concentración (hasta 1 minuto). La fuerza espectral aparece en un espacio a tu elección y atacás de inmediato con un ataque de conjuro cuerpo a cuerpo contra una criatura a 5 ft: 1d8 + tu modificador de característica de lanzamiento de daño de fuerza. Como acción adicional en turnos posteriores, la movés hasta 20 ft y repetís el ataque. A niveles superiores: +1d8 por cada nivel de espacio sobre 2 (antes, uno cada dos niveles)."},
{name:"Warding Bond", nivel:2, edicion:"ambas", etiquetas:["protección", "buff"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S, M (un par de anillos de platino de al menos 50 po cada uno, que vos y el objetivo deben llevar puestos mientras dure)", duracion:"1 hora", clases:["Clérigo"], desc:"Protegés a una criatura voluntaria que tocás y creás una conexión mística entre ambos. Mientras el objetivo esté a 60 ft de vos, recibe +1 a la CA y a las tiradas de salvación, y tiene resistencia a todo el daño; además, cada vez que sufre daño, vos sufrís la misma cantidad. El hechizo termina si caés a 0 PG, si quedan separados por más de 60 ft, o si se lanza de nuevo sobre cualquiera de los dos conectados. También podés disiparlo con una acción."},

// ===== NIVEL 3 =====
{name:"Call Lightning", nivel:3, edicion:"ambas", etiquetas:["daño","rayo","salvación"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"120 ft", componentes:"V, S", duracion:"Conc., hasta 10 min", clases:["Druida"], desc:"Una nube de tormenta aparece; con cada acción adicional, un rayo golpea un punto a tu elección, 3d10 daño de rayo (salvación de Destreza para mitad)."},
{name:"Conjure Animals", nivel:3, edicion:"ambas", etiquetas:["invocación"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S", duracion:"Conc., hasta 1 hora", clases:["Druida","Ranger"], desc2024:"Conjurás espíritus de la naturaleza como una manada grande, espectral e intangible de animales (la forma la elegís vos) en un espacio libre a 60 ft, hasta 10 minutos (concentración). Tenés ventaja en salvaciones de Fuerza a 5 ft de la manada y, al moverte, podés moverla hasta 30 ft. Cuando la manada se mueve a 10 ft de una criatura que veas, o una criatura entra a 10 ft o termina su turno ahí, podés forzarla a una salvación de Destreza: si falla, 3d10 de daño cortante (una vez por turno). A niveles superiores: +1d10 por nivel por encima de 3.", desc:"Invocás espíritus de bestias que toman forma (hasta 8 CR¼, o proporcionalmente más pequeñas cantidades de CR mayor) para pelear a tu lado.", upcast:{tipo:"tabla", nivelBase:3, tabla:{
  3:"Hasta 8 bestias de CR 1/4 (o menos cantidad, de CR mayor, proporcional).",
  4:"El doble que a nivel 3 (o la combinación de CR mayor equivalente).",
  5:"El triple que a nivel 3.",
  6:"Cuádruple que a nivel 3.",
  7:"Quíntuple que a nivel 3.",
  8:"Séxtuple que a nivel 3.",
  9:"Séptuple que a nivel 3.",
}}},
{name:"Daylight", nivel:3, edicion:"ambas", etiquetas:["utilidad"], escuela:"Evocación", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S", duracion:"1 hora", clases:["Clérigo","Druida","Paladín","Ranger","Hechicero"], desc:"Un punto a tu alcance emite luz brillante en 60 ft (y tenue 60 ft más), como luz solar, disipando oscuridad no mágica."},
{name:"Dispel Magic", nivel:3, edicion:"ambas", etiquetas:["utilidad"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"120 ft", componentes:"V, S", duracion:"Instantáneo", clases:["Bardo","Clérigo","Druida","Paladín","Hechicero","Brujo","Mago"], desc:"Termina un conjuro activo sobre una criatura u objeto a tu alcance (chequeo automático hasta nivel 3, prueba de habilidad para conjuros de nivel mayor)."},
{name:"Meld into Stone", nivel:3, edicion:"ambas", etiquetas:["utilidad"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S", duracion:"8 horas", clases:["Clérigo","Druida"], desc2024:"Te fundís con una superficie u objeto de piedra tocado lo bastante grande para contenerte (8 horas, ritual); nada de tu presencia es detectable por sentidos no mágicos. No ves el exterior y tus pruebas de Sabiduría (Percepción) para oír tienen desventaja; podés lanzar conjuros sobre vos. Salir cuesta 5 ft de movimiento y termina el conjuro. Si la piedra se daña de forma parcial o cambia de forma, te expulsa con 6d6 de daño de fuerza; si se destruye por completo, 50 de daño de fuerza. Al ser expulsado quedás Derribado. Ahora también lo tienen Druida y Explorador.", desc:"Te fusionás con un objeto de piedra tocado, quedando invisible y protegido dentro durante la duración."},
{name:"Plant Growth", nivel:3, edicion:"ambas", etiquetas:["control"], escuela:"Transmutación", tiempo:"1 Acción (o 8 horas)", alcance:"150 ft", componentes:"V, S", duracion:"Instantáneo", clases:["Bardo","Druida","Ranger"], desc:"Enriquecés la vegetación en un radio de 100 ft convirtiéndola en terreno difícil (versión de 1 acción), o multiplicás el rendimiento de cultivo en un área grande (versión de 8 horas)."},
{name:"Protection from Energy", nivel:3, edicion:"ambas", etiquetas:["buff"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S", duracion:"Conc., hasta 1 hora", clases:["Clérigo","Druida","Ranger","Hechicero","Mago"], desc:"La criatura tocada gana resistencia a un tipo de daño elegido (ácido, frío, fuego, rayo o trueno) durante la duración."},
{name:"Sleet Storm", nivel:3, edicion:"ambas", etiquetas:["control"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"150 ft", componentes:"V, S, M (fichas de porcelana)", duracion:"Conc., hasta 1 min", clases:["Druida","Hechicero","Mago"], desc2024:"Aguanieve cae en un cilindro de 40 ft de alto y 20 ft de radio centrado en un punto a 150 ft (hasta 1 minuto, concentración). Zona muy oscurecida, llamas expuestas apagadas, suelo de terreno difícil. Una criatura que entre por primera vez en un turno o empiece su turno ahí debe superar una salvación de Destreza o queda Derribada y pierde la concentración (ya no hay una salvación de Constitución aparte).", desc:"Aguanieve helada cae en un cilindro de 40 ft: terreno difícil, visión oscurecida, y las criaturas que se muevan/entren deben chequear equilibrio o caer derribadas."},
{name:"Speak with Plants", nivel:3, edicion:"ambas", etiquetas:["utilidad"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"Personal", componentes:"V, S", duracion:"10 minutos", clases:["Bardo","Druida","Ranger"], desc:"Ganás la capacidad de comprender y comunicarte verbalmente con plantas dentro de 30 ft, y podés pedirles ayudas menores razonables."},
{name:"Water Breathing", nivel:3, edicion:"ambas", etiquetas:["buff"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, S, M (junco corto)", duracion:"24 horas", clases:["Druida","Ranger","Hechicero","Mago"], desc:"Hasta 10 criaturas voluntarias tocadas pueden respirar bajo el agua durante la duración."},
{name:"Water Walk", nivel:3, edicion:"ambas", etiquetas:["buff"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, S, M (corcho)", duracion:"1 hora", clases:["Clérigo","Druida","Ranger","Hechicero"], desc2024:"En 2024, hasta diez criaturas voluntarias a tu elección a alcance ganan la capacidad de moverse sobre cualquier superficie líquida (agua, ácido, barro, nieve, arenas movedizas, lava) como si fuera suelo sólido inofensivo. Pasar de la superficie al interior del líquido, y viceversa, requiere una acción adicional; si el objetivo cae al líquido, lo atraviesa. Ya no sube a los sumergidos a la superficie a 60 ft por asalto.", desc:"Hasta 10 criaturas tocadas pueden moverse sobre cualquier superficie líquida como si fuera terreno firme durante la duración."},
{name:"Wind Wall", nivel:3, edicion:"ambas", etiquetas:["control"], escuela:"Evocación", tiempo:"1 Acción", alcance:"120 ft", componentes:"V, S, M (trozo de pluma de ave)", duracion:"Conc., hasta 1 min", clases:["Druida","Ranger"], desc2024:"Un muro de viento fuerte (hasta 50 ft de largo, 15 ft de alto, 1 ft de grosor) se alza a 120 ft; al aparecer, cada criatura en su área hace salvación de Fuerza y sufre 4d8 daño contundente (mitad si salva). Mantiene a raya niebla, humo y gases; criaturas u objetos voladores Pequeños o menores no lo atraviesan; los proyectiles ordinarios hacia el otro lado se desvían hacia arriba y fallan automáticamente. En 2024 el daño es 4d8 (antes 3d8).", desc:"Un muro de viento fuerte (15 ft alto, 50 ft ancho) desvía flechas y gases, y dificulta el vuelo a través de él."},
{name:"Fireball", nivel:3, edicion:"ambas", etiquetas:["daño","fuego","salvación"], escuela:"Evocación", tiempo:"1 Acción", alcance:"150 ft", componentes:"V, S, M (bolita de guano y azufre)", duracion:"Instantáneo", clases:["Hechicero","Mago"], desc:"Una esfera de fuego de 20 ft de radio estalla en un punto; cada criatura ahí hace salvación de Destreza, sufriendo 8d6 daño de fuego (mitad si salva). Enciende objetos inflamables no equipados."},
{name:"Haste", nivel:3, edicion:"ambas", etiquetas:["buff"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, S, M (trozo de piel de ardilla)", duracion:"Conc., hasta 1 min", clases:["Hechicero","Mago"], desc:"La criatura tocada duplica su velocidad, gana +2 a CA, ventaja en salvaciones de Destreza y una acción adicional durante la duración.", buff:{activo:false, efectos:[{tipo:"plano", objetivo:"ca", valor:2}]}},
{name:"Summon Beast", nivel:3, etiquetas:["invocación"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"90 ft", componentes:"V, S, M (equipo de valor 25+ gp)", duracion:"Conc., hasta 1 hora", clases:["Druida","Ranger"], desc:"[2024] Invocás un espíritu de bestia (Aire/Tierra/Agua) que combatís a tu lado; sus estadísticas escalan con el nivel del espacio usado.", upcast:{tipo:"tabla", nivelBase:3, tabla:{
  3:"Espíritu Bestia nivel base — ver bloque de estadísticas 'Beast Spirit' para nivel de espacio 3.",
  4:"Ver bloque de estadísticas 'Beast Spirit' para nivel de espacio 4 (HP/ataque/daño mayores).",
  5:"Ver bloque de estadísticas 'Beast Spirit' para nivel de espacio 5.",
  6:"Ver bloque de estadísticas 'Beast Spirit' para nivel de espacio 6.",
  7:"Ver bloque de estadísticas 'Beast Spirit' para nivel de espacio 7.",
  8:"Ver bloque de estadísticas 'Beast Spirit' para nivel de espacio 8.",
  9:"Ver bloque de estadísticas 'Beast Spirit' para nivel de espacio 9.",
}}},
{name:"Animate Dead", nivel:3, edicion:"ambas", etiquetas:["invocación", "control"], escuela:"Necromancia", tiempo:"1 minuto", alcance:"10 ft", componentes:"V, S, M (una gota de sangre, un trozo de carne y una pizca de polvo de hueso)", duracion:"Instantáneo", clases:["Clérigo", "Mago"], desc:"Elegís un montón de huesos o el cadáver de un humanoide Mediano o Pequeño a alcance: se alza como muerto viviente, esqueleto si son huesos o zombi si es un cadáver (el DM tiene sus estadísticas). En cada uno de tus turnos podés usar una acción adicional para ordenar mentalmente a cada criatura creada que esté a 60 ft (la misma orden a varias a la vez); decidís su acción y movimiento o le das una orden general. Sin órdenes, solo se defiende. Te obedece 24 horas; para mantener el control otras 24 horas hay que relanzar el conjuro antes sobre ella, lo que reafirma el control de hasta cuatro criaturas animadas con él en vez de animar una nueva. A niveles superiores: animás o reafirmás el control de 2 muertos vivientes adicionales por cada nivel de espacio por encima de 3; cada uno debe provenir de un cadáver o montón de huesos distinto.", desc2024:"En 2024, si no das órdenes, la criatura realiza la acción Esquivar y solo se mueve para evitar daño (en vez de solo defenderse). El resto es igual: elegís huesos o el cadáver de un humanoide Mediano o Pequeño, que se vuelve esqueleto o zombi; ordenás con una acción adicional a criaturas a 60 ft; te obedecen 24 horas, renovables relanzando el conjuro (reafirma hasta cuatro criaturas). A niveles superiores: 2 muertos vivientes adicionales por nivel de espacio por encima de 3."},
{name:"Beacon of Hope", nivel:3, edicion:"ambas", etiquetas:["buff", "protección"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, S", duracion:"Conc., hasta 1 min", clases:["Clérigo"], desc:"Elegís cualquier cantidad de criaturas a 30 ft. Mientras dure, cada objetivo tiene ventaja en tiradas de salvación de Sabiduría y en salvaciones de muerte, y recupera el máximo posible de PG con cualquier curación que reciba."},
{name:"Bestow Curse", nivel:3, edicion:"ambas", etiquetas:["control", "salvación", "daño", "necrótico"], escuela:"Necromancia", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S", duracion:"Conc., hasta 1 min", clases:["Bardo", "Clérigo", "Mago"], desc:"Tocás a una criatura, que hace salvación de Sabiduría o queda maldita mientras dure. Al lanzarlo elegís la maldición: desventaja en pruebas y salvaciones de una característica a elección; desventaja en sus ataques contra vos; al inicio de cada uno de sus turnos hace salvación de Sabiduría o pierde su acción ese turno; o tus ataques y hechizos le infligen 1d8 daño necrótico adicional. Remove curse termina el efecto; el DM puede permitir otra maldición no más potente. A niveles superiores: espacio de nivel 4, concentración hasta 10 min; nivel 5+, sin concentración y 8 horas; nivel 7+, 24 horas; nivel 9, hasta que se disipe.", desc2024:"En 2024 la maldición de la acción cambia: al inicio de cada uno de sus turnos en combate, el objetivo supera una salvación de Sabiduría o se ve obligado a usar la acción Esquivar ese turno. El daño necrótico adicional de 1d8 se aplica si le infligís daño con una tirada de ataque o un hechizo. Niveles superiores: espacio de nivel 4, concentración hasta 10 min; nivel 5-6, sin concentración y 8 horas; nivel 7-8, 24 horas; nivel 9, hasta que se disipe."},
{name:"Blink", nivel:3, edicion:"ambas", etiquetas:["teletransporte", "protección"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"Personal", componentes:"V, S", duracion:"1 minuto", clases:["Hechicero", "Mago"], desc:"Al final de cada uno de tus turnos tirás 1d20; con 11 o más desaparecés de tu plano y aparecés en el Plano Etéreo (si ya estabas allí, el conjuro falla y se pierde). Al inicio de tu siguiente turno, y cuando termine el conjuro si estás en el Plano Etéreo, regresás a un espacio desocupado que veas a 10 ft del que dejaste (si no hay, al más cercano, al azar si hay varios). Podés terminarlo con una acción. En el Plano Etéreo ves y oís tu plano de origen en tonos grises, pero nada a más de 60 ft; solo afectás y te afectan otras criaturas etéreas, y quienes no estén allí no pueden percibirte ni interactuar con vos salvo que puedan hacerlo.", desc2024:"Ahora tirás 1d6 al final de cada uno de tus turnos y desaparecés al Plano Etéreo con 4-6 (si ya estabas allí, el conjuro termina al instante). El resto es igual: percibís el plano que dejaste en tonos grises hasta 60 ft, solo afectás y te afectan criaturas etéreas, y regresás al inicio de tu siguiente turno o al terminar el conjuro a un espacio desocupado que veas a 10 ft del que dejaste (o al más cercano)."},
{name:"Clairvoyance", nivel:3, edicion:"ambas", etiquetas:["adivinación"], escuela:"Adivinación", tiempo:"10 minutos", alcance:"1 mi", componentes:"V, S, M (un foco que valga al menos 100 po: un cuerno con joyas para oír o un ojo de vidrio para ver)", duracion:"Conc., hasta 10 min", clases:["Bardo", "Clérigo", "Hechicero", "Mago"], desc:"Creás un sensor invisible en un lugar de alcance que conozcas (visitado o visto antes) o en uno obvio aunque desconocido (tras una puerta, una esquina, una arboleda). El sensor permanece mientras dure y no puede ser atacado ni interactuado. Al lanzarlo elegís ver u oír, y percibís a través del sensor como si estuvieras en su espacio; con tu acción podés alternar entre ver y oír. Una criatura que vea el sensor (por ver invisibilidad o visión verdadera) percibe un orbe luminoso intangible del tamaño de un puño.", desc2024:"En 2024 alternar entre ver y oír cuesta una acción adicional (no una acción); el sensor es intangible e invulnerable. El resto funciona igual: sensor invisible en un lugar conocido u obvio dentro de 1 mi, elegís ver u oír, y quien lo vea percibe un orbe luminoso del tamaño de un puño."},
{name:"Counterspell", nivel:3, edicion:"ambas", etiquetas:["control", "protección"], escuela:"Abjuración", tiempo:"1 Reacción", alcance:"60 ft", componentes:"S", duracion:"Instantáneo", clases:["Hechicero", "Brujo", "Mago"], desc:"Intentás interrumpir a una criatura que está lanzando un hechizo. Si lanza un hechizo de nivel 3 o menor, falla y no tiene efecto. Si es de nivel 4 o mayor, hacés una prueba de característica de lanzamiento contra CD 10 + el nivel del hechizo; si la superás, el hechizo falla y no tiene efecto. A niveles superiores: con un espacio de nivel 4 o más, el hechizo interrumpido no tiene efecto si su nivel es menor o igual al del espacio usado.", desc2024:"En 2024 se lanza como reacción al ver a una criatura a 60 ft lanzar un hechizo con componentes verbales, somáticos o materiales. La criatura hace una salvación de Constitución; si falla, el hechizo se disipa sin efecto, se pierde la acción, acción adicional o reacción usada para lanzarlo y, si usó un espacio de conjuro, este no se gasta. Ya no hay prueba de característica ni escalado por nivel de espacio."},
{name:"Create Food and Water", nivel:3, edicion:"ambas", etiquetas:["utilidad", "invocación"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, S", duracion:"Instantáneo", clases:["Clérigo", "Druida", "Paladín"], desc:"Creás 45 libras de comida y 30 galones de agua en el suelo o en recipientes a alcance, suficientes para sustentar a hasta quince humanoides o cinco monturas durante 24 horas. La comida es insípida pero nutritiva y se echa a perder si no se come en 24 horas; el agua es limpia y no se pudre.", desc2024:"En 2024 ya no está en la lista de Druida. Creás 45 libras de comida y 30 galones de agua fresca en el suelo o en recipientes a alcance (útiles contra la desnutrición y la deshidratación). La comida es insípida pero nutritiva y tiene el aspecto de un alimento a tu elección; se echa a perder a las 24 horas si no se come. Ya no especifica a cuántas criaturas sustenta."},
{name:"Fear", nivel:3, edicion:"ambas", etiquetas:["control", "salvación", "ilusión"], escuela:"Ilusión", tiempo:"1 Acción", alcance:"Personal (cono de 30 ft)", componentes:"V, S, M (una pluma blanca o el corazón de una gallina)", duracion:"Conc., hasta 1 min", clases:["Bardo", "Hechicero", "Brujo", "Mago"], desc:"Proyectás la imagen fantasmal de los peores miedos de cada criatura en un cono de 30 ft; cada una debe superar una tirada de salvación de Sabiduría o suelta lo que sostenga y queda Asustada mientras dure. Mientras está Asustada, en cada uno de sus turnos debe usar la acción Correr y alejarse de vos por la ruta más segura, salvo que no tenga adónde ir. Si termina su turno en un lugar sin línea de visión hacia vos, puede repetir la salvación de Sabiduría; si la supera, el conjuro termina para esa criatura."},
{name:"Fly", nivel:3, edicion:"ambas", etiquetas:["buff", "utilidad"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S, M (una pluma de ala de cualquier ave)", duracion:"Conc., hasta 10 min", clases:["Hechicero", "Brujo", "Mago"], desc:"Tocás a una criatura voluntaria: obtiene velocidad de vuelo de 60 ft mientras dure. Al terminar el hechizo, el objetivo cae si sigue en el aire, salvo que pueda evitar la caída. A niveles superiores: una criatura adicional por cada nivel de espacio por encima de 3.", desc2024:"En 2024 el objetivo, además de la velocidad de vuelo de 60 ft, puede flotar (hover). Al terminar cae si sigue en el aire, salvo que pueda evitar la caída. A niveles superiores: una criatura adicional por cada nivel de espacio por encima de 3."},
{name:"Gaseous Form", nivel:3, edicion:"ambas", etiquetas:["buff", "utilidad", "protección"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S, M (un trozo de gasa y una voluta de humo)", duracion:"Conc., hasta 1 hora", clases:["Hechicero", "Brujo", "Mago"], desc:"Transformás a una criatura voluntaria tocada, con todo lo que viste y lleva, en una nube de niebla. Termina si cae a 0 PG; no afecta a criaturas incorpóreas. Su única forma de moverse es una velocidad de vuelo de 10 ft; puede ocupar el espacio de otra criatura, tiene resistencia al daño no mágico y ventaja en salvaciones de Fuerza, Destreza y Constitución. Pasa por orificios y rendijas (los líquidos son superficies sólidas), no cae y flota aun Aturdida o Incapacitada. No puede hablar ni manipular objetos (lo que lleva no se puede soltar ni usar) ni atacar ni lanzar conjuros.", desc2024:"En 2024: el objetivo (o el conjuro, con una acción Magia) puede terminar el efecto a voluntad; tiene velocidad de vuelo de 10 ft con vuelo estacionario, resistencia al daño contundente, perforante y cortante, inmunidad a Derribado y ventaja en salvaciones de Fuerza, Destreza y Constitución. Sigue sin poder hablar, manipular objetos, atacar ni lanzar conjuros. A niveles superiores: una criatura adicional por cada nivel de espacio por encima de 3."},
{name:"Glyph of Warding", nivel:3, edicion:"ambas", etiquetas:["daño", "salvación", "protección", "ácido", "frío", "fuego", "rayo", "trueno"], escuela:"Abjuración", tiempo:"1 hora", alcance:"Toque", componentes:"V, S, M (incienso y polvo de diamante por al menos 200 gp, que el hechizo consume)", duracion:"Hasta que se disipe", clases:["Bardo", "Clérigo", "Mago"], desc:"Inscribís un glifo dañino sobre una superficie o dentro de un objeto cerrable (libro, rollo, cofre), en un área de hasta 10 ft de diámetro; si el objeto se mueve más de 10 ft de donde lanzaste el hechizo, el glifo se rompe sin activarse. Es casi invisible: hallarlo requiere prueba de Inteligencia (Investigación) contra tu CD. Definís el disparador (tocarlo, pisarlo, quitar lo que lo cubre, acercarse, abrir el objeto, verlo o leerlo), que podés refinar por rasgos físicos, tipo de criatura o alineamiento, con excepciones (p. ej. una contraseña). Al activarse, el hechizo termina. Elegís al crearlo: Runas explosivas, esfera de 20 ft de radio centrada en el glifo (rodea esquinas); salvación de Destreza, 5d8 de daño de ácido, frío, fuego, relámpago o trueno (a elección) o mitad si salva. Glifo de conjuro, almacenás un hechizo preparado de nivel 3 o menor (que apunte a una criatura o un área) lanzándolo al crearlo, sin efecto inmediato; al activarse se lanza sobre la criatura que lo disparó (o centrado en ella), y las criaturas hostiles u objetos dañinos aparecen cerca del intruso y lo atacan. A niveles superiores: +1d8 a las runas por nivel de espacio por encima de 3; el glifo de conjuro puede almacenar un hechizo de hasta el nivel del espacio usado.", desc2024:"En 2024 la duración es hasta que se disipe o se active, el material es solo polvo de diamante de 200+ gp (consumido) y el glifo se nota con una prueba de Sabiduría (Percepción) contra tu CD (en vez de Inteligencia (Investigación)). Lo inscribís en una superficie u objeto cerrable, de hasta 10 ft de diámetro (si se mueve más de 10 ft, se rompe), con un disparador que podés refinar por tipo de criatura. Runa explosiva: esfera de 20 ft de radio, salvación de Destreza, 5d8 de daño de ácido, frío, fuego, relámpago o trueno (a elección) o mitad si salva. Glifo de conjuro: almacenás un hechizo preparado de nivel 3 o menor que se aplica sobre la criatura que dispara el glifo (o centrado en ella). A niveles superiores: +1d8 a la runa por nivel de espacio por encima de 3, o el glifo almacena un hechizo de hasta el nivel del espacio usado."},
{name:"Hypnotic Pattern", nivel:3, edicion:"ambas", etiquetas:["control", "ilusión", "salvación"], escuela:"Ilusión", tiempo:"1 Acción", alcance:"120 ft", componentes:"S, M (una varilla de incienso brillante o un vial de cristal con material fosforescente)", duracion:"Conc., hasta 1 min", clases:["Bardo", "Hechicero", "Brujo", "Mago"], desc:"Creás un patrón de colores retorcidos en un cubo de 30 ft dentro del alcance; aparece un instante y se desvanece. Cada criatura en el área que lo vea hace salvación de Sabiduría; si falla queda Hechizada durante la duración, y mientras lo está está Incapacitada y con velocidad 0. El efecto termina para una criatura si recibe daño o si alguien usa una acción para sacudirla de su estupor."},
{name:"Lightning Bolt", nivel:3, edicion:"ambas", etiquetas:["daño", "rayo", "salvación"], escuela:"Evocación", tiempo:"1 Acción", alcance:"Personal (línea de 100 ft)", componentes:"V, S, M (un poco de piel y una varilla de ámbar, cristal o vidrio)", duracion:"Instantáneo", clases:["Hechicero", "Mago"], desc:"Un rayo en línea de 100 ft de largo y 5 ft de ancho sale de vos en la dirección que elijas. Cada criatura en la línea hace salvación de Destreza: sufre 8d6 daño de relámpago (mitad si salva). Enciende los objetos inflamables del área que nadie lleve puestos ni cargados. A niveles superiores: el daño sube 1d6 por cada nivel de espacio por encima de 3.", desc2024:"En 2024 el rayo ya no enciende los objetos inflamables del área; el resto no cambia (línea de 100 ft por 5 ft, 8d6 daño de relámpago, mitad si salva Destreza; +1d6 por nivel de espacio sobre 3). El material pasa a ser un poco de piel y una varilla de cristal."},
{name:"Magic Circle", nivel:3, edicion:"ambas", etiquetas:["protección", "control", "salvación"], escuela:"Abjuración", tiempo:"1 minuto", alcance:"10 ft", componentes:"V, S, M (agua bendita o plata en polvo y hierro por un valor de al menos 100 po, que el conjuro consume)", duracion:"1 hora", clases:["Clérigo", "Paladín", "Brujo", "Mago"], desc:"Creás un cilindro de energía mágica de 10 ft de radio y 20 ft de alto centrado en un punto del suelo que veas a tu alcance, con runas brillantes donde toca una superficie. Elegís uno o más tipos: celestiales, elementales, feéricos, infernales o no-muertos. Una criatura de ese tipo no puede entrar voluntariamente al cilindro por medios no mágicos (si intenta teletransportarse o viajar entre planos para entrar, primero debe superar una salvación de Carisma); tiene desventaja en ataques contra objetivos dentro; y los objetivos dentro no pueden ser hechizados, asustados ni poseídos por ella. Al lanzarlo podés invertir la magia: impide que esas criaturas salgan y protege a los objetivos de afuera. A niveles superiores: +1 hora de duración por nivel de espacio sobre 3."},
{name:"Major Image", nivel:3, edicion:"ambas", etiquetas:["ilusión"], escuela:"Ilusión", tiempo:"1 Acción", alcance:"120 ft", componentes:"V, S, M (un poco de vellón)", duracion:"Conc., hasta 10 min", clases:["Bardo", "Hechicero", "Brujo", "Mago"], desc:"Creás la imagen de un objeto, criatura u otro fenómeno visible de no más de un cubo de 20 ft, en un punto que veas a tu alcance. Parece completamente real, con sonidos, olores y temperatura apropiados, pero no puede crear calor o frío que dañe, un sonido que cause daño de trueno o ensordezca, ni un olor que descomponga. Mientras estés a su alcance, usás tu acción para moverla a otro punto a tu alcance y ajustar su aspecto para que sus movimientos parezcan naturales; podés cambiar los sonidos (incluso hacerla conversar). La interacción física revela que es una ilusión (las cosas la atraviesan). Una criatura que use su acción para examinarla la detecta con una prueba de Inteligencia (Investigación) contra tu CD de conjuros; si lo logra, ve a través de ella y sus demás cualidades sensoriales se atenúan. A niveles superiores: con un espacio de nivel 6 o superior, el conjuro dura hasta que se disipe, sin concentración.", desc2024:"En 2024 la imagen no puede infligir daño ni causar condiciones. Moverla requiere una acción de Magia, y examinarla requiere la acción Estudiar (prueba de Inteligencia (Investigación) contra tu CD de conjuros). A niveles superiores: con un espacio de nivel 4 o superior, dura hasta que se disipe, sin concentración."},
{name:"Mass Healing Word", nivel:3, edicion:"ambas", etiquetas:["curación"], escuela:"Evocación", tiempo:"1 Acción Adicional", alcance:"60 ft", componentes:"V", duracion:"Instantáneo", clases:["Clérigo"], desc:"Hasta seis criaturas de tu elección que veas en alcance recuperan PG iguales a 1d4 + tu modificador de característica de lanzamiento. No tiene efecto en no-muertos ni constructos. A niveles superiores: +1d4 de curación por cada nivel de espacio por encima de 3.", desc2024:"En 2024 es de escuela Abjuración, también lo lanzan los Bardos, la curación es 2d4 + tu modificador de característica de lanzamiento (ya no excluye no-muertos ni constructos en el texto). Afecta hasta a seis criaturas que veas en alcance. A niveles superiores: +1d4 por cada nivel de espacio por encima de 3."},
{name:"Nondetection", nivel:3, edicion:"ambas", etiquetas:["protección", "utilidad"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S, M (una pizca de polvo de diamante por 25 gp esparcida sobre el objetivo, que el hechizo consume)", duracion:"8 horas", clases:["Bardo", "Ranger", "Mago"], desc:"Mientras dure, ocultás a un objetivo que tocás de la magia de adivinación. Puede ser una criatura voluntaria, un lugar o un objeto de no más de 10 ft por lado. El objetivo no puede ser blanco de magia de adivinación ni ser percibido mediante sensores mágicos de escudriñamiento."},
{name:"Phantom Steed", nivel:3, edicion:"ambas", etiquetas:["invocación", "utilidad"], escuela:"Ilusión", tiempo:"1 minuto (ritual)", alcance:"30 ft", componentes:"V, S", duracion:"1 hora", clases:["Mago"], desc:"Una criatura Grande, cuasi real y con forma de caballo aparece en un espacio libre a alcance; decidís su aspecto y viene con silla, freno y brida (el equipo desaparece si se aleja más de 10 ft de la montura). Mientras dure, vos o una criatura que elijas pueden montarla. Usa las estadísticas de un caballo de monta, pero con velocidad de 100 ft; recorre 10 mi en una hora, o 13 mi a paso rápido. Al terminar se desvanece gradualmente y el jinete tiene 1 minuto para desmontar. El conjuro termina si lo disipás con una acción o si la montura sufre cualquier daño."},
{name:"Remove Curse", nivel:3, edicion:"ambas", etiquetas:["utilidad"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S", duracion:"Instantáneo", clases:["Clérigo", "Paladín", "Brujo", "Mago"], desc:"Al tocarla, terminan todas las maldiciones que afecten a una criatura u objeto. Si es un objeto mágico maldito, su maldición permanece, pero el conjuro rompe la sintonización de su dueño con él, de modo que pueda quitárselo o descartarlo."},
{name:"Revivify", nivel:3, edicion:"ambas", etiquetas:["curación"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S, M (diamantes valuados en 300 po, que el conjuro consume)", duracion:"Instantáneo", clases:["Clérigo", "Paladín"], desc:"Tocás a una criatura que murió en el último minuto: vuelve a la vida con 1 PG. No puede devolver a la vida a una criatura que murió de vejez ni restaura partes del cuerpo faltantes."},
{name:"Sending", nivel:3, edicion:"ambas", etiquetas:["utilidad"], escuela:"Evocación", tiempo:"1 Acción", alcance:"Ilimitado", componentes:"V, S, M (un trozo corto de alambre fino de cobre)", duracion:"1 turno", clases:["Bardo", "Clérigo", "Mago"], desc:"Enviás un mensaje corto de 25 palabras o menos a una criatura que conozcas. La criatura lo oye en su mente, te reconoce como emisor si te conoce y puede responder del mismo modo de inmediato. Permite que criaturas con Inteligencia 1 o más entiendan el mensaje. Funciona a cualquier distancia e incluso entre planos, pero si el objetivo está en otro plano hay 5% de probabilidad de que el mensaje no llegue.", desc2024:"En 2024 es Instantáneo y el objetivo debe ser una criatura que hayas conocido o que te hayan descrito quien la conoce. Mensaje de 25 palabras o menos que el objetivo oye en su mente y al que puede responder; funciona entre planos, con 5% de que no llegue (y sabés si falló). Al recibirlo, la criatura puede bloquearte durante 8 horas: si intentás enviar otro mensaje, sabés que estás bloqueado y el hechizo falla."},
{name:"Slow", nivel:3, edicion:"ambas", etiquetas:["control", "salvación"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"120 ft", componentes:"V, S, M (una gota de melaza)", duracion:"Conc., hasta 1 min", clases:["Hechicero", "Mago"], desc:"Alterás el tiempo alrededor de hasta seis criaturas a tu elección en un cubo de 40 ft a tu alcance; cada una debe superar una salvación de Sabiduría o queda afectada. Un objetivo afectado tiene la velocidad reducida a la mitad, -2 a la CA y a las salvaciones de Destreza, no puede usar reacciones, y en su turno puede usar una acción o una acción adicional, no ambas; además no puede hacer más de un ataque cuerpo a cuerpo o a distancia en su turno. Si intenta lanzar un hechizo de 1 acción, tira un d20: con 11 o más, el hechizo no surte efecto hasta su próximo turno y debe usar su acción entonces para completarlo; si no puede, se pierde. Al final de cada uno de sus turnos repite la salvación de Sabiduría; si la supera, el efecto termina para él.", desc2024:"En 2024 el hechizo también está en la lista de Bardo. Hasta seis criaturas en un cubo de 40 ft hacen salvación de Sabiduría o quedan afectadas: velocidad a la mitad, -2 a la CA y a las salvaciones de Destreza, sin reacciones; en su turno usa una acción o una acción adicional, no ambas, y si usa la acción de Atacar hace solo un ataque. Si lanza un hechizo con componente somático, hay 25% de probabilidad de que falle por hacer los gestos demasiado lento (ya no existe la tirada de d20 por tiempo de lanzamiento). Repite la salvación al final de cada uno de sus turnos y, si la supera, termina el efecto en él."},
{name:"Speak with Dead", nivel:3, edicion:"ambas", etiquetas:["adivinación", "utilidad"], escuela:"Necromancia", tiempo:"1 Acción", alcance:"10 ft", componentes:"V, S, M (incienso encendido)", duracion:"10 minutos", clases:["Bardo", "Clérigo"], desc:"Otorgás una apariencia de vida e inteligencia a un cadáver a alcance, que debe conservar la boca y no ser un muerto viviente; falla si fue objetivo de este conjuro en los últimos 10 días. Mientras dure, podés hacerle hasta cinco preguntas. Solo sabe lo que sabía en vida, incluidos sus idiomas; las respuestas suelen ser breves, crípticas o repetitivas, y no está obligado a decir la verdad si le sos hostil o te reconoce como enemigo. No devuelve el alma, solo el espíritu animador: no aprende información nueva, no comprende lo ocurrido desde su muerte ni puede especular sobre el futuro."},
{name:"Spirit Guardians", nivel:3, edicion:"ambas", etiquetas:["daño", "radiante", "necrótico", "salvación", "control", "protección"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"Personal (radio de 15 ft)", componentes:"V, S, M (un símbolo sagrado)", duracion:"Conc., hasta 10 min", clases:["Clérigo"], desc:"Espíritus protectores revolotean a tu alrededor en un radio de 15 ft (angelicales o feéricos si sos bueno o neutral, a elección; infernales si sos malvado). Podés designar criaturas que no se vean afectadas. La velocidad de las demás se reduce a la mitad en el área, y cuando una entra por primera vez en un turno o empieza su turno ahí hace salvación de Sabiduría: si falla sufre 3d8 daño radiante (si sos bueno o neutral) o necrótico (si sos malvado); mitad si salva. A niveles superiores: +1d8 por cada nivel de espacio por encima de 3.", desc2024:"En 2024 el área es una emanación de 15 ft (el material es un pergamino de oración) y la salvación de Sabiduría también se hace cuando la emanación entra en el espacio de una criatura o cuando una criatura entra o termina su turno en ella; cada criatura la hace solo una vez por turno. Mismo daño (3d8 radiante o necrótico, mitad si salva; +1d8 por nivel sobre 3) y misma reducción de velocidad a la mitad."},
{name:"Stinking Cloud", nivel:3, edicion:"ambas", etiquetas:["control", "salvación"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"90 ft", componentes:"V, S, M (un huevo podrido o varias hojas de col de zorrillo)", duracion:"Conc., hasta 1 min", clases:["Bardo", "Hechicero", "Mago"], desc:"Creás una esfera de gas amarillo y nauseabundo de 20 ft de radio centrada en un punto a tu alcance; la nube dobla esquinas, su área está muy oscurecida y permanece mientras dure. Cada criatura completamente dentro de la nube al inicio de su turno hace una salvación de Constitución contra veneno; si falla, gasta su acción de ese turno vomitando y tambaleándose. Las criaturas que no respiran o son inmunes al veneno superan la salvación automáticamente. Un viento moderado (10 mi/h o más) la dispersa tras 4 asaltos; uno fuerte (20 mi/h o más), tras 1 asalto.", desc2024:"La esfera de 20 ft de radio queda muy oscurecida y dura hasta que termine el conjuro o la disperse un viento fuerte (como el de Gust of Wind). Cada criatura que empiece su turno en la esfera debe superar una salvación de Constitución o queda Envenenada hasta el final del turno actual; mientras esté así, no puede realizar acciones ni acciones adicionales (ya no se pierde solo la acción, ni hay inmunidad automática ni dispersión por viento moderado)."},
{name:"Tiny Hut", nivel:3, edicion:"ambas", etiquetas:["utilidad", "protección"], escuela:"Evocación", tiempo:"1 minuto (ritual)", alcance:"Personal (cúpula de 10 ft)", componentes:"V, S, M (una pequeña cuenta de cristal)", duracion:"8 horas", clases:["Bardo", "Mago"], desc:"Una cúpula inmóvil de fuerza de 10 ft de radio surge alrededor y por encima de vos y permanece fija toda la duración; el conjuro termina si salís de su área. Caben contigo hasta nueve criaturas de tamaño Mediano o menor (si el área incluye una criatura mayor o más de nueve, el conjuro falla). Las criaturas y objetos dentro al lanzarlo pueden atravesarla libremente; todo lo demás no puede pasar. Los conjuros y otros efectos mágicos no pueden extenderse a través de ella ni lanzarse a través de ella. El ambiente interior es cómodo y seco sin importar el clima. Podés ordenar que el interior esté en luz tenue u oscuridad. La cúpula es opaca desde afuera (del color que elijas) y transparente desde adentro.", desc2024:"En 2024 es una Emanación de 10 ft alrededor de vos (sin límite de nueve criaturas: el conjuro falla si no puede abarcar completamente a todas las criaturas en su área). Los conjuros de nivel 3 o inferior no pueden lanzarse a través de ella ni sus efectos extenderse hacia adentro. Cambiás la luz interior a tenue u oscuridad sin necesidad de acción. Termina antes si salís de la Emanación o si lo lanzás de nuevo."},
{name:"Tongues", nivel:3, edicion:"ambas", etiquetas:["utilidad"], escuela:"Adivinación", tiempo:"1 Acción", alcance:"Toque", componentes:"V, M (un pequeño modelo de arcilla de un zigurat)", duracion:"1 hora", clases:["Bardo", "Clérigo", "Hechicero", "Brujo", "Mago"], desc:"La criatura que tocás puede entender cualquier idioma hablado que oiga. Además, cuando el objetivo habla, cualquier criatura que conozca al menos un idioma y pueda oírlo entiende lo que dice.", desc2024:"En 2024 también cubre lenguaje de señas: el objetivo entiende cualquier idioma hablado o por señas que oiga o vea, y cuando habla o hace señas, cualquier criatura que conozca al menos un idioma lo entiende si puede oírlo o verlo."},
{name:"Vampiric Touch", nivel:3, edicion:"ambas", etiquetas:["daño", "necrótico", "ataque", "curación"], escuela:"Necromancia", tiempo:"1 Acción", alcance:"Personal", componentes:"V, S", duracion:"Conc., hasta 1 min", clases:["Brujo", "Mago"], desc:"Tu mano envuelta en sombras absorbe fuerza vital para curar tus heridas. Ataque de conjuro cuerpo a cuerpo contra una criatura a tu alcance: si impacta, 3d6 de daño necrótico y recuperás PG iguales a la mitad del daño necrótico infligido. Hasta que termine el conjuro, podés repetir el ataque en cada uno de tus turnos como acción. A niveles superiores: +1d6 por cada nivel de espacio por encima de 3.", desc2024:"En 2024: también está en la lista del Hechicero. Repetís el ataque cada turno con la acción Magia, contra la misma criatura o una distinta; el resto igual (3d6 de daño necrótico, recuperás la mitad como PG, +1d6 por nivel de espacio por encima de 3)."},

// ===== NIVEL 4 =====
{name:"Blight", nivel:4, edicion:"ambas", etiquetas:["daño","necrótico","salvación"], escuela:"Necromancia", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, S", duracion:"Instantáneo", clases:["Druida","Hechicero","Brujo","Mago"], desc2024:"Una criatura que veas a 30 ft hace salvación de Constitución, sufriendo 8d8 de daño necrótico (mitad si salva). Una criatura Planta falla la salvación automáticamente (ya no se trata de desventaja y daño máximo, y ya no excluye a no-muertos y constructos). También podés apuntar a una planta no mágica que no sea criatura: se marchita y muere sin salvación. A niveles superiores: +1d8 por nivel por encima de 4.", desc:"Energía necrótica drena vida de una criatura a tu alcance (salvación de Constitución), 8d8 daño necrótico (mitad si salva). Marchita instantáneamente plantas no mágicas en un radio de 10 ft."},
{name:"Confusion", nivel:4, edicion:"ambas", etiquetas:["control","salvación"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"90 ft", componentes:"V, S, M (nuez moscada, ojo de pescado y algo blanco)", duracion:"Conc., hasta 1 min", clases:["Bardo","Druida","Hechicero","Mago"], desc2024:"Cada criatura en una esfera de 10 ft de radio a 90 ft debe superar una salvación de Sabiduría o no puede realizar acciones adicionales ni reacciones, y al inicio de cada uno de sus turnos tira 1d10: 1 = usa todo su movimiento en una dirección aleatoria y no realiza acciones; 2-6 = no se mueve ni actúa; 7-8 = no se mueve y usa su acción para atacar cuerpo a cuerpo a una criatura al azar a su alcance (si no hay, no hace nada); 9-10 = elige su comportamiento. Al final de cada uno de sus turnos repite la salvación y, si la supera, el conjuro termina para ella. A niveles superiores: +5 ft de radio por nivel sobre el 4º.", desc:"Las criaturas en un radio de 10 ft hacen salvación de Sabiduría o actúan de forma errática/aleatoria durante la duración."},
{name:"Conjure Minor Elementals", nivel:4, edicion:"ambas", etiquetas:["invocación"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"90 ft", componentes:"V, S", duracion:"Conc., hasta 1 hora", clases:["Druida","Mago"], desc2024:"En 2024 ya no invoca criaturas: es un hechizo de lanzamiento Personal (1 Acción, concentración hasta 10 min). Espíritus de los Planos Elementales revolotean en una emanación de 15 ft a tu alrededor; mientras dure, cada ataque tuyo que impacte a una criatura en la emanación inflige 2d8 de daño adicional, de ácido, frío, fuego o relámpago (lo elegís al atacar). Además, el suelo en la emanación es terreno difícil para tus enemigos. A niveles superiores: +1d8 por cada nivel de espacio por encima de 4.", desc:"Invocás criaturas elementales (equivalente a CR total 4, o combinación menor) que combaten a tu lado."},
{name:"Conjure Woodland Beings", nivel:4, edicion:"ambas", etiquetas:["invocación"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S, M (mistletoe)", duracion:"Conc., hasta 1 hora", clases:["Druida","Ranger"], desc2024:"Cambia por completo: alcance Personal, duración Conc., hasta 10 minutos y ya no invoca criaturas. Espíritus de la naturaleza revolotean a tu alrededor en una emanación de 10 ft. Cuando la emanación entra en el espacio de una criatura que veas, o una criatura que veas entra en ella o termina su turno ahí, podés obligarla a hacer una salvación de Sabiduría: sufre 5d8 daño de fuerza si falla, la mitad si supera. Una criatura hace esta salvación solo una vez por turno. Además podés usar Retirarse como acción adicional mientras dure. A niveles superiores: +1d8 por nivel de espacio sobre 4.", desc:"Invocás espíritus feéricos del bosque (equivalente a CR total 4, o combinación menor) que combaten a tu lado.", upcast:{tipo:"tabla", nivelBase:4, tabla:{
  4:"CR total 4 en espíritus feéricos (o combinación de menor CR, proporcional).",
  5:"El doble que a nivel 4.",
  6:"El triple que a nivel 4.",
  7:"Cuádruple que a nivel 4.",
  8:"Quíntuple que a nivel 4.",
  9:"Séxtuple que a nivel 4.",
}}},
{name:"Control Water", nivel:4, edicion:"ambas", etiquetas:["control"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"300 ft", componentes:"V, S, M (gota de agua y pizca de polvo)", duracion:"Conc., hasta 10 min", clases:["Clérigo","Druida","Mago"], desc2024:"En 2024 las acciones posteriores para repetir o cambiar el efecto son acciones de Magia. Flood, Part Water y Redirect Flow funcionan igual. En Whirlpool (requiere agua de al menos 50 ft de lado y 25 ft de profundidad; vórtice de 5 ft de base, hasta 50 ft arriba y 25 ft de alto; atrae 10 ft a lo que esté a 25 ft), la salvación de Fuerza se hace al entrar por primera vez en un turno o al terminar su turno allí (2d8 daño contundente, mitad si salva); ya no queda atrapada, pero para alejarse a nado debe usar una acción para zafarse y superar una prueba de Fuerza (Atletismo) contra tu CD.", desc:"Controlás agua en un cubo de 100 ft: inundar, crear una ola, redirigir una corriente, o abrir un pasaje seco."},
{name:"Dominate Beast", nivel:4, edicion:"ambas", etiquetas:["control"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S", duracion:"Conc., hasta 1 min", clases:["Druida","Hechicero"], desc2024:"En 2024 también está en la lista de Explorador y afecta a una Bestia que veas a alcance: hace salvación de Sabiduría o queda Hechizada (ventaja si vos o tus aliados la combaten) y repite la salvación cada vez que sufre daño, terminando el conjuro si la supera. Tenés un vínculo telepático y le das órdenes en tu turno sin acción; si cumple una orden sin nueva dirección, actúa como quiera, protegiéndose. Ya no hay control total y preciso. Podés ordenarle usar una reacción gastando la tuya. A niveles superiores: concentración de hasta 10 min con espacio de nivel 5, 1 hora con nivel 6 y 8 horas con nivel 7 o más.", desc:"Una bestia a tu alcance hace salvación de Sabiduría o queda hechizada; podés ordenarle mentalmente mientras dure el conjuro."},
{name:"Freedom of Movement", nivel:4, edicion:"ambas", etiquetas:["buff"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S, M (correa de cuero)", duracion:"1 hora", clases:["Bardo","Clérigo","Druida","Ranger"], desc2024:"En 2024 la criatura voluntaria que tocás ignora el terreno difícil, ningún conjuro ni efecto mágico puede reducir su velocidad ni dejarla Paralizada o Apresada, y además obtiene una velocidad de nado igual a su velocidad. Puede gastar 5 ft de movimiento para escapar automáticamente de ataduras no mágicas (grilletes, o una criatura que la tiene Agarrada).", desc:"La criatura tocada ignora terreno difícil, y no puede quedar paralizada, apresada ni con velocidad reducida durante la duración."},
{name:"Giant Insect", nivel:4, edicion:"ambas", etiquetas:["invocación"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, S", duracion:"Conc., hasta 10 min", clases:["Druida"], desc2024:"En 2024 cambia por completo: es una invocación (Conjuración) de alcance 60 ft. Invocás un ciempiés, una araña o una avispa gigante (a elección) en un espacio libre que veas, con el stat block Giant Insect: Bestia Grande, CA 11 + nivel del hechizo, PG 30 + 10 por cada nivel por encima de 4, velocidad 40 ft (trepa 40 ft; la avispa vuela 40 ft). Es aliada tuya: comparte tu iniciativa y actúa justo después de vos, obedece órdenes verbales sin costarte acción y, sin órdenes, usa Esquivar. Multiataque: ataques iguales a la mitad del nivel del hechizo (redondeo hacia abajo), Poison Jab (ataque de conjuro, alcance 10 ft, 1d6 + 3 + nivel de perforante más 1d4 de veneno); la araña lanza Web Bolt (60 ft, 1d10 + 3 + nivel contundente y velocidad 0 hasta el inicio de su siguiente turno) y el ciempiés Venomous Spew (acción adicional, salvación de Constitución, Envenenado hasta su siguiente turno). Desaparece a 0 PG o al terminar. Dura hasta 10 min con concentración.", desc:"Transformás hasta 10 ciempiés/3 arañas/5 avispas/1 escorpión que veas en versiones gigantes durante la duración, bajo tu control.", upcast:{tipo:"tabla", nivelBase:4, tabla:{
  4:"Base: hasta 10 ciempiés / 3 arañas / 5 avispas / 1 escorpión gigante.",
  5:"+1 criatura adicional transformada (respetando los límites por tipo).",
  6:"+2 criaturas adicionales.",
  7:"+3 criaturas adicionales.",
  8:"+4 criaturas adicionales.",
  9:"+5 criaturas adicionales.",
}}},
{name:"Hallucinatory Terrain", nivel:4, edicion:"ambas", etiquetas:["ilusión"], escuela:"Ilusión", tiempo:"10 minutos", alcance:"300 ft", componentes:"V, S, M (piedra, ramita y trozo de raíz verde)", duracion:"24 horas", clases:["Bardo","Druida","Mago"], desc:"Hacés que un terreno de 150 ft de cubo parezca otro tipo de terreno (árboles, colinas, pantano, etc.) hasta que se investigue activamente."},
{name:"Ice Storm", nivel:4, edicion:"ambas", etiquetas:["daño","frío","contundente","salvación"], escuela:"Evocación", tiempo:"1 Acción", alcance:"300 ft", componentes:"V, S, M (una piedra fría)", duracion:"Instantáneo", clases:["Druida","Hechicero","Mago"], desc2024:"Cae granizo en un cilindro de 20 ft de radio y 40 ft de alto a 300 ft; cada criatura hace salvación de Destreza y sufre 2d10 daño contundente + 4d6 daño de frío (mitad si salva). El suelo queda como terreno difícil hasta el final de tu próximo turno. A niveles superiores: +1d10 contundente por nivel sobre el 4º (en 2024 el dado es d10, antes d8).", desc:"Granizo cae en un cilindro de 20 ft; cada criatura ahí hace salvación de Destreza, sufriendo 2d8 contundente + 4d6 frío (mitad si salva). El terreno queda difícil."},
{name:"Locate Creature", nivel:4, edicion:"ambas", etiquetas:["utilidad"], escuela:"Adivinación", tiempo:"1 Acción", alcance:"Personal", componentes:"V, S, M (trozo de piel de sabueso)", duracion:"Conc., hasta 1 hora", clases:["Bardo","Clérigo","Druida","Paladín","Ranger"], desc2024:"En 2024: lo que bloquea el hechizo cambia: ya no es el agua corriente de 10 ft de ancho sino cualquier espesor de plomo entre vos y la criatura. Además no la localiza si está bajo los efectos de Flesh to Stone o Polymorph. El resto es igual (1000 ft, dirección y movimiento, criatura conocida o la más cercana de un tipo vista a 30 ft).", desc:"Sentís la dirección hacia una criatura específica (o tipo de criatura) conocida, a 1000 ft, mientras dure el conjuro."},
{name:"Polymorph", nivel:4, edicion:"ambas", etiquetas:["control"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S, M (capullo de oruga)", duracion:"Conc., hasta 1 hora", clases:["Bardo","Druida","Hechicero","Mago"], desc2024:"En 2024 la criatura que veas a tu alcance debe superar una salvación de Sabiduría o se transforma en una Bestia de tu elección con CR igual o menor al del objetivo (o a su nivel). Sus estadísticas se reemplazan por las de la Bestia, pero conserva alineamiento, personalidad, tipo de criatura, PG y dados de golpe. Gana PG temporales iguales a los PG de la forma bestial (se pierden al terminar el conjuro); el conjuro termina para ella si se queda sin PG temporales. Sus acciones están limitadas por la anatomía de la nueva forma y no puede hablar ni lanzar conjuros; su equipo se funde con la forma y no puede usarlo.", desc:"Una criatura a tu alcance (salvación de Sabiduría si no es voluntaria) se transforma en una bestia de CR igual o menor durante la duración."},
{name:"Stone Shape", nivel:4, edicion:"ambas", etiquetas:["utilidad"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S, M (arcilla blanda)", duracion:"Instantáneo", clases:["Clérigo","Druida","Mago"], desc:"Moldeás un objeto de piedra tocado (hasta Mediano) en cualquier forma que desees dentro de sus dimensiones."},
{name:"Stoneskin", nivel:4, edicion:"ambas", etiquetas:["buff"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S, M (diamante en polvo, 100 gp, consumido)", duracion:"Conc., hasta 1 hora", clases:["Druida","Ranger","Hechicero","Mago"], desc2024:"Una criatura voluntaria que tocás gana resistencia al daño contundente, perforante y cortante (en 2024 ya no solo no mágico) mientras dure el conjuro (concentración, hasta 1 hora). Requiere polvo de diamante de 100+ po, que se consume.", desc:"La criatura tocada gana resistencia a daño contundente, perforante y cortante no mágico durante la duración."},
{name:"Wall of Fire", nivel:4, edicion:"ambas", etiquetas:["daño","fuego","control"], escuela:"Evocación", tiempo:"1 Acción", alcance:"120 ft", componentes:"V, S, M (fósforo pequeño)", duracion:"Conc., hasta 1 min", clases:["Druida","Hechicero","Mago"], desc:"Creás un muro de fuego (línea o anillo); las criaturas en el área de aparición o que lo atraviesen sufren 5d8 daño de fuego (salvación de Destreza para mitad); calienta a quienes estén a 10 ft de un lado."},
{name:"Greater Invisibility", nivel:4, edicion:"ambas", etiquetas:["buff","ilusión"], escuela:"Ilusión", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S", duracion:"Conc., hasta 1 min", clases:["Bardo","Hechicero","Mago"], desc:"La criatura tocada se vuelve invisible durante la duración, incluso al atacar o ser atacada (a diferencia de Invisibility normal)."},
{name:"Summon Fey", nivel:4, etiquetas:["invocación"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"90 ft", componentes:"V, S, M (equipo de valor 25+ gp)", duracion:"Conc., hasta 1 hora", clases:["Druida","Brujo"], desc:"[2024] Invocás un espíritu feérico (Fuentes: Alegre/Malicioso/Astuto) que combate a tu lado; sus estadísticas escalan con el nivel del espacio usado.", upcast:{tipo:"tabla", nivelBase:4, tabla:{
  4:"Espíritu Feérico nivel base — ver bloque de estadísticas 'Fey Spirit' para nivel de espacio 4.",
  5:"Ver bloque de estadísticas 'Fey Spirit' para nivel de espacio 5 (HP/ataque/daño mayores).",
  6:"Ver bloque de estadísticas 'Fey Spirit' para nivel de espacio 6.",
  7:"Ver bloque de estadísticas 'Fey Spirit' para nivel de espacio 7.",
  8:"Ver bloque de estadísticas 'Fey Spirit' para nivel de espacio 8.",
  9:"Ver bloque de estadísticas 'Fey Spirit' para nivel de espacio 9.",
}}},
{name:"Arcane Eye", nivel:4, edicion:"ambas", etiquetas:["adivinación", "utilidad"], escuela:"Adivinación", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, S, M (un poco de pelo de murciélago)", duracion:"Conc., hasta 1 hora", clases:["Clérigo", "Mago"], desc:"Creás un ojo mágico invisible en el alcance que flota en el aire mientras dure. Recibís mentalmente lo que ve, con visión normal y visión en la oscuridad a 30 ft, en todas direcciones. Con una acción lo movés hasta 30 ft en cualquier dirección, sin límite de distancia a vos, pero no puede cambiar de plano. Una barrera sólida lo detiene, aunque pasa por una abertura de 1 pulgada.", desc2024:"En 2024: el ojo es invisible e invulnerable y lo movés hasta 30 ft con una acción adicional (no con una acción); solo lo aprende el Mago. Sigue viendo en todas direcciones y con visión en la oscuridad a 30 ft; una barrera sólida lo detiene, pero pasa por una abertura de 1 pulgada."},
{name:"Aura of Life", nivel:4, edicion:"2024", etiquetas:["protección", "curación"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"Personal (emanación de 30 ft)", componentes:"V", duracion:"Conc., hasta 10 min", clases:["Clérigo", "Paladín"], desc:"Un aura de 30 ft de emanación irradia de vos mientras dure. Dentro de ella, vos y tus aliados tenés resistencia al daño necrótico y vuestro máximo de PG no puede reducirse. Si un aliado con 0 PG empieza su turno en el aura, recupera 1 PG."},
{name:"Banishment", nivel:4, edicion:"ambas", etiquetas:["control", "salvación"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S, M (un objeto que le desagrade al objetivo)", duracion:"Conc., hasta 1 min", clases:["Clérigo", "Paladín", "Hechicero", "Brujo", "Mago"], desc:"Intentás enviar a otro plano a una criatura que veas a tu alcance; debe superar una tirada de salvación de Carisma o queda desterrada. Si es nativa del plano en que estás, va a un semiplano inofensivo donde queda Incapacitada hasta que termine el conjuro, y entonces reaparece en el espacio que dejó (o el libre más cercano). Si es nativa de otro plano, regresa a su plano de origen; si el conjuro termina antes de que pase 1 minuto, reaparece en el espacio que dejó (o el libre más cercano); si no, no vuelve. A niveles superiores: podés afectar a una criatura adicional por cada nivel de espacio por encima del 4.º.", desc2024:"En 2024 el alcance es 30 ft y el componente material es un pentáculo. El objetivo que falla la salvación de Carisma es enviado a un semiplano inofensivo, Incapacitado durante la duración; al terminar reaparece en el espacio que dejó (o el libre más cercano). Si es Aberración, Celestial, Elemental, Feérico o Demonio y el conjuro dura 1 minuto, no regresa: es transportado a un lugar aleatorio de un plano (a elección del DM) asociado a su tipo. A niveles superiores: una criatura adicional por cada nivel de espacio por encima del 4.º."},
{name:"Black Tentacles", nivel:4, edicion:"ambas", etiquetas:["daño", "contundente", "control", "salvación", "invocación"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"90 ft", componentes:"V, S, M (un trozo de tentáculo de pulpo o calamar gigante)", duracion:"Conc., hasta 1 min", clases:["Mago"], desc:"Tentáculos de ébano llenan un cuadrado de 20 ft en el suelo que veas en alcance y vuelven el área terreno difícil. Cuando una criatura entra por primera vez en un turno o empieza su turno allí, debe superar una salvación de Destreza o sufrir 3d6 daño contundente y quedar Apresada hasta que termine el hechizo. Una criatura que empiece su turno ya Apresada sufre 3d6 daño contundente. Una criatura Apresada puede usar su acción para una prueba de Fuerza o Destreza (a su elección) contra tu CD de conjuro; si tiene éxito, se libera.", desc2024:"En 2024 la salvación es de Fuerza (no de Destreza). Cada criatura en el área hace salvación de Fuerza; si falla, sufre 3d6 daño contundente y queda Apresada hasta que termine el hechizo. También hace la salvación al entrar al área o terminar su turno allí, una sola vez por turno. Una criatura Apresada puede usar una acción para una prueba de Fuerza (Atletismo) contra tu CD de conjuro y se libera si tiene éxito."},
{name:"Charm Monster", nivel:4, edicion:"2024", etiquetas:["control", "salvación"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, S", duracion:"1 hora", clases:["Bardo", "Druida", "Hechicero", "Brujo", "Mago"], desc:"Una criatura que veas a tu alcance hace una salvación de Sabiduría, con ventaja si vos o tus aliados la están combatiendo. Si falla, queda Hechizada hasta que termine el hechizo o hasta que vos o tus aliados le hagan daño; la criatura Hechizada es Amistosa hacia vos. Al terminar el hechizo, el objetivo sabe que fue Hechizado por vos. A niveles superiores: una criatura adicional por cada nivel de espacio por encima de 4."},
{name:"Compulsion", nivel:4, edicion:"ambas", etiquetas:["control", "salvación"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, S", duracion:"Conc., hasta 1 min", clases:["Bardo"], desc:"Las criaturas a tu elección que veas a alcance y puedan oírte hacen salvación de Sabiduría (superan automáticamente si no pueden ser hechizadas); las que fallen quedan afectadas. Mientras dure, en cada uno de tus turnos podés usar una acción adicional para designar una dirección horizontal; cada objetivo afectado debe usar todo el movimiento posible para ir en esa dirección en su próximo turno (puede realizar cualquier acción antes de moverse). Tras moverse así, puede repetir la salvación para terminar el efecto. No se ve obligado a entrar en un peligro obviamente mortal (fuego, foso), pero provoca ataques de oportunidad al moverse en esa dirección.", desc2024:"En 2024 cada criatura a tu elección que veas a alcance (ya no hace falta que pueda oírte) hace salvación de Sabiduría o queda Hechizada hasta que termine el conjuro. Mientras dure, podés usar una acción adicional para designar una dirección horizontal; cada objetivo Hechizado debe usar todo el movimiento posible en esa dirección en su próximo turno, por la ruta más segura. Tras moverse así, repite la salvación y termina el conjuro sobre sí si la supera."},
{name:"Death Ward", nivel:4, edicion:"ambas", etiquetas:["protección"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S", duracion:"8 horas", clases:["Clérigo", "Paladín"], desc:"Tocás a una criatura y le das protección contra la muerte. La primera vez que el objetivo caería a 0 PG por daño, queda en 1 PG y el hechizo termina. Si el hechizo sigue activo cuando el objetivo sufre un efecto que lo mataría al instante sin infligir daño, ese efecto se anula contra él y el hechizo termina."},
{name:"Dimension Door", nivel:4, edicion:"ambas", etiquetas:["teletransporte", "utilidad"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"500 ft", componentes:"V", duracion:"Instantáneo", clases:["Bardo", "Hechicero", "Brujo", "Mago"], desc:"Te teletransportás a cualquier punto en alcance (500 ft) y llegás exactamente al lugar deseado: uno que veas, que visualices o que describas por distancia y dirección (p. ej. “200 ft hacia abajo”). Podés llevar objetos que puedas cargar y a una criatura voluntaria de tu tamaño o menor, con su equipo hasta su capacidad de carga, que esté a 5 ft de vos. Si llegarías a un lugar ocupado por un objeto o criatura, vos y quien te acompañe sufren 4d6 de daño de fuerza y el teletransporte falla."},
{name:"Divination", nivel:4, edicion:"ambas", etiquetas:["adivinación", "utilidad"], escuela:"Adivinación", tiempo:"1 Acción (ritual)", alcance:"Personal", componentes:"V, S, M (incienso y una ofrenda sacrificial acorde a tu religión, valor total de al menos 25 gp, que el hechizo consume)", duracion:"Instantáneo", clases:["Druida"], desc:"Tu magia y una ofrenda te ponen en contacto con un dios o sus sirvientes. Hacés una pregunta sobre una meta, suceso o actividad concreta que ocurrirá dentro de los próximos 7 días. El DM da una respuesta veraz: una frase corta, una rima críptica o un presagio. No tiene en cuenta circunstancias que puedan cambiar el resultado, como lanzar otros hechizos o perder o ganar un compañero. Si lo lanzás dos o más veces antes de terminar tu próximo descanso largo, hay 25% acumulativo por cada lanzamiento posterior al primero de obtener una lectura al azar (el DM tira en secreto).", desc2024:"En 2024 el componente material es solo incienso por 25+ gp (consumido) y el hechizo también está en las listas de Clérigo y Mago. Hacés una pregunta sobre una meta, suceso o actividad dentro de los próximos 7 días; el DM da una respuesta veraz (frase corta o rima críptica) que no considera circunstancias que puedan cambiarla. Si lo lanzás más de una vez antes de terminar un descanso largo, hay 25% acumulativo por cada lanzamiento posterior al primero de no obtener respuesta (en vez de una lectura al azar)."},
{name:"Fabricate", nivel:4, edicion:"ambas", etiquetas:["invocación", "utilidad"], escuela:"Transmutación", tiempo:"10 minutos", alcance:"120 ft", componentes:"V, S", duracion:"Instantáneo", clases:["Mago"], desc:"Convertís materias primas que veas a 120 ft en productos del mismo material (un puente de madera con árboles, una cuerda con cáñamo, ropa con lino o lana). Podés fabricar un objeto Grande o menor (dentro de un cubo de 10 ft u ocho cubos de 5 ft conectados); si el material es metal, piedra u otro mineral, no mayor que Mediano (un cubo de 5 ft). La calidad depende de la de la materia prima. No crea criaturas ni objetos mágicos, ni objetos que requieran gran pericia (joyas, armas, vidrio, armadura) salvo que tengas competencia con las herramientas de artesano correspondientes."},
{name:"Faithful Hound", nivel:4, edicion:"ambas", etiquetas:["invocación", "daño", "perforante", "protección"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, S, M (un pequeño silbato de plata, un trozo de hueso y un hilo)", duracion:"8 horas", clases:["Mago"], desc:"Conjurás un perro guardián fantasma en un espacio libre que veas; permanece mientras dure, hasta que lo despidas con una acción o te alejes más de 100 ft de él. Es invisible para todos salvo vos y no puede ser dañado. Si una criatura Pequeña o mayor se acerca a 30 ft sin decir antes la contraseña que fijaste al lanzarlo, ladra fuerte. Ve criaturas invisibles y el Plano Etéreo e ignora ilusiones. Al inicio de cada uno de tus turnos intenta morder a una criatura hostil a 5 ft: bono de ataque = tu modificador de característica de lanzamiento + competencia; con impacto 4d8 daño perforante.", desc2024:"En 2024: permanece hasta que se separen más de 300 ft, es intangible e invulnerable y solo vos lo ves; tiene visión verdadera a 30 ft. Al inicio de cada uno de tus turnos intenta morder a un enemigo a 5 ft, que hace salvación de Destreza o sufre 4d8 daño de fuerza (ya no hay tirada de ataque). En tus turnos siguientes podés usar la acción Magia para moverlo hasta 30 ft. Sigue ladrando si una criatura Pequeña o mayor se acerca a 30 ft sin decir la contraseña."},
{name:"Fire Shield", nivel:4, edicion:"ambas", etiquetas:["protección", "daño", "fuego", "frío"], escuela:"Evocación", tiempo:"1 Acción", alcance:"Personal", componentes:"V, S, M (un poco de fósforo o una luciérnaga)", duracion:"10 minutos", clases:["Mago"], desc:"Llamas finas y vaporosas rodean tu cuerpo, emitiendo luz brillante en 10 ft de radio y luz tenue otros 10 ft. Podés terminar el conjuro con una acción. Elegís escudo cálido (resistencia al daño de frío) o escudo frío (resistencia al daño de fuego). Además, cuando una criatura a 5 ft te impacta con un ataque cuerpo a cuerpo, el escudo estalla: el atacante sufre 2d8 daño de fuego (escudo cálido) o de frío (escudo frío)."},
{name:"Guardian of Faith", nivel:4, edicion:"ambas", etiquetas:["invocación", "daño", "radiante", "salvación", "protección"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"30 ft", componentes:"V", duracion:"8 horas", clases:["Clérigo"], desc:"Aparece un guardián espectral Grande que flota durante la duración en un espacio libre que veas a tu alcance; ocupa ese espacio y es difuso salvo por una espada y un escudo relucientes con el símbolo de tu deidad. Toda criatura hostil hacia vos que entre por primera vez en un turno a un espacio a 10 ft o menos del guardián debe hacer una salvación de Destreza: sufre 20 de daño radiante si falla, o la mitad si salva. El guardián desaparece cuando ha infligido un total de 60 de daño.", desc2024:"En 2024 el guardián es invulnerable y toma una forma acorde a tu deidad o panteón. Todo enemigo que entre por primera vez en un turno a un espacio a 10 ft o menos del guardián, o que empiece su turno allí, hace una salvación de Destreza: sufre 20 de daño radiante si falla, o la mitad si salva. El guardián desaparece cuando ha infligido un total de 60 de daño."},
{name:"Phantasmal Killer", nivel:4, edicion:"ambas", etiquetas:["daño", "psíquico", "salvación", "control", "ilusión"], escuela:"Ilusión", tiempo:"1 Acción", alcance:"120 ft", componentes:"V, S", duracion:"Conc., hasta 1 min", clases:["Mago"], desc:"Accedés a las pesadillas de una criatura que veas a tu alcance y creás una manifestación ilusoria de sus peores miedos, visible solo para ella. El objetivo hace una salvación de Sabiduría; si falla, queda Asustado mientras dure. Al inicio de cada uno de sus turnos antes de que termine el conjuro, debe superar una salvación de Sabiduría o sufrir 4d10 daño psíquico; si la supera, el conjuro termina. A niveles superiores: +1d10 por nivel de espacio sobre 4.", desc2024:"Ahora el objetivo hace la salvación de Sabiduría de inmediato: si falla, sufre 4d10 daño psíquico y tiene desventaja en pruebas de característica y tiradas de ataque mientras dure; si la supera, sufre la mitad del daño y el conjuro termina. Mientras dure, repite la salvación de Sabiduría al final de cada uno de sus turnos: si falla, sufre de nuevo el daño psíquico; si la supera, el conjuro termina. A niveles superiores: +1d10 por nivel de espacio sobre 4."},
{name:"Private Sanctum", nivel:4, edicion:"ambas", etiquetas:["protección", "utilidad"], escuela:"Abjuración", tiempo:"10 minutos", alcance:"120 ft", componentes:"V, S, M (una lámina fina de plomo, un trozo de vidrio opaco, un puñado de algodón o tela y crisolita en polvo)", duracion:"24 horas", clases:["Mago"], desc:"Asegurás mágicamente un área en alcance: un cubo de entre 5 y 100 ft por lado. Dura mientras dure el hechizo o hasta que lo disipes con una acción. Al lanzarlo elegís una o más de estas propiedades: el sonido no atraviesa la barrera del borde; la barrera se ve oscura y neblinosa e impide ver a través (incluso con visión en la oscuridad); no pueden aparecer ni atravesar el perímetro sensores de hechizos de adivinación; las criaturas del área no pueden ser objetivo de adivinación; nada puede teletransportarse hacia dentro ni fuera; el viaje planar queda bloqueado. Si lo lanzás en el mismo sitio todos los días durante un año, se vuelve permanente. A niveles superiores: el cubo aumenta 100 ft por cada nivel de espacio por encima de 4."},
{name:"Resilient Sphere", nivel:4, edicion:"ambas", etiquetas:["protección", "control"], escuela:"Evocación", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, S, M (una pieza hemisférica de cristal transparente y otra de goma arábiga)", duracion:"Conc., hasta 1 min", clases:["Mago"], desc:"Una esfera de fuerza centelleante encierra a una criatura u objeto Grande o menor en alcance; una criatura no dispuesta hace salvación de Destreza y, si falla, queda encerrada. Nada (objetos, energía ni otros efectos de conjuro) atraviesa la barrera, aunque quien está dentro puede respirar. La esfera es inmune a todo daño y nada dentro puede dañarse desde fuera ni dañar lo de afuera. No pesa; una criatura dentro puede usar una acción para empujar y rodarla a la mitad de su velocidad, y otros pueden levantarla. Disintegrate la destruye sin dañar lo de adentro."},
{name:"Secret Chest", nivel:4, edicion:"ambas", etiquetas:["utilidad"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S, M (un cofre exquisito de 3 x 2 x 2 ft de materiales raros por al menos 5.000 gp y una réplica Diminuta hecha con los mismos materiales por al menos 50 gp)", duracion:"Instantáneo", clases:["Mago"], desc:"Ocultás un cofre y todo su contenido en el Plano Etéreo; debés tocar el cofre y la réplica en miniatura (componentes materiales). Cabe hasta 12 pies cúbicos de material no vivo (3 x 2 x 2 ft). Mientras el cofre esté en el Plano Etéreo, podés usar una acción y tocar la réplica para recuperarlo: aparece en un espacio libre del suelo a 5 ft de vos; con una acción y tocando cofre y réplica, lo enviás de vuelta. Pasados 60 días, hay 5% acumulativo por día de que el efecto termine. También termina si lanzás el hechizo otra vez, si la réplica se destruye o si decidís terminarlo con una acción. Si termina con el cofre en el Plano Etéreo, se pierde irremediablemente.", desc2024:"En 2024 la duración es hasta que se disipe. Recuperás o enviás el cofre al Plano Etéreo con una acción de Magia tocando la réplica (y el cofre para enviarlo). Pasados 60 días, hay 5% acumulativo al final de cada día de que termine; también termina si lanzás el hechizo otra vez o se destruye la réplica. Si termina con el cofre en el Plano Etéreo, este permanece allí para que vos u otro lo encuentre (ya no se pierde)."},
{name:"Vitriolic Sphere", nivel:4, edicion:"2024", etiquetas:["daño", "ácido", "salvación"], escuela:"Evocación", tiempo:"1 Acción", alcance:"150 ft", componentes:"V, S, M (una gota de bilis)", duracion:"Instantáneo", clases:["Hechicero", "Mago"], desc:"Señalás un lugar en alcance y una bola brillante de ácido de 1 ft de diámetro vuela hasta allí y estalla en una esfera de 20 ft de radio. Cada criatura en el área hace salvación de Destreza: si falla sufre 10d4 daño de ácido y otros 5d4 daño de ácido al final de su próximo turno; si salva, solo la mitad del daño inicial. A niveles superiores: el daño inicial sube 2d4 por cada nivel de espacio por encima de 4."},

// ===== NIVEL 5 =====
{name:"Antilife Shell", nivel:5, edicion:"ambas", etiquetas:["buff"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"Personal (10 ft radio)", componentes:"V, S", duracion:"Conc., hasta 1 hora", clases:["Druida"], desc:"Una barrera invisible te rodea (10 ft radio); criaturas vivas (salvo no-muertos y constructos) no pueden pasar a través ni atacar dentro de ella."},
{name:"Awaken", nivel:5, edicion:"ambas", etiquetas:["utilidad"], escuela:"Transmutación", tiempo:"8 horas", alcance:"Toque", componentes:"V, S, M (agatha con valor 1000+ gp, consumido)", duracion:"Instantáneo", clases:["Bardo","Druida"], desc2024:"En 2024 el objetivo debe ser una Bestia o Planta con Inteligencia 3 o menos, o una planta natural que no sea criatura (que se vuelve una criatura Planta y puede mover sus miembros y tiene sentidos similares a los humanos). Gana Inteligencia 10 y habla un idioma que conozcas. Queda Hechizado durante 30 días o hasta que vos o tus aliados le hagan daño; al terminar, elige su actitud hacia vos.", desc:"Le otorgás inteligencia y sensibilidad a una bestia o planta tocada; se vuelve una criatura Mediana pensante, amistosa hacia vos por 30 días."},
{name:"Commune with Nature", nivel:5, edicion:"ambas", etiquetas:["utilidad"], escuela:"Adivinación", tiempo:"1 minuto", alcance:"Personal", componentes:"V, S", duracion:"Instantáneo", clases:["Druida","Ranger"], desc2024:"En 2024 ya no obtenés hechos libres: elegís tres de estas opciones y aprendés lo que corresponde a la zona (3 mi al aire libre, 300 ft bajo tierra; no funciona donde la naturaleza fue reemplazada por construcciones): ubicación de asentamientos; ubicación de portales a otros planos; ubicación de una criatura de CR 10+ (a criterio del DM) que sea celestial, elemental, feérica, infernal o muerto viviente; el tipo más abundante de planta, mineral o bestia (a tu elección); ubicación de cuerpos de agua.", desc:"Te comunicás brevemente con espíritus de la naturaleza, obteniendo conocimiento sobre el terreno circundante en 3 millas (criaturas, poblaciones, terreno, etc.)."},
{name:"Conjure Elemental", nivel:5, edicion:"ambas", etiquetas:["invocación"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"90 ft", componentes:"V, S, M (quemar incienso)", duracion:"Conc., hasta 1 hora", clases:["Druida","Mago"], desc2024:"En 2024 se lanza con una acción (alcance 60 ft, hasta 10 minutos, solo V, S) y cambia por completo: conjurás un espíritu intangible Grande de los Planos Elementales en un espacio libre a tu alcance; elegís su elemento, que define el tipo de daño: aire (relámpago), tierra (trueno), fuego (fuego) o agua (frío). Cuando una criatura que veas entra en su espacio o empieza su turno a 5 ft de él, y el espíritu no tiene a ninguna criatura Apresada, puede obligarla a una salvación de Destreza: si falla, sufre 8d8 daño del tipo del espíritu y queda Apresada hasta que termine el conjuro. Al inicio de cada turno suyo repite la salvación: si falla, sufre 4d8 daño; si salva, deja de estar Apresada. A niveles superiores: el daño aumenta en 1d8 por cada nivel de espacio por encima del 5.º.", desc:"Invocás a un elemental de CR 5 o menor que combate a tu lado durante la duración."},
{name:"Contagion", nivel:5, edicion:"ambas", etiquetas:["control"], escuela:"Necromancia", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S", duracion:"7 días", clases:["Clérigo","Druida"], desc2024:"Tu toque inflige un contagio mágico; salvación de Constitución o el objetivo sufre 11d8 de daño necrótico y queda Envenenado (7 días). Al lanzarlo elegís una característica: mientras esté Envenenado, el objetivo tiene desventaja en las salvaciones con ella. Repite la salvación al final de cada uno de sus turnos hasta acumular tres éxitos (el conjuro termina) o tres fallos (dura 7 días). Si recibe un efecto que terminaría Envenenado, debe superar una salvación de Constitución o la condición no termina. Ya no hay enfermedades a elegir.", desc:"Un golpe cuerpo a cuerpo contagia una enfermedad mágica a la criatura (salvación de Constitución tras 3 fallos, o efectos progresivamente peores)."},
{name:"Geas", nivel:5, edicion:"ambas", etiquetas:["control"], escuela:"Encantamiento", tiempo:"1 minuto", alcance:"60 ft", componentes:"V", duracion:"30 días", clases:["Bardo","Clérigo","Druida","Paladín","Mago"], desc:"Le ordenás a una criatura (salvación de Sabiduría) cumplir un curso de acción; si lo desobedece, sufre 5d10 daño psíquico cada vez que actúa en contra."},
{name:"Greater Restoration", nivel:5, edicion:"ambas", etiquetas:["utilidad"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S, M (diamante en polvo, 100 gp, consumido)", duracion:"Instantáneo", clases:["Bardo","Clérigo","Druida"], desc:"Terminás un efecto en la criatura tocada: reducción de característica, exhausto, maldición, hechizado, petrificado o transformado."},
{name:"Insect Plague", nivel:5, edicion:"ambas", etiquetas:["daño","perforante","control"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"300 ft", componentes:"V, S, M (bola de estiércol)", duracion:"Conc., hasta 10 min", clases:["Clérigo","Druida","Hechicero"], desc2024:"En 2024 la esfera de langostas de 20 ft de radio ya no se esparce por las esquinas y una criatura hace la salvación de Constitución (4d10 daño perforante, mitad si salva) solo una vez por turno; el resto, incluido el escalado de +1d10 por nivel de espacio por encima de 5, queda igual.", desc:"Una esfera de langostas devoradoras de 20 ft de radio; cada criatura ahí hace salvación de Constitución, sufriendo 4d10 daño perforante (mitad si salva)."},
{name:"Mass Cure Wounds", nivel:5, edicion:"ambas", etiquetas:["curación"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S", duracion:"Instantáneo", clases:["Bardo","Clérigo","Druida"], desc2024:"En 2024: la curación sube a 5d8 + tu modificador de característica de lanzamiento (antes 3d8) a hasta seis criaturas en una esfera de 30 ft de radio centrada en un punto que veas; ya no excluye a muertos vivientes ni constructos. A niveles superiores: +1d8 por cada nivel de espacio por encima de 5. Pasa a ser de escuela Abjuración.", desc:"Hasta 6 criaturas en un radio de 30 ft recuperan 3d8 + tu mod. de característica de lanzamiento HP."},
{name:"Planar Binding", nivel:5, edicion:"ambas", etiquetas:["control"], escuela:"Abjuración", tiempo:"1 hora", alcance:"60 ft", componentes:"V, S, M (rubí de 1000+ gp, consumido)", duracion:"24 horas", clases:["Bardo","Clérigo","Druida","Mago"], desc2024:"En 2024: también en la lista del Brujo. Intentás vincular a un Celestial, Elemental, Feérico o Infernal dentro de alcance durante todo el lanzamiento (1 hora, joya de 1.000+ gp que se consume): salvación de Carisma o queda obligado a servirte 24 horas, siguiendo tus órdenes lo mejor posible. A niveles superiores la duración es 10 días (nivel 6), 30 días (7), 180 días (8) y 366 días (9).", desc:"Una criatura extraplanar a tu alcance hace salvación de Carisma o queda vinculada a servirte durante la duración."},
{name:"Reincarnate", nivel:5, edicion:"ambas", etiquetas:["utilidad"], escuela:"Transmutación", tiempo:"1 hora", alcance:"Toque", componentes:"V, S, M (aceites raros y ungüentos, 1000+ gp, consumido)", duracion:"Instantáneo", clases:["Druida"], desc2024:"En 2024 el material son óleos raros por valor de 1.000+ po (consumidos) y es de Necromancia. Tocás a un humanoide muerto (o una parte de él) que no lleve muerto más de 10 días: el conjuro forma un nuevo cuerpo y llama al alma a entrar. Tirás 1d10 para la especie (o el DM elige otra jugable): 1 tirar de nuevo, 2 Dragonborn, 3 Dwarf, 4 Elf, 5 Gnome, 6 Goliath, 7 Halfling, 8 Human, 9 Orc, 10 Tiefling. La criatura toma las decisiones que ofrezca esa especie, recuerda su vida anterior y conserva sus capacidades, salvo que pierde los rasgos de su especie previa y gana los de la nueva.", desc:"Un humanoide muerto (menos de 10 días) recobra la vida en un nuevo cuerpo, de una raza aleatoria distinta."},
{name:"Scrying", nivel:5, edicion:"ambas", etiquetas:["utilidad"], escuela:"Adivinación", tiempo:"10 minutos", alcance:"Personal", componentes:"V, S, M (espejo de plata, 1000+ gp)", duracion:"Conc., hasta 10 min", clases:["Bardo","Clérigo","Druida","Brujo","Mago"], desc:"Ves y oís a un objetivo específico (salvación de Sabiduría si es hostil) en cualquier lugar del mismo plano, invocando un sensor invisible cerca suyo."},
{name:"Tree Stride", nivel:5, edicion:"ambas", etiquetas:["utilidad","teletransporte"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"Personal", componentes:"V, S", duracion:"Conc., hasta 1 min", clases:["Druida","Ranger"], desc:"Podés entrar a un árbol y salir instantáneamente de otro árbol del mismo tipo a 500 ft, hasta una vez por turno mientras dure el conjuro."},
{name:"Wall of Stone", nivel:5, edicion:"ambas", etiquetas:["control"], escuela:"Evocación", tiempo:"1 Acción", alcance:"120 ft", componentes:"V, S, M (piedrita)", duracion:"Conc., hasta 10 min", clases:["Druida","Hechicero","Mago"], desc2024:"Creás un muro de piedra no mágica de diez paneles de 10x10 ft y 6 pulgadas de grosor (o paneles de 10x20 ft de 3 pulgadas). Cada panel tiene CA 15 y 30 PG por pulgada de grosor, e inmunidad al daño de veneno y psíquico (novedad 2024). Si mantenés la concentración toda la duración (hasta 10 min), el muro se vuelve permanente. Una criatura rodeada puede salvar de Destreza y mover su velocidad con su reacción.", desc:"Creás un muro de piedra no mágica de hasta diez paneles de 10x10 ft cada uno, que puede tomar la forma deseada."},
{name:"Animate Objects", nivel:5, edicion:"ambas", etiquetas:["invocación", "daño", "contundente", "control"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"120 ft", componentes:"V, S", duracion:"Conc., hasta 1 min", clases:["Bardo", "Hechicero", "Mago"], desc:"Animás hasta diez objetos no mágicos a tu alcance que no estén siendo llevados (Mediano cuenta como 2 objetos, Grande como 4, Enorme como 8; no podés animar más grandes que Enorme). Cada uno se vuelve una criatura Constructo bajo tu control hasta que el conjuro termine o llegue a 0 PG; vuelve a su forma de objeto con el daño sobrante. Como acción adicional les ordenás mentalmente (a una o a todas a la vez, si están a 500 ft de vos); si no das órdenes, solo se defienden. Hacen un ataque cuerpo a cuerpo a 5 ft (daño contundente). Diminuto: 20 PG, CA 18, +8, 1d4+4. Pequeño: 25 PG, CA 16, +6, 1d8+2. Mediano: 40 PG, CA 13, +5, 2d6+1. Grande: 50 PG, CA 10, +6, 2d10+2. Enorme: 80 PG, CA 10, +8, 2d12+4. Velocidad 30 ft (o vuelo 30 ft si no tiene miembros; 0 si está fijo), visión ciega 30 ft. A niveles superiores: animás dos objetos adicionales por cada nivel de espacio por encima del 5.º.", desc2024:"En 2024 animás una cantidad de objetos no mágicos, no fijados a una superficie y no Gargantuescos, igual a tu modificador de característica de lanzamiento (Mediano o menor cuenta 1, Grande 2, Enorme 3). Cada uno es un Constructo con el perfil Animated Object (CA 15; 10/20/40 PG según sea Mediano o menor/Grande/Enorme; velocidad 30 ft; inmune a veneno, psíquico y varias condiciones); es tu aliado, comparte tu iniciativa y actúa justo después de vos. Como acción adicional les ordenás (a 500 ft); sin órdenes usan Esquivar y solo se mueven para evitar daño. Slam: tirada de ataque de conjuro, alcance 5 ft, daño de fuerza 1d4+3 (Mediano o menor), 2d6+3+mod. (Grande) o 2d12+3+mod. (Enorme). A niveles superiores: el daño del Slam aumenta 1d4/1d6/1d12 por cada nivel de espacio por encima del 5.º."},
{name:"Arcane Hand", nivel:5, edicion:"ambas", etiquetas:["invocación", "daño", "fuerza", "control", "protección"], escuela:"Evocación", tiempo:"1 Acción", alcance:"120 ft", componentes:"V, S, M (una cáscara de huevo y un guante de piel de serpiente)", duracion:"Conc., hasta 1 min", clases:["Mago"], desc:"Creás una mano Grande de fuerza translúcida a 120 ft que imita tu mano. Es un objeto con CA 20, PG iguales a tu máximo, Fuerza 26 (+8) y Destreza 10 (+0); si llega a 0 PG, el conjuro termina. Al lanzarlo y como acción adicional en turnos posteriores, la movés hasta 60 ft y elegís: Puño cerrado (ataque de conjuro cuerpo a cuerpo, 4d8 de daño de fuerza); Mano violenta (prueba de Fuerza de la mano contra Fuerza (Atletismo) del objetivo, ventaja si es Mediano o menor; lo empuja 5 ft + 5 × tu modificador); Mano aferrante (agarra a una criatura Enorme o menor, ventaja si es Mediana o menor; con acción adicional la aplasta: 2d6 + tu modificador de contundente); Mano interpuesta (te da media cobertura contra la criatura elegida y no puede atravesarla si su Fuerza es menor o igual a 26; si es mayor, el espacio es terreno difícil). A niveles superiores: Puño +2d8 y Mano aferrante +2d6 por nivel por encima de 5.", desc2024:"En 2024: también en la lista del Hechicero. Misma mano (CA 20, PG iguales a tu máximo, 60 ft por acción adicional). Puño cerrado: 5d8 de daño de fuerza. Mano violenta: salvación de Fuerza de una criatura Enorme o menor o la empuja 5 ft + 5 × tu modificador. Mano aferrante: salvación de Destreza o queda Agarrada (CD de escape = tu CD); aplastar con acción adicional: 4d6 + tu modificador de contundente. Mano interpuesta: media cobertura contra ataques que pasen por su espacio y su espacio es terreno difícil para tus enemigos. A niveles superiores: Puño +2d8, Mano aferrante +2d6 por nivel por encima de 5."},
{name:"Cloudkill", nivel:5, edicion:"ambas", etiquetas:["daño", "veneno", "salvación", "control"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"120 ft", componentes:"V, S", duracion:"Conc., hasta 10 min", clases:["Hechicero", "Mago"], desc:"Creás una esfera de 20 ft de radio de niebla venenosa amarillo verdosa centrada en un punto a alcance, que se esparce por las esquinas y dura hasta que un viento fuerte la disperse (termina el conjuro). Su área está muy oscurecida. Una criatura que entra por primera vez en un turno al área o empieza su turno ahí hace salvación de Constitución: sufre 5d8 daño de veneno si falla, o la mitad si salva (aunque contenga el aliento o no respire). La niebla se mueve 10 ft alejándose de vos al inicio de cada uno de tus turnos, rodando por el suelo y hundiéndose en el nivel más bajo, incluso por aberturas. A niveles superiores: +1d8 de daño por cada nivel de espacio por encima de 5.", desc2024:"En 2024 la esfera de niebla de 20 ft de radio ya no se esparce por las esquinas ni se hunde por aberturas. Cada criatura en ella hace salvación de Constitución, con 5d8 daño de veneno si falla o la mitad si salva; también la hace cuando la esfera se mueve a su espacio, cuando entra o cuando termina su turno ahí, pero solo una vez por turno. Se mueve 10 ft alejándose de vos al inicio de cada uno de tus turnos. A niveles superiores: +1d8 por cada nivel de espacio por encima de 5."},
{name:"Commune", nivel:5, edicion:"ambas", etiquetas:["adivinación", "utilidad"], escuela:"Adivinación", tiempo:"1 minuto (ritual)", alcance:"Personal", componentes:"V, S, M (incienso y un vial de agua bendita o profana)", duracion:"1 minuto", clases:["Clérigo"], desc:"Contactás a tu deidad o a un intermediario divino y hacés hasta tres preguntas que se respondan con sí o no, antes de que termine el conjuro; recibís una respuesta correcta a cada una. Los seres divinos no son omniscientes: puede responder \"poco claro\", o el DM puede dar una frase corta si una palabra sería engañosa. Si lo lanzás dos o más veces antes de tu próximo descanso largo, hay 25% acumulativo por cada lanzamiento posterior al primero de no recibir respuesta (tirada secreta del DM)."},
{name:"Cone of Cold", nivel:5, edicion:"ambas", etiquetas:["daño", "frío", "salvación"], escuela:"Evocación", tiempo:"1 Acción", alcance:"Personal (cono de 60 ft)", componentes:"V, S, M (un pequeño cono de cristal o vidrio)", duracion:"Instantáneo", clases:["Hechicero", "Mago"], desc:"Una ráfaga de aire helado sale de tus manos. Cada criatura en un cono de 60 ft hace una salvación de Constitución: sufre 8d8 daño de frío si falla, la mitad si supera. Una criatura que muera por este conjuro se convierte en una estatua congelada hasta que se descongele. A niveles superiores: +1d8 por nivel de espacio sobre 5."},
{name:"Contact Other Plane", nivel:5, edicion:"ambas", etiquetas:["adivinación", "psíquico", "daño", "salvación"], escuela:"Adivinación", tiempo:"1 minuto (ritual)", alcance:"Personal", componentes:"V", duracion:"1 minuto", clases:["Brujo", "Mago"], desc:"Contactás mentalmente a un semidiós, al espíritu de un sabio muerto hace tiempo u otra entidad misteriosa de otro plano; hacerlo puede dañar tu mente. Al lanzarlo hacés una salvación de Inteligencia CD 15. Si fallás, sufrís 6d6 daño psíquico y quedás loco hasta que termines un descanso largo: no podés actuar, entender a otros, leer y solo balbuceás; Greater Restoration lanzado sobre vos termina el efecto. Si salvás, podés hacerle a la entidad hasta cinco preguntas antes de que termine el hechizo. El DM responde cada una con una palabra («sí», «no», «quizás», «nunca», «irrelevante», «poco claro») o, si sería engañoso, con una frase corta.", desc2024:"En 2024, si fallás la salvación de Inteligencia CD 15 sufrís 6d6 daño psíquico y quedás Incapacitado hasta terminar un descanso largo (Greater Restoration termina el efecto), en vez de quedar loco. Si salvás, podés hacerle a la entidad hasta cinco preguntas antes de que termine el hechizo; el DM responde con una palabra («sí», «no», «quizás», «nunca», «irrelevante», «poco claro») o una frase corta si la palabra sería engañosa."},
{name:"Creation", nivel:5, edicion:"ambas", etiquetas:["invocación", "utilidad"], escuela:"Ilusión", tiempo:"1 minuto", alcance:"30 ft", componentes:"V, S, M (un trocito de materia del mismo tipo que el objeto que planeás crear)", duracion:"Especial", clases:["Hechicero", "Mago"], desc:"Extraés hilos de sombra del Páramo de las Sombras (Shadowfell) para crear un objeto no vivo de materia vegetal (telas, cuerda, madera o similar) o mineral (piedra, cristal, metal) a tu alcance. No puede ser mayor que un cubo de 5 ft y debe tener una forma y material que hayas visto antes. La duración depende del material (si hay varios, la más corta): materia vegetal 1 día; piedra o cristal 12 horas; metales preciosos 1 hora; gemas 10 minutos; adamantina o mithral 1 minuto. Usar un material creado así como componente de otro hechizo hace que ese hechizo falle. A niveles superiores: el cubo crece 5 ft por cada nivel de espacio por encima de 5."},
{name:"Dispel Evil and Good", nivel:5, edicion:"ambas", etiquetas:["protección", "control", "salvación"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"Personal", componentes:"V, S, M (agua bendita o polvo de plata y hierro)", duracion:"Conc., hasta 1 min", clases:["Clérigo", "Paladín"], desc:"Energía reluciente te rodea y protege de feéricos, muertos vivientes y criaturas de más allá del Plano Material: mientras dure, celestiales, elementales, feéricos, infernales y muertos vivientes tienen desventaja en las tiradas de ataque contra vos. Podés terminar el conjuro antes con una de dos funciones. Romper encantamiento: con una acción tocás a una criatura hechizada, asustada o poseída por esos tipos, y deja de estarlo. Despedir: con una acción hacés un ataque de conjuro cuerpo a cuerpo contra uno de esos tipos a tu alcance; si impacta, hace salvación de Carisma o es enviada a su plano de origen (si no está ya allí; los muertos vivientes van al Shadowfell y los feéricos al Feywild).", desc2024:"En 2024 el material es polvo de plata y hierro (sin agua bendita) y las dos funciones usan la acción Magia. Romper encantamiento: tocás a una criatura poseída, o Hechizada o Asustada por criaturas de esos tipos, y deja de estarlo. Despedir: ya no hay tirada de ataque; elegís a una criatura de esos tipos que veas a 5 ft o menos de vos, que hace salvación de Carisma o es enviada a su plano de origen (los muertos vivientes al Shadowfell y los feéricos al Feywild)."},
{name:"Dominate Person", nivel:5, edicion:"ambas", etiquetas:["control", "salvación"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S", duracion:"Conc., hasta 1 min", clases:["Bardo", "Hechicero", "Mago"], desc:"Un humanoide que veas a 60 ft hace salvación de Sabiduría o queda Hechizado por vos (ventaja en la salvación si vos o tus aliados lo están combatiendo). Tenés un vínculo telepático con él mientras estén en el mismo plano; le das órdenes simples y generales sin gastar acción y las cumple lo mejor posible (si termina y no recibe más órdenes, se defiende). Con tu acción tomás control total y preciso hasta el final de tu próximo turno, incluso una reacción si gastás la tuya. Cada vez que recibe daño repite la salvación; si la supera, termina el conjuro. A niveles superiores: concentración hasta 10 min (nivel 6), 1 hora (7) u 8 horas (8+).", desc2024:"En 2024: un humanoide que veas a 60 ft hace salvación de Sabiduría o queda Hechizado (ventaja si vos o tus aliados lo combaten); cada vez que recibe daño repite la salvación y termina el conjuro si la supera. Vínculo telepático: en tu turno das órdenes sin gastar acción y obedece lo mejor que pueda en su turno; si completa la orden sin más indicaciones, actúa y se mueve como quiere, priorizando protegerse. Podés ordenarle usar una reacción gastando la tuya. Ya no existe el control total con tu acción. A niveles superiores: hasta 10 min (nivel 6), 1 hora (7) u 8 horas (8+)."},
{name:"Dream", nivel:5, edicion:"ambas", etiquetas:["control", "ilusión", "daño", "psíquico", "salvación"], escuela:"Ilusión", tiempo:"1 minuto", alcance:"Especial", componentes:"V, S, M (un puñado de arena, una gota de tinta y una pluma de escribir arrancada a un pájaro dormido)", duracion:"8 horas", clases:["Bardo", "Brujo", "Mago"], desc:"Moldeás los sueños de una criatura conocida que esté en tu mismo plano (las que no duermen, como los elfos, no pueden ser contactadas). Vos o una criatura voluntaria que toques entra en trance como mensajero: percibe su entorno pero no puede actuar ni moverse. Si el objetivo duerme, el mensajero aparece en sus sueños, conversa con él mientras siga dormido y moldea el entorno del sueño; puede salir del trance cuando quiera, y el objetivo recuerda el sueño. Si está despierto, el mensajero lo sabe y puede terminar el hechizo o esperar a que duerma. Si lo hacés monstruoso, entrega un mensaje de hasta diez palabras y el objetivo hace salvación de Sabiduría: si falla, una pesadilla le impide beneficiarse del descanso y al despertar sufre 3d6 daño psíquico. Con una parte de su cuerpo (mechón, uña…), salva con desventaja.", desc2024:"En 2024: el mensajero en trance queda Incapacitado y con velocidad 0; el material es solo un puñado de arena. Si lo hacés terrorífico, tras el mensaje de hasta diez palabras el objetivo hace salvación de Sabiduría: si falla no obtiene beneficio del descanso y al despertar sufre 3d6 daño psíquico. Ya no hay desventaja en la salvación por poseer una parte de su cuerpo."},
{name:"Flame Strike", nivel:5, edicion:"ambas", etiquetas:["daño", "fuego", "radiante", "salvación"], escuela:"Evocación", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S, M (una pizca de azufre)", duracion:"Instantáneo", clases:["Clérigo"], desc:"Una columna vertical de fuego divino cae rugiendo desde los cielos en un lugar que indiques. Cada criatura en un cilindro de 10 ft de radio y 40 ft de alto centrado en un punto a tu alcance hace una salvación de Destreza: sufre 4d6 daño de fuego y 4d6 radiante si falla, la mitad si supera. A niveles superiores: +1d6 al daño de fuego o al radiante (a tu elección) por nivel de espacio sobre 5.", desc2024:"Cada criatura en el cilindro de 10 ft de radio y 40 ft de alto hace una salvación de Destreza: sufre 5d6 daño de fuego y 5d6 radiante si falla, la mitad si supera. A niveles superiores: +1d6 a ambos daños (fuego y radiante) por nivel de espacio sobre 5."},
{name:"Hallow", nivel:5, edicion:"ambas", etiquetas:["protección", "control", "utilidad"], escuela:"Evocación", tiempo:"24 horas", alcance:"Toque", componentes:"V, S, M (hierbas, aceites e incienso por valor de al menos 1.000 gp, que el conjuro consume)", duracion:"Hasta que se disipe", clases:["Clérigo"], desc:"Tocás un punto e infundís el área alrededor (radio hasta 60 ft; falla si incluye un área ya bajo Hallow) con poder sagrado o profano. Celestiales, elementales, feéricos, infernales y no-muertos no pueden entrar ni hechizar, asustar o poseer a criaturas allí (las ya afectadas se liberan al entrar); podés excluir tipos. Además ligás un efecto extra: Coraje (no pueden ser Asustadas), Oscuridad, Luz diurna (la luz brillante no se apaga con oscuridad mágica de nivel menor), Protección de energía o Vulnerabilidad a energía (un tipo de daño a elección, salvo contundente/perforante/cortante), Descanso eterno (los cadáveres no se vuelven no-muertos), Interferencia extradimensional (sin teletransporte ni viaje extradimensional o interplanar), Miedo (Asustadas), Silencio o Lenguas (todas se comunican). Podés elegir a quién afecta; una criatura afectada puede hacer salvación de Carisma al entrar o empezar su turno por primera vez en un turno y, si la supera, ignora el efecto extra hasta que salga.", desc2024:"En 2024: es de escuela Abjuración y no requiere hierbas ni aceites, solo incienso de 1.000+ gp que se consume. Mismo área (radio hasta 60 ft). Custodia sagrada: elegís entre Aberración, Celestial, Elemental, Feérico, Infernal o No-muerto; esas criaturas no pueden entrar voluntariamente y se liberan de posesión, Hechizado o Asustado causados por ellas. Efecto extra: Coraje, Oscuridad, Luz diurna, Descanso pacífico, Interferencia extradimensional (sin teletransporte ni viaje interplanar, tipos a elección), Miedo, Resistencia o Vulnerabilidad (un tipo de daño, para tipos de criatura a elección), Silencio o Lenguas. Ya no hay salvación de Carisma para ignorar el efecto."},
{name:"Hold Monster", nivel:5, edicion:"ambas", etiquetas:["control", "salvación"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"90 ft", componentes:"V, S, M (un trocito de hierro)", duracion:"Conc., hasta 1 min", clases:["Bardo", "Hechicero", "Brujo", "Mago"], desc:"Elegís una criatura que veas a tu alcance; debe superar una salvación de Sabiduría o queda Paralizada mientras dure el hechizo. No tiene efecto contra no-muertos. Al final de cada uno de sus turnos, el objetivo puede repetir la salvación de Sabiduría; si la supera, el hechizo termina para él. A niveles superiores: una criatura adicional por cada nivel de espacio por encima de 5; las criaturas deben estar a 30 ft o menos entre sí.", desc2024:"En 2024: elegís una criatura que veas a tu alcance (90 ft); debe superar una salvación de Sabiduría o queda Paralizada mientras dure el hechizo. Ya no excluye a los no-muertos. Al final de cada uno de sus turnos repite la salvación y, si la supera, el hechizo termina en ella. A niveles superiores: una criatura adicional por cada nivel de espacio por encima de 5 (sin el límite de 30 ft entre objetivos)."},
{name:"Legend Lore", nivel:5, edicion:"ambas", etiquetas:["adivinación", "utilidad"], escuela:"Adivinación", tiempo:"10 minutos", alcance:"Personal", componentes:"V, S, M (incienso por 250 po, que se consume, y cuatro tiras de marfil de 50 po cada una)", duracion:"Instantáneo", clases:["Bardo", "Clérigo", "Mago"], desc:"Nombrás o describís una persona, lugar u objeto; el conjuro te trae un breve resumen de la tradición significativa sobre eso: relatos actuales, historias olvidadas o saberes secretos. Si lo nombrado no tiene importancia legendaria, no obtenés información. Cuanta más información tengas ya, más precisa y detallada es la que recibís. Es exacta pero puede estar en lenguaje figurado.", desc2024:"En 2024: debe ser una persona, lugar u objeto famoso. Recibís un breve resumen de su tradición (detalles importantes, revelaciones curiosas o saberes secretos), exacto pero posiblemente en lenguaje figurado o poesía según el DM; cuanta más información tengas, más precisa. Si lo elegido no es realmente famoso, el conjuro falla."},
{name:"Mislead", nivel:5, edicion:"ambas", etiquetas:["ilusión", "utilidad"], escuela:"Ilusión", tiempo:"1 Acción", alcance:"Personal", componentes:"S", duracion:"Conc., hasta 1 hora", clases:["Bardo", "Mago"], desc:"Te volvés Invisible al mismo tiempo que aparece un doble ilusorio tuyo donde estás parado. El doble dura mientras dure el conjuro, pero la invisibilidad termina si atacás o lanzás un conjuro. Con tu acción movés el doble hasta el doble de tu velocidad y hacés que gesticule, hable y se comporte como quieras. Podés ver y oír a través de él; como acción adicional en tu turno, alternás entre sus sentidos y los tuyos, y mientras usás los suyos estás Cegado y Ensordecido respecto de tu entorno.", desc2024:"Te volvés Invisible mientras aparece el doble ilusorio, pero la invisibilidad termina de inmediato después de que hagas una tirada de ataque, infligas daño o lances un conjuro. Con la acción de Magia movés el doble hasta el doble de tu velocidad y lo hacés gesticular, hablar y comportarse como quieras; es intangible e invulnerable. Podés ver y oír a través de él como si estuvieras donde está. En 2024 también es conjuro de Brujo."},
{name:"Modify Memory", nivel:5, edicion:"ambas", etiquetas:["control", "salvación"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, S", duracion:"Conc., hasta 1 min", clases:["Bardo", "Mago"], desc:"Intentás remodelar los recuerdos de una criatura que veas: hace una tirada de salvación de Sabiduría (con ventaja si estás peleando contra ella). Si falla, queda Hechizada durante la duración, Incapacitada y ajena a su entorno, aunque te oye; si recibe daño o es objetivo de otro conjuro, el conjuro termina y no se modifica ningún recuerdo. Mientras dure, podés afectar el recuerdo de un evento de las últimas 24 horas que durara no más de 10 minutos: eliminarlo para siempre, hacerlo recordar con total claridad, cambiar sus detalles o crear el recuerdo de otro evento. Debés hablarle para describir los cambios y debe entender tu idioma; si el conjuro termina antes de que termines de describirlos, no se altera nada. Un recuerdo ilógico se descarta como un mal sueño. Remove Curse o Greater Restoration restauran el recuerdo verdadero. A niveles superiores: podés alterar recuerdos de hasta 7 días atrás (nivel 6), 30 días (nivel 7), 1 año (nivel 8) o cualquier momento del pasado (nivel 9)."},
{name:"Passwall", nivel:5, edicion:"ambas", etiquetas:["utilidad"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, S, M (una pizca de semillas de sésamo)", duracion:"1 hora", clases:["Mago"], desc:"Aparece un pasaje en un punto que veas de una superficie de madera, yeso o piedra (pared, techo o suelo) en alcance, y dura mientras dure el hechizo. Elegís sus dimensiones: hasta 5 ft de ancho, 8 ft de alto y 20 ft de profundidad. No genera inestabilidad en la estructura que lo rodea. Cuando la abertura desaparece, las criaturas u objetos que sigan dentro son expulsados sin daño al espacio libre más cercano a la superficie donde lo lanzaste."},
{name:"Raise Dead", nivel:5, edicion:"ambas", etiquetas:["curación", "utilidad"], escuela:"Necromancia", tiempo:"1 hora", alcance:"Toque", componentes:"V, S, M (un diamante de al menos 500 gp, que el hechizo consume)", duracion:"Instantáneo", clases:["Bardo", "Clérigo", "Paladín"], desc:"Devolvés a la vida a una criatura muerta que tocás, siempre que haya muerto hace no más de 10 días. Si su alma es libre y está dispuesta a volver al cuerpo, revive con 1 PG. Neutraliza los venenos y cura las enfermedades no mágicas que la afectaban al morir, pero no quita enfermedades mágicas, maldiciones ni efectos similares (si no se eliminaron antes, se activan al revivir). No puede revivir a un no-muerto. Cierra todas las heridas mortales pero no restaura partes del cuerpo faltantes; si falta una parte u órgano indispensable (p. ej. la cabeza), el hechizo falla automáticamente. Volver de la muerte es duro: el objetivo sufre -4 a todas las tiradas de ataque, de salvación y pruebas de característica; cada descanso largo que termine reduce la penalización en 1 hasta que desaparece.", desc2024:"En 2024: con un toque revivís a una criatura muerta hace no más de 10 días que no fuera No-muerta al morir; vuelve con 1 PG. Neutraliza los venenos que la afectaban (ya no cura enfermedades no mágicas). Cierra heridas mortales pero no restaura partes faltantes; si falta una parte u órgano vital, falla automáticamente. El objetivo sufre -4 a las pruebas de d20; cada descanso largo reduce la penalización en 1 hasta llegar a 0."},
{name:"Seeming", nivel:5, edicion:"ambas", etiquetas:["ilusión", "utilidad", "salvación"], escuela:"Ilusión", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, S", duracion:"8 horas", clases:["Bardo", "Hechicero", "Mago"], desc:"Cambiás la apariencia de cualquier cantidad de criaturas que veas en alcance, dándole a cada una un aspecto ilusorio nuevo. Un objetivo que no quiera puede hacer salvación de Carisma y, si la supera, no es afectado. Disfraza el aspecto físico, la ropa, armaduras, armas y equipo; podés hacer a cada criatura 1 ft más alta o más baja y delgada, gorda o intermedia, pero la forma debe tener la misma disposición básica de miembros. Dura todo el tiempo, salvo que la despidas con una acción. No resiste una inspección física (los objetos atraviesan un sombrero añadido, una mano choca con el cuerpo real). Una criatura puede usar su acción para inspeccionar al objetivo y hacer una prueba de Inteligencia (Investigación) contra tu CD de conjuros; si la supera, nota el disfraz."},
{name:"Summon Dragon", nivel:5, edicion:"2024", etiquetas:["invocación", "daño", "salvación"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S, M (un objeto con la imagen de un dragón grabada que valga 500+ po)", duracion:"Conc., hasta 1 hora", clases:["Mago"], desc:"Invocás un espíritu de dragón en un espacio desocupado que veas a tu alcance, con el perfil Draconic Spirit; desaparece al llegar a 0 PG o al terminar el conjuro. Es aliado tuyo y de tus aliados, comparte tu iniciativa pero actúa justo después de vos; obedece tus órdenes verbales (sin acción) y, si no das ninguna, usa Esquivar y se mueve para evitar peligro. Usá el nivel del espacio como nivel del conjuro en el perfil. Draconic Spirit: Grande, Neutral; CA 14 + nivel; PG 50 + 10 por nivel sobre 5; Vel 30 ft, vuelo 60 ft, nado 30 ft; FUE 19, DES 14, CON 17, INT 10, SAB 14, CAR 14; resistencias: ácido, frío, fuego, relámpago, veneno; inmune a Hechizado, Asustado, Envenenado; visión ciega 30 ft, visión en la oscuridad 60 ft. Resistencias compartidas: al invocarlo elegís una de sus resistencias y la tenés vos hasta que termine el conjuro. Multiataque: tantos ataques Rend como la mitad del nivel del conjuro (redondeando hacia abajo) y usa Aliento. Rend: ataque cuerpo a cuerpo, bonificador = tu ataque de conjuro, alcance 10 ft, 1d6 + 4 + nivel del conjuro de daño perforante. Aliento: salvación de Destreza (tu CD), cono de 30 ft, 2d6 de un tipo al que tenga resistencia (a tu elección al lanzar), mitad si supera."},
{name:"Telekinesis", nivel:5, edicion:"ambas", etiquetas:["control", "utilidad"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S", duracion:"Conc., hasta 10 min", clases:["Hechicero", "Mago"], desc:"Mové o manipulá criaturas u objetos con la mente. Al lanzarlo, y con tu acción cada asalto, ejercés tu voluntad sobre una criatura u objeto que veas a tu alcance; podés mantener el mismo objetivo o cambiar (el anterior deja de ser afectado). Criatura: podés intentar mover una criatura Enorme o menor; hacés una prueba de característica de lanzamiento enfrentada a la prueba de Fuerza de la criatura; si ganás, la movés hasta 30 ft en cualquier dirección (incluso hacia arriba, sin salir del alcance) y queda Apresada en tu agarre telequinético hasta el final de tu siguiente turno (suspendida en el aire si la elevaste); en asaltos siguientes repetís la prueba con tu acción para mantenerla. Objeto: hasta 1.000 libras; si nadie lo lleva puesto o en mano, lo movés automáticamente hasta 30 ft; si una criatura lo lleva, prueba enfrentada contra su Fuerza para arrebatárselo. Podés manipular con precisión (herramienta simple, abrir puertas o contenedores, guardar o sacar objetos, verter un frasco).", desc2024:"En 2024 ya no hay prueba enfrentada: la criatura Enorme o menor debe superar una tirada de salvación de Fuerza o la movés hasta 30 ft dentro del alcance; queda Apresada hasta el final de tu siguiente turno y, si la elevaste, queda suspendida y cae al final de ese turno salvo que vuelvas a usar la opción y falle la salvación. Los asaltos posteriores requieren una acción de Magia. Objeto: puede ser Enorme o menor (ya no el límite de 1.000 libras); si nadie lo lleva, lo movés automáticamente hasta 30 ft; si una criatura lo lleva puesto o en mano, debe superar una salvación de Fuerza o se lo arrebatás y lo movés hasta 30 ft."},
{name:"Telepathic Bond", nivel:5, edicion:"ambas", etiquetas:["utilidad", "buff"], escuela:"Adivinación", tiempo:"1 Acción (ritual)", alcance:"30 ft", componentes:"V, S, M (cáscaras de huevo de dos tipos distintos de criaturas)", duracion:"1 hora", clases:["Mago"], desc:"Creás un vínculo telepático entre hasta ocho criaturas voluntarias de tu elección en alcance, conectando a cada una con todas las demás mientras dure. Las criaturas con Inteligencia 2 o menos no se ven afectadas. Los objetivos pueden comunicarse telepáticamente a través del vínculo, compartan o no un idioma, a cualquier distancia, pero no entre planos de existencia.", desc2024:"En 2024 también lo lanzan los Bardos y no se ven afectadas las criaturas que no puedan comunicarse en ningún idioma (en vez de Inteligencia 2 o menos). Vinculás a hasta ocho criaturas voluntarias en alcance; pueden comunicarse telepáticamente, compartan o no un idioma, a cualquier distancia pero no entre planos."},
{name:"Teleportation Circle", nivel:5, edicion:"ambas", etiquetas:["teletransporte", "utilidad"], escuela:"Conjuración", tiempo:"1 minuto", alcance:"10 ft", componentes:"V, M (tizas y tintas raras infundidas con gemas preciosas por 50 gp, que el conjuro consume)", duracion:"1 turno", clases:["Bardo", "Hechicero", "Mago"], desc:"Dibujás en el suelo un círculo de 10 ft de diámetro con sigilos que lo enlazan con un círculo de teletransporte permanente de tu elección cuya secuencia de sigilos conozcas y que esté en tu mismo plano. Se abre un portal reluciente que dura hasta el final de tu próximo turno; quien lo cruce aparece a 5 ft del círculo de destino (o en el espacio libre más cercano). Al ganar el conjuro conocés las secuencias de dos destinos del Plano Material (las elige el DJ); podés aprender más y memorizar una nueva tras estudiarla 1 minuto. Lanzarlo en el mismo lugar cada día durante un año crea un círculo permanente (sin necesidad de teletransportarte)."},
{name:"Wall of Force", nivel:5, edicion:"ambas", etiquetas:["protección", "control"], escuela:"Evocación", tiempo:"1 Acción", alcance:"120 ft", componentes:"V, S, M (una pizca de polvo de una gema transparente triturada)", duracion:"Conc., hasta 10 min", clases:["Mago"], desc:"Un muro invisible de fuerza surge en un punto a alcance, con la orientación que elijas (horizontal, vertical o en ángulo), flotando libre o apoyado en una superficie sólida. Podés darle forma de cúpula hemisférica o esfera de hasta 10 ft de radio, o de superficie plana de hasta diez paneles contiguos de 10 ft x 10 ft. Mide 1/4 de pulgada de grosor. Si corta el espacio de una criatura al aparecer, ésta es empujada a un lado a tu elección. Nada puede atravesarlo; es inmune a todo daño y a disipar magia, pero Disintegrate lo destruye al instante. También se extiende al Plano Etéreo y bloquea el viaje etéreo."},

// ===== NIVEL 6 =====
{name:"Conjure Fey", nivel:6, edicion:"ambas", etiquetas:["invocación"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"90 ft", componentes:"V, S", duracion:"Conc., hasta 1 hora", clases:["Druida","Brujo"], desc2024:"En 2024 se lanza con una acción, alcance 60 ft, dura hasta 10 min con concentración y solo lo lanzan los Druidas. Conjurás un espíritu Mediano del Feywild con aspecto de criatura feérica en un espacio libre que veas. Al aparecer podés hacer un ataque de conjuro cuerpo a cuerpo contra una criatura a 5 ft de él: si impacta, sufre daño psíquico igual a 3d12 + tu modificador de característica de lanzamiento y queda Asustada hasta el inicio de tu siguiente turno (vos y el espíritu sois la fuente del miedo). Como acción adicional en turnos posteriores podés teletransportarlo a un espacio libre que veas a 30 ft del que dejó y repetir el ataque. A niveles superiores: +1d12 de daño por cada nivel de espacio por encima de 6.", desc:"Invocás a una criatura feérica de CR 6 o menor (o dos de CR 3 o menor) que combate a tu lado durante la duración."},
{name:"Find the Path", nivel:6, edicion:"ambas", etiquetas:["utilidad"], escuela:"Adivinación", tiempo:"1 minuto", alcance:"Personal", componentes:"V, S, M (set de adivinación, 100+ gp)", duracion:"Conc., hasta 1 día", clases:["Bardo","Clérigo","Druida"], desc:"Descubrís la ruta más directa hacia un destino específico que conozcas o hayas visitado, mientras dure el conjuro."},
{name:"Heal", nivel:6, edicion:"ambas", etiquetas:["curación"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S", duracion:"Instantáneo", clases:["Clérigo","Druida"], desc2024:"Elegís una criatura que veas a 60 ft: recupera 70 PG y se terminan sus condiciones de Cegado, Ensordecido y Envenenado (en 2024 ya no cura enfermedades, y ya no excluye a constructos y muertos vivientes; ahora es de Abjuración). A niveles superiores: +10 PG de curación por nivel sobre el 6º.", desc:"La criatura objetivo recupera 70 HP y se cura de ceguera y sordera (no de enfermedades mágicas ni maldiciones)."},
{name:"Heroes' Feast", nivel:6, edicion:"ambas", etiquetas:["buff"], escuela:"Conjuración", tiempo:"10 minutos", alcance:"30 ft", componentes:"V, S, M (recipiente dorado, 1000+ gp, consumido)", duracion:"Instantáneo", clases:["Clérigo","Druida"], desc2024:"En 2024: el festín aparece en un cubo libre de 10 ft junto a vos (alcance Personal) y también lo aprende el Bardo. Hasta doce criaturas pueden comer (1 hora). Quien lo hace obtiene por 24 horas Resistencia al daño de veneno, Inmunidad a Asustado y Envenenado, y +2d10 a su máximo de PG (y esos mismos PG). Ya no cura enfermedades ni da ventaja en salvaciones de Sabiduría.", desc:"Un festín aparece; quienes coman se curan por completo, ganan +2d10 HP máximo por 24 horas, e inmunidad a miedo/veneno con ventaja en salvaciones de Sabiduría durante ese tiempo."},
{name:"Move Earth", nivel:6, edicion:"ambas", etiquetas:["utilidad"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"120 ft", componentes:"V, S, M (piedra de hierro, marfil o diamante talladas)", duracion:"Conc., hasta 2 horas", clases:["Druida","Hechicero","Mago"], desc:"Excavás, aplanás o reformás tierra/roca no mágica en un área de hasta 40 ft de cubo durante la duración."},
{name:"Sunbeam", nivel:6, edicion:"ambas", etiquetas:["daño","radiante","salvación"], escuela:"Evocación", tiempo:"1 Acción", alcance:"Personal (línea 60 ft)", componentes:"V, S, M (lupa)", duracion:"Conc., hasta 1 min", clases:["Druida","Hechicero","Mago"], desc2024:"En 2024: los muertos vivientes y las cienagas ya no tienen desventaja en la salvación, y también lo aprende el Clérigo. Una criatura que falla queda Cegada hasta el inicio de tu próximo turno; si salva, solo sufre la mitad del daño. Para crear una nueva línea usás la acción Magia. El resto no cambia (5x60 ft, salvación de Constitución, 6d8 daño radiante).", desc:"Un rayo de luz radiante ilumina una línea de 5x60 ft; cada criatura ahí hace salvación de Constitución, sufriendo 6d8 daño radiante (mitad si salva) y quedando cegada hasta tu próximo turno."},
{name:"Transport via Plants", nivel:6, edicion:"ambas", etiquetas:["utilidad","teletransporte"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"10 ft", componentes:"V, S", duracion:"1 turno", clases:["Druida"], desc2024:"La duración pasa de 1 asalto a 1 minuto: el enlace mágico entre una planta inanimada Grande o mayor a tu alcance (10 ft) y otra planta a cualquier distancia en el mismo plano (que hayas visto o tocado) permanece 1 minuto, durante el cual cualquier criatura puede entrar en la planta objetivo y salir por la de destino gastando 5 ft de movimiento.", desc:"Creás un portal mágico entre una planta grande cercana y otra que conozcas, permitiendo el paso instantáneo entre ambas."},
{name:"Wall of Thorns", nivel:6, edicion:"ambas", etiquetas:["daño","perforante","control"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"120 ft", componentes:"V, S, M (una zarza)", duracion:"Conc., hasta 10 min", clases:["Druida"], desc:"Creás un muro de zarzas espinosas de hasta 60 ft de largo; cruzarlo causa daño perforante y cortante (salvación de Destreza para mitad)."},
{name:"Wind Walk", nivel:6, edicion:"ambas", etiquetas:["utilidad"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, S, M (fuego y aire aromático)", duracion:"8 horas", clases:["Druida"], desc2024:"En 2024: vos y hasta diez criaturas voluntarias a tu alcance adoptan forma gaseosa durante 8 horas, como jirones de nube. En esa forma, cada objetivo tiene velocidad de vuelo 300 ft y puede flotar, es inmune a la condición Derribado y tiene resistencia al daño contundente, perforante y cortante. Solo puede usar la acción Correr o una acción de Magia para empezar a revertir; revertir tarda 1 minuto, durante el cual está Aturdido. Mientras dure el hechizo puede volver a la forma de nube (acción de Magia + 1 minuto de transformación). Si termina el efecto mientras vuela en forma de nube, desciende 60 ft por asalto durante 1 minuto hasta aterrizar sin daño; si no logra aterrizar en 1 minuto, cae el resto de la distancia.", desc:"Hasta 10 criaturas voluntarias tocadas se transforman en una forma gaseosa nebulosa, con velocidad de vuelo de 300 ft, durante la duración."},
{name:"Blade Barrier", nivel:6, edicion:"ambas", etiquetas:["daño", "cortante", "salvación", "control", "invocación"], escuela:"Evocación", tiempo:"1 Acción", alcance:"90 ft", componentes:"V, S", duracion:"Conc., hasta 10 min", clases:["Clérigo"], desc:"Creás un muro vertical de cuchillas giratorias de energía mágica: recto de hasta 100 ft de largo, 20 ft de alto y 5 ft de espesor, o circular de hasta 60 ft de diámetro, 20 ft de alto y 5 ft de espesor. Da cobertura de tres cuartos a quienes están detrás y su espacio es terreno difícil. Cuando una criatura entra por primera vez en un turno al área o empieza su turno ahí, hace salvación de Destreza: sufre 6d10 daño cortante, o la mitad si salva.", desc2024:"En 2024 el daño es de fuerza (no cortante), y la criatura que está en el espacio del muro, entra a él o termina su turno ahí hace salvación de Destreza: 6d10 daño de fuerza, mitad si salva; la hace una sola vez por turno. Sigue dando cobertura de tres cuartos y su espacio es terreno difícil."},
{name:"Chain Lightning", nivel:6, edicion:"ambas", etiquetas:["daño", "rayo", "salvación"], escuela:"Evocación", tiempo:"1 Acción", alcance:"150 ft", componentes:"V, S, M (un poco de pelaje; una pieza de ámbar, vidrio o una varilla de cristal; y tres alfileres de plata)", duracion:"Instantáneo", clases:["Hechicero", "Mago"], desc:"Creás un rayo que salta hacia un objetivo que veas a tu alcance; luego tres rayos saltan de ese objetivo a hasta otros tres objetivos a 30 ft del primero. Un objetivo puede ser criatura u objeto y solo puede ser blanco de un rayo. Cada objetivo hace una salvación de Destreza: sufre 10d8 daño de relámpago si falla, la mitad si supera. A niveles superiores: un rayo adicional salta del primer objetivo por cada nivel de espacio sobre 6."},
{name:"Circle of Death", nivel:6, edicion:"ambas", etiquetas:["daño", "necrótico", "salvación"], escuela:"Necromancia", tiempo:"1 Acción", alcance:"150 ft", componentes:"V, S, M (polvo de una perla negra triturada valuada en al menos 500 po)", duracion:"Instantáneo", clases:["Hechicero", "Brujo", "Mago"], desc:"Una esfera de energía negativa de 60 ft de radio se expande desde un punto a tu alcance; cada criatura en el área hace una tirada de salvación de Constitución y sufre 8d6 daño necrótico si falla, o la mitad si salva. A niveles superiores: el daño aumenta en 2d6 por cada nivel de espacio por encima del 6.º.", desc2024:"En 2024 el daño es 8d8 necrótico (mitad si salva la Constitución). A niveles superiores: aumenta en 2d8 por cada nivel de espacio por encima del 6.º."},
{name:"Contingency", nivel:6, edicion:"ambas", etiquetas:["utilidad", "protección"], escuela:"Evocación", tiempo:"10 minutos", alcance:"Personal", componentes:"V, S, M (una estatuilla de vos mismo tallada en marfil y decorada con gemas, de al menos 1.500 gp)", duracion:"10 días", clases:["Mago"], desc:"Elegís un conjuro de nivel 5 o menor que puedas lanzar, con tiempo de lanzamiento de 1 acción y que pueda tenerte como objetivo. Lo lanzás como parte de Contingency, gastando espacios de conjuro para ambos, pero no se activa: lo hace cuando ocurre una circunstancia que describís al lanzarlos (p. ej. Water Breathing al quedar sumergido). Se activa justo después de cumplirse la circunstancia por primera vez, lo quieras o no, y Contingency termina. Solo te afecta a vos, aunque normalmente pueda afectar a otros. Solo un Contingency a la vez (relanzarlo termina el anterior) y termina si el componente material no está en tu persona."},
{name:"Create Undead", nivel:6, edicion:"ambas", etiquetas:["invocación", "control"], escuela:"Necromancia", tiempo:"1 minuto", alcance:"10 ft", componentes:"V, S, M (una vasija de arcilla con tierra de tumba, otra con agua salobre y una piedra de ónix negro de 150 gp por cada cadáver)", duracion:"Instantáneo", clases:["Clérigo", "Brujo", "Mago"], desc:"Solo se puede lanzar de noche. Elegís hasta tres cadáveres de humanoides Medianos o Pequeños a tu alcance; cada uno se vuelve un necrófago (ghoul) bajo tu control. Con una acción adicional en cada uno de tus turnos podés darles órdenes mentales si están a 120 ft o menos (a varios a la vez, con la misma orden): decidís su acción y movimiento del próximo turno o una orden general, como custodiar un lugar. Sin órdenes, solo se defienden de criaturas hostiles. Siguen una orden hasta cumplirla. Los controlás 24 horas; luego dejan de obedecer. Para mantener el control otras 24 horas, debés lanzar el hechizo sobre ellos antes de que termine el período; ese uso reafirma el control sobre hasta tres criaturas en vez de animar nuevas. A niveles superiores: espacio de nivel 7, cuatro ghouls; nivel 8, cinco ghouls o dos ghasts o wights; nivel 9, seis ghouls, tres ghasts o wights, o dos momias.", desc2024:"En 2024 el componente material es solo una piedra de ónix negro de 150+ gp por cadáver. Solo de noche; hasta tres cadáveres de humanoides Medianos o Pequeños se vuelven Ghouls bajo tu control. Con una acción adicional en tus turnos les ordenás mentalmente si están a 120 ft (órdenes específicas o generales). Si no les das órdenes, el ser toma la acción Esquivar y se mueve solo para evitar daño. Los controlás 24 horas; para mantener el control, volvés a lanzar el hechizo sobre ellos antes de que termine el período (reafirma el control de hasta tres criaturas). A niveles superiores: nivel 7, cuatro ghouls; nivel 8, cinco ghouls o dos ghasts o wights; nivel 9, seis ghouls, tres ghasts o wights, o dos momias."},
{name:"Disintegrate", nivel:6, edicion:"ambas", etiquetas:["daño", "fuerza", "salvación"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S, M (una piedra imán y una pizca de polvo)", duracion:"Instantáneo", clases:["Hechicero", "Mago"], desc:"Un delgado rayo verde sale de tu dedo hacia un objetivo que veas a alcance: una criatura, un objeto o una creación de fuerza mágica (como el muro de Wall of Force). Una criatura hace salvación de Destreza; si falla, sufre 10d6 + 40 daño de fuerza, y si esto la reduce a 0 PG se desintegra: ella y todo lo que lleve puesto o cargue, salvo objetos mágicos, quedan reducidos a polvo gris, y solo True Resurrection o Wish pueden revivirla. Desintegra automáticamente un objeto no mágico Grande o menor o una creación de fuerza; si es Enorme o mayor, desintegra un cubo de 10 ft. Un objeto mágico no se ve afectado. A niveles superiores: +3d6 de daño por cada nivel de espacio por encima de 6."},
{name:"Eyebite", nivel:6, edicion:"ambas", etiquetas:["control", "salvación"], escuela:"Necromancia", tiempo:"1 Acción", alcance:"Personal", componentes:"V, S", duracion:"Conc., hasta 1 min", clases:["Bardo", "Hechicero", "Brujo", "Mago"], desc:"Tus ojos se vuelven un vacío de tinta. Una criatura de tu elección que veas a 60 ft hace salvación de Sabiduría o sufre un efecto a tu elección. En cada uno de tus turnos podés usar tu acción para apuntar a otra criatura, pero no a una que ya superó la salvación contra este lanzamiento. Dormido: cae Inconsciente; despierta si recibe daño o si otra criatura usa su acción para sacudirla. Pánico: queda Asustada de vos y en cada uno de sus turnos debe correr (Dash) alejándose por la ruta más segura y corta; termina si llega a 60+ ft de vos y deja de verte. Enfermo: desventaja en tiradas de ataque y pruebas de característica; al final de cada uno de sus turnos repite la salvación y, si la supera, termina.", desc2024:"En 2024: igual salvación de Sabiduría y efectos Dormido (Inconsciente, despierta con daño o sacudida) y Pánico (Asustada, debe correr alejándose; termina a 60+ ft si no te ve), pero cambia Enfermo: la criatura queda Envenenada (ya no hay repetición de salvación). Redirigís el efecto con una acción de Magia en tus turnos siguientes, sin repetir objetivos que superaron la salvación."},
{name:"Flesh to Stone", nivel:6, edicion:"ambas", etiquetas:["control", "salvación"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S, M (una pizca de cal, agua y tierra)", duracion:"Conc., hasta 1 min", clases:["Brujo", "Mago"], desc:"Intentás convertir en piedra a una criatura que veas a tu alcance. Si su cuerpo es de carne, hace una salvación de Constitución: si falla, queda Apresada mientras su carne empieza a endurecerse; si supera, no sufre efecto. La criatura Apresada repite la salvación al final de cada uno de sus turnos: con tres éxitos el conjuro termina; con tres fallos se convierte en piedra y queda Petrificada mientras dure. Los éxitos y fallos no tienen que ser consecutivos. Si queda deformada físicamente mientras está petrificada, conservará esas deformidades al revertir. Si mantenés la concentración toda la duración posible, queda petrificada hasta que se quite el efecto.", desc2024:"Ya no depende de que el cuerpo sea de carne: el objetivo hace una salvación de Constitución; si falla, queda Apresado mientras dure; si supera, su velocidad es 0 hasta el inicio de tu próximo turno. Los autómatas (constructos) superan la salvación automáticamente. Repite la salvación al final de cada uno de sus turnos (tres éxitos terminan el conjuro; tres fallos lo petrifican, no necesariamente consecutivos). Si mantenés la concentración toda la duración posible, queda Petrificado hasta que Greater Restoration o magia similar termine la condición. En 2024 también es conjuro de Druida."},
{name:"Forbiddance", nivel:6, edicion:"ambas", etiquetas:["protección", "utilidad", "daño", "radiante", "necrótico"], escuela:"Abjuración", tiempo:"10 minutos (ritual)", alcance:"Toque", componentes:"V, S, M (agua bendita rociada, incienso raro y polvo de rubí valuado en al menos 1.000 po)", duracion:"24 horas", clases:["Clérigo"], desc:"Creás una protección contra el viaje mágico sobre hasta 40.000 pies cuadrados de suelo, hasta 30 ft de altura. Durante la duración, las criaturas no pueden teletransportarse al área ni usar portales (como los de Gate) para entrar; el área queda a salvo del viaje planar (Plano Astral, Etéreo, Feywild, Shadowfell, Plane Shift). Además, dañás a los tipos de criatura que elijas al lanzarlo (celestiales, elementales, feéricos, demonios, muertos vivientes): cuando una criatura elegida entra en el área por primera vez en un turno o empieza su turno allí, sufre 5d10 daño radiante o necrótico (a tu elección al lanzarlo). Podés designar una contraseña: quien la diga al entrar no sufre daño. El área no puede superponerse con otro Forbiddance. Si lo lanzás cada día durante 30 días en el mismo lugar, dura hasta que se disipe y los componentes materiales se consumen en el último lanzamiento.", desc2024:"En 2024 el conjuro también puede dañar a las Aberraciones (además de celestiales, elementales, feéricos, demonios y muertos vivientes), y el daño de 5d10 radiante o necrótico se aplica cuando la criatura elegida entra en el área por primera vez en un turno o termina su turno allí. La duración es 1 día."},
{name:"Freezing Sphere", nivel:6, edicion:"ambas", etiquetas:["daño", "frío", "salvación", "control"], escuela:"Evocación", tiempo:"1 Acción", alcance:"300 ft", componentes:"V, S, M (una pequeña esfera de cristal)", duracion:"Instantáneo", clases:["Mago"], desc:"Un glóbulo gélido sale de tus dedos hacia un punto de alcance y estalla en una esfera de 60 ft de radio. Cada criatura hace salvación de Constitución: si falla sufre 10d6 daño de frío (mitad si salva). Si golpea agua o un líquido principalmente de agua, lo congela hasta 6 pulgadas de profundidad en un área de 30 ft por lado durante 1 minuto; las criaturas que nadaban en la superficie quedan atrapadas y pueden usar una acción para una prueba de Fuerza contra tu CD para liberarse. Podés no disparar el glóbulo: aparece en tu mano una esfera del tamaño de una piedra de honda, fría al tacto, que vos o quien se la des puede arrojar (40 ft) o lanzar con honda; estalla al impactar con el mismo efecto. Podés dejarla sin romperla; tras 1 minuto, si no se rompió, estalla. A niveles superiores: +1d6 de daño por cada nivel de espacio por encima de 6.", desc2024:"En 2024 también lo lanzan los Hechiceros. Igual en daño (10d6 de frío, salvación de Constitución, mitad si salva, esfera de 60 ft) y escalado (+1d6 por nivel por encima de 6). Si golpea agua la congela 6 pulgadas en 30 ft por lado durante 1 minuto, y las criaturas que nadaban quedan atrapadas y Apresadas; para liberarse usan una acción para una prueba de Fuerza (Atletismo) contra tu CD. Podés conservar el glóbulo para lanzarlo después (40 ft) y estalla al minuto si no se rompió."},
{name:"Globe of Invulnerability", nivel:6, edicion:"ambas", etiquetas:["protección"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"Personal", componentes:"V, S, M (una cuenta de vidrio o cristal que se rompe al terminar el conjuro)", duracion:"Conc., hasta 1 min", clases:["Hechicero", "Mago"], desc:"Una barrera inmóvil y tenuemente reluciente de 10 ft de radio aparece a tu alrededor. Cualquier conjuro de nivel 5 o menor lanzado desde fuera no puede afectar a criaturas ni objetos dentro, aunque se lance con un espacio de nivel superior: puede apuntarlos, pero no tiene efecto, y el área de la barrera queda excluida de las áreas de esos conjuros. A niveles superiores: la barrera bloquea conjuros de un nivel más por cada nivel de espacio por encima de 6."},
{name:"Guards and Wards", nivel:6, edicion:"ambas", etiquetas:["protección", "control", "utilidad"], escuela:"Abjuración", tiempo:"10 minutos", alcance:"Toque", componentes:"V, S, M (incienso ardiendo, un poco de azufre y aceite, una cuerda anudada, un poco de sangre de umber hulk y una varilla de plata de al menos 10 gp)", duracion:"24 horas", clases:["Bardo", "Mago"], desc:"Protegés hasta 2.500 pies cuadrados de suelo (50 ft por lado, cien cuadrados de 5 ft o veinticinco de 10 ft), de hasta 20 ft de alto y con la forma que quieras; podés dividirla en varios pisos si podés caminar por cada área contigua al lanzarlo. Podés exceptuar individuos y fijar una contraseña que inmuniza a quien la diga. Pasillos: niebla (muy oscurecido); en cada intersección hay 50% de que una criatura que no seas vos crea ir en la dirección opuesta. Puertas: cerradas como con arcane lock; hasta diez pueden disfrazarse de pared lisa. Escaleras: telarañas como web, que rebrotan en 10 minutos. Otro efecto a elección: dancing lights en cuatro pasillos, magic mouth en dos lugares, stinking cloud en dos lugares (vuelve en 10 minutos si el viento la dispersa), viento constante en un pasillo o sala, o suggestion en un área de 5 ft por lado (la recibe quien entre). Toda el área irradia magia; dispel magic sobre un efecto solo quita ese efecto. Lanzarlo cada día durante un año la vuelve permanente.", desc2024:"En 2024 se lanza en 1 hora (no 10 minutos) y el material es solo una varilla de plata de 10+ gp. Protegés hasta 2.500 pies cuadrados, de hasta 20 ft de alto: un cuadrado de 50 ft, cien de 5 ft contiguos o veinticinco de 10 ft contiguos. Exceptuás individuos y fijás una contraseña que, dicha a 5 ft del área, inmuniza a quien la diga. Dispel Magic no afecta al hechizo en sí sino a cada efecto; si se disipan los cuatro, termina; lanzado cada día durante 365 días en la misma área, dura hasta que se disipen todos sus efectos. Pasillos: niebla y 50% de confundir la dirección. Puertas: cerradas como Arcane Lock; hasta diez disfrazadas con ilusión. Escaleras: telarañas como Web (rebrotan en 10 minutos). Otro efecto: Dancing Lights en cuatro pasillos, Magic Mouth o Stinking Cloud en dos lugares, Gust of Wind continuo en un pasillo o sala, o Suggestion en un cuadrado de 5 ft."},
{name:"Harm", nivel:6, edicion:"ambas", etiquetas:["daño", "necrótico", "salvación"], escuela:"Necromancia", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S", duracion:"Instantáneo", clases:["Clérigo"], desc:"Desatás una enfermedad virulenta sobre una criatura que veas a alcance, que hace salvación de Constitución: si falla, sufre 14d6 daño necrótico (mitad si salva). El daño no puede reducir sus PG por debajo de 1. Si falla la salvación, su máximo de PG se reduce durante 1 hora en una cantidad igual al daño necrótico sufrido; cualquier efecto que cure una enfermedad permite que vuelva a la normalidad antes.", desc2024:"En 2024 desatás magia virulenta sobre una criatura que veas a alcance, que hace salvación de Constitución: si falla, sufre 14d6 daño necrótico y su máximo de PG se reduce en una cantidad igual al daño necrótico sufrido; si salva, sufre solo la mitad del daño. El conjuro no puede reducir el máximo de PG de un objetivo por debajo de 1. Ya no se aclara que el daño no pueda bajarlo de 1 PG, ni que la reducción dure 1 hora o termine con un efecto que cure enfermedades."},
{name:"Instant Summons", nivel:6, edicion:"ambas", etiquetas:["utilidad", "teletransporte"], escuela:"Conjuración", tiempo:"1 minuto (ritual)", alcance:"Toque", componentes:"V, S, M (un zafiro que valga 1.000 po)", duracion:"Hasta que se disipe", clases:["Mago"], desc:"Tocás un objeto de 10 libras o menos cuya dimensión mayor sea de 6 ft o menos. El conjuro deja una marca invisible en él e inscribe invisiblemente su nombre en el zafiro usado como componente (cada lanzamiento requiere un zafiro distinto). Más adelante, podés usar tu acción para decir el nombre del objeto y triturar el zafiro: el objeto aparece al instante en tu mano sin importar la distancia física o entre planos, y el conjuro termina. Si otra criatura lo sostiene o carga, no se transporta, pero sabés quién es y aproximadamente dónde está en ese momento. Disipar magia o un efecto similar aplicado con éxito al zafiro termina el conjuro."},
{name:"Irresistible Dance", nivel:6, edicion:"ambas", etiquetas:["control"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"30 ft", componentes:"V", duracion:"Conc., hasta 1 min", clases:["Bardo", "Mago"], desc:"Elegís una criatura que veas a tu alcance: empieza un baile cómico en el lugar, durante la duración. Las criaturas que no pueden ser Hechizadas son inmunes. La criatura debe usar todo su movimiento para bailar sin salir de su espacio, tiene desventaja en las tiradas de salvación de Destreza y en las tiradas de ataque, y las demás criaturas tienen ventaja en las tiradas de ataque contra ella. Con su acción, la criatura bailarina hace una tirada de salvación de Sabiduría para recuperar el control; si tiene éxito, el conjuro termina.", desc2024:"En 2024 el objetivo hace primero una tirada de salvación de Sabiduría. Si salva, baila cómicamente hasta el final de su siguiente turno, gastando todo su movimiento en bailar en el lugar. Si falla, queda Hechizado durante la duración: baila cómicamente, usa todo su movimiento para bailar en el lugar, tiene desventaja en salvaciones de Destreza y tiradas de ataque, y las demás criaturas tienen ventaja contra él. En cada uno de sus turnos puede usar una acción para recomponerse y repetir la salvación; si la supera, el conjuro termina."},
{name:"Magic Jar", nivel:6, edicion:"ambas", etiquetas:["control", "utilidad"], escuela:"Necromancia", tiempo:"1 minuto", alcance:"Personal", componentes:"V, S, M (una gema, cristal, relicario u otro recipiente ornamental que valga al menos 500 po)", duracion:"Hasta que se disipe", clases:["Mago"], desc:"Tu cuerpo cae en estado catatónico y tu alma entra en el recipiente del material; percibís tu entorno desde su espacio, pero no podés moverte ni usar reacciones. Solo podés proyectar tu alma hasta 100 ft fuera del recipiente para volver a tu cuerpo (termina el hechizo) o intentar poseer a un humanoide que veas a 100 ft (los protegidos por protección contra el bien y el mal o círculo mágico no pueden ser poseídos). El objetivo hace salvación de Carisma: si falla, tu alma entra en su cuerpo y la suya queda atrapada en el recipiente; si salva, no podés intentarlo de nuevo por 24 horas. Controlás el cuerpo poseído con sus estadísticas, salvo alineamiento, Inteligencia, Sabiduría y Carisma, y conservás tus rasgos de clase. Con tu acción volvés al recipiente si está a 100 ft. Si el huésped muere, hacés una salvación de Carisma contra tu CD: si tenés éxito volvés al recipiente a 100 ft; si no, morís. Si el recipiente se destruye o el hechizo termina, tu alma vuelve a tu cuerpo (si está a más de 100 ft o muerto, morís); el alma atrapada vuelve a su cuerpo si está vivo y a 100 ft, si no muere. Al terminar, el recipiente se destruye.", desc2024:"En 2024 el recipiente es una gema, cristal o relicario de al menos 500 po. Al poseer un cuerpo, tus PG, Dados de Golpe, Fuerza, Destreza, Constitución, velocidad y sentidos pasan a ser los de la criatura y mantenés el resto de tus estadísticas; el alma poseída percibe desde el recipiente pero no puede moverse y queda Incapacitada. Volver al recipiente cuesta una acción de Magia. El resto (salvación de Carisma del objetivo, 100 ft, muerte del huésped, destrucción del recipiente) funciona igual."},
{name:"Mass Suggestion", nivel:6, edicion:"ambas", etiquetas:["control", "salvación"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, M (una lengua de serpiente y un poco de panal o una gota de aceite dulce)", duracion:"24 horas", clases:["Bardo", "Hechicero", "Brujo", "Mago"], desc:"Sugerís un curso de acción (una o dos frases) a hasta doce criaturas que veas en alcance y que te oigan y entiendan. Las que no pueden ser hechizadas son inmunes. Debe sonar razonable: pedir algo obviamente dañino (apuñalarse, arrojarse a una lanza) anula el efecto. Cada objetivo hace salvación de Sabiduría; si falla, cumple la sugerencia lo mejor que pueda durante toda la duración, o hasta completarla si es más corta. Podés fijar condiciones que activen una actividad especial; si no se cumple antes del final, no se realiza. Si vos o tus compañeros dañan a una criatura afectada, el conjuro termina para ella. A niveles superiores: duración de 10 días (nivel 7), 30 días (nivel 8) y un año y un día (nivel 9).", desc2024:"En 2024: ya no está en la lista del Brujo y el material es solo una lengua de serpiente. La sugerencia debe describirse en 25 palabras o menos; hasta doce criaturas que veas y te oigan hacen salvación de Sabiduría o quedan Hechizadas (hasta la duración o hasta que vos o tus aliados les causen daño) y cumplen la sugerencia lo mejor posible. No puede implicar daño evidente para los objetivos ni sus aliados. A niveles superiores: duración de 10 días (nivel 7), 30 días (8) y 366 días (9)."},
{name:"Planar Ally", nivel:6, edicion:"ambas", etiquetas:["invocación", "utilidad"], escuela:"Conjuración", tiempo:"10 minutos", alcance:"60 ft", componentes:"V, S", duracion:"Instantáneo", clases:["Clérigo"], desc:"Suplicás ayuda a una entidad de otro mundo que conozcas (un dios, un primordial, un príncipe demonio u otro ser de poder cósmico), que envía a un celestial, elemental o infernal leal a ella, el cual aparece en un espacio libre a alcance. Si conocés el nombre de una criatura concreta, podés pedirla, aunque el DM puede enviar otra. La criatura no está obligada a nada: podés pedirle un servicio a cambio de pago, y debés poder comunicarte para negociar. Referencia: 100 po por minuto, 1.000 po por hora o 10.000 po por día (hasta 10 días); el DM ajusta el pago (mitad o nada si coincide con su ética, la mitad si no hay riesgo, más si es muy peligroso; rara vez acepta tareas suicidas). Al terminar la tarea, o si no hay acuerdo, vuelve a su plano de origen. Si se une a tu grupo, cuenta como miembro y recibe una parte completa de la experiencia."},
{name:"Programmed Illusion", nivel:6, edicion:"ambas", etiquetas:["ilusión"], escuela:"Ilusión", tiempo:"1 Acción", alcance:"120 ft", componentes:"V, S, M (un poco de vellón y polvo de jade por 25 po como mínimo)", duracion:"Hasta que se disipe", clases:["Bardo", "Mago"], desc:"Creás la ilusión de un objeto, criatura u otro fenómeno visible (no mayor que un cubo de 30 ft) que se activa cuando ocurre una condición específica; hasta entonces es imperceptible. Decidís al lanzarla cómo se comporta y qué sonidos hace (hasta 5 minutos). Al terminar se desvanece y queda inactiva 10 minutos, tras los cuales puede activarse otra vez. La condición debe basarse en fenómenos visuales o sonoros a 30 ft de la zona. Una criatura que use su acción para examinarla la descubre con una prueba de Inteligencia (Investigación) contra tu CD; entonces ve a través de ella y su ruido suena hueco."},
{name:"True Seeing", nivel:6, edicion:"ambas", etiquetas:["adivinación", "buff", "utilidad"], escuela:"Adivinación", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S, M (ungüento para los ojos de 25 po, hecho de polvo de hongos, azafrán y grasa, que el conjuro consume)", duracion:"1 hora", clases:["Bardo", "Clérigo", "Hechicero", "Brujo", "Mago"], desc:"La criatura voluntaria que tocás puede ver las cosas como realmente son. Durante la duración tiene visión verdadera, nota puertas secretas ocultas por magia y puede ver el Plano Etéreo, todo hasta un alcance de 120 ft."},
{name:"Wall of Ice", nivel:6, edicion:"ambas", etiquetas:["daño", "frío", "salvación", "control", "invocación"], escuela:"Evocación", tiempo:"1 Acción", alcance:"120 ft", componentes:"V, S, M (un trozo pequeño de cuarzo)", duracion:"Conc., hasta 10 min", clases:["Mago"], desc:"Creás un muro de hielo sobre una superficie sólida en alcance: una cúpula hemisférica o una esfera de hasta 10 ft de radio, o una superficie plana de diez paneles contiguos de 10 ft por lado. En cualquier forma, tiene 1 ft de grosor. Si corta el espacio de una criatura al aparecer, esta es empujada a un lado del muro y hace salvación de Destreza: sufre 10d6 daño de frío (mitad si salva). El muro es un objeto con CA 12 y 30 PG por sección de 10 ft, vulnerable al daño de fuego. Al llevar una sección a 0 PG se destruye y deja una lámina de aire gélido; la criatura que la atraviese por primera vez en un turno hace salvación de Constitución y sufre 5d6 daño de frío (mitad si salva). A niveles superiores: +2d6 al daño inicial y +1d6 al del aire gélido por cada nivel de espacio por encima de 6.", desc2024:"En 2024 el muro además tiene inmunidad al daño de frío, de veneno y psíquico, y elegís hacia qué lado se empuja a la criatura cuyo espacio corta. El resto igual: 10d6 de frío (salvación de Destreza, mitad si salva), CA 12, 30 PG por sección, vulnerable al fuego, y aire gélido con salvación de Constitución (5d6 de frío). A niveles superiores: +2d6 al daño inicial y +1d6 al del aire gélido por nivel por encima de 6."},
{name:"Word of Recall", nivel:6, edicion:"ambas", etiquetas:["teletransporte"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"5 ft", componentes:"V", duracion:"Instantáneo", clases:["Clérigo"], desc:"Vos y hasta cinco criaturas voluntarias a 5 ft de vos se teletransportan instantáneamente a un santuario designado antes, apareciendo en el espacio libre más cercano al punto que marcaste. Si lo lanzás sin haber preparado un santuario, no tiene efecto. El santuario se designa lanzando el conjuro en un lugar, como un templo, dedicado a tu deidad o fuertemente vinculado a ella; si el lugar no está dedicado a tu deidad, no tiene efecto.", desc2024:"En 2024 el santuario se designa lanzando el conjuro en cualquier lugar, como un templo; ya no hace falta que esté dedicado a tu deidad. El resto no cambia: vos y hasta cinco criaturas voluntarias a 5 ft se teletransportan al santuario designado, y sin santuario previo no tiene efecto."},

// ===== NIVEL 7 =====
{name:"Fire Storm", nivel:7, edicion:"ambas", etiquetas:["daño","fuego","salvación"], escuela:"Evocación", tiempo:"1 Acción", alcance:"150 ft", componentes:"V, S", duracion:"Instantáneo", clases:["Clérigo","Druida"], desc2024:"En 2024: aparece una tormenta de fuego a tu alcance (150 ft) formada por hasta diez cubos de 10 ft, cada uno contiguo a al menos otro. Cada criatura en el área hace salvación de Destreza: 7d10 de daño de fuego si falla, mitad si salva. Los objetos inflamables en el área que no estén equipados ni llevados empiezan a arder. Ya no existe la opción de que la vegetación no sea afectada.", desc:"Fuego llena un área compuesta de hasta diez cubos de 10 ft; cada criatura ahí hace salvación de Destreza, sufriendo 7d10 daño de fuego (mitad si salva)."},
{name:"Mirage Arcane", nivel:7, edicion:"ambas", etiquetas:["ilusión"], escuela:"Ilusión", tiempo:"10 minutos", alcance:"Personal", componentes:"V, S", duracion:"10 días", clases:["Bardo","Druida","Mago"], desc:"Alterás la apariencia del terreno en un área grande (hasta 1 milla de cubo) durante hasta 10 días, incluyendo sonidos, olores y temperatura."},
{name:"Plane Shift", nivel:7, edicion:"ambas", etiquetas:["utilidad","teletransporte"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S, M (bifurcación afinada al plano de destino)", duracion:"Instantáneo", clases:["Clérigo","Druida","Hechicero","Brujo","Mago"], desc2024:"Se elimina la opción de desterrar: ya no se puede enviar a una criatura involuntaria a otro plano con un ataque de conjuro cuerpo a cuerpo y salvación de Carisma. Solo transporta a vos y hasta ocho criaturas voluntarias que se tomen de las manos en círculo; el destino se indica en términos generales (una ciudad específica del Plano Elemental del Fuego, por ejemplo) y el DM determina dónde aparecés, o a un círculo de teletransporte cuya secuencia de sigilos conozcas. Requiere una varilla de metal bifurcada de 250+ po sintonizada a un plano.", desc:"Vos y hasta 8 criaturas voluntarias tocadas son transportadas a otro plano de existencia (salvación de Carisma si el objetivo es hostil)."},
{name:"Regenerate", nivel:7, edicion:"ambas", etiquetas:["curación"], escuela:"Transmutación", tiempo:"1 minuto", alcance:"Toque", componentes:"V, S, M (jengibre fresco)", duracion:"1 hora", clases:["Bardo","Clérigo","Druida","Paladín"], desc:"La criatura tocada recupera 4d8+15 HP inmediatamente, y luego 1 HP al inicio de cada turno durante 1 hora; puede regenerar miembros perdidos."},
{name:"Reverse Gravity", nivel:7, edicion:"ambas", etiquetas:["control"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"100 ft", componentes:"V, S, M (piedra imán y trozo de hierro)", duracion:"Conc., hasta 1 min", clases:["Druida","Hechicero","Mago"], desc:"La gravedad se invierte en un cilindro de 50 ft de radio; todo lo que no esté asegurado ahí cae hacia arriba durante la duración."},
{name:"Arcane Sword", nivel:7, edicion:"ambas", etiquetas:["daño", "fuerza", "ataque", "invocación"], escuela:"Evocación", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S, M (una espada de platino en miniatura con empuñadura y pomo de cobre y zinc, de 250 po)", duracion:"Conc., hasta 1 min", clases:["Bardo", "Mago"], desc:"Creás un plano de fuerza con forma de espada que flota a 60 ft de vos. Al aparecer hacés un ataque de conjuro cuerpo a cuerpo contra un objetivo a 5 ft de la espada: si impacta, sufre 3d10 daño de fuerza. Mientras dure, con una acción adicional en cada uno de tus turnos movés la espada hasta 20 ft a un punto que veas y repetís el ataque contra el mismo objetivo u otro.", desc2024:"En 2024: alcance 90 ft. Creás una espada espectral; al aparecer, ataque de conjuro cuerpo a cuerpo contra un objetivo a 5 ft de ella: si impacta, sufre daño de fuerza igual a 4d12 + tu modificador de característica de lanzamiento. En turnos posteriores, con una acción adicional movés la espada hasta 30 ft y repetís el ataque contra el mismo objetivo u otro."},
{name:"Conjure Celestial", nivel:7, edicion:"ambas", etiquetas:["invocación"], escuela:"Conjuración", tiempo:"1 minuto", alcance:"90 ft", componentes:"V, S", duracion:"Conc., hasta 1 hora", clases:["Clérigo"], desc:"Invocás un celestial de CR 4 o menor, que aparece en un espacio libre que veas en alcance y desaparece al llegar a 0 PG o cuando termina el hechizo. Es amistoso con vos y tus compañeros mientras dure. Tira iniciativa propia, con sus turnos, y obedece tus órdenes verbales (no te cuestan acción) mientras no violen su alineamiento; sin órdenes se defiende de criaturas hostiles pero no hace nada más. El DM tiene sus estadísticas. A niveles superiores: con un espacio de nivel 9 invocás un celestial de CR 5 o menor.", desc2024:"En 2024 ya no invoca una criatura: es 1 Acción, concentración hasta 10 min. Conjurás un espíritu de los Planos Superiores como un pilar de luz (cilindro de 10 ft de radio y 40 ft de alto) centrado en un punto del alcance. Por cada criatura que veas dentro, elegís su luz: Luz Curativa (recupera 4d12 + tu modificador de característica de lanzamiento PG) o Luz Abrasadora (salvación de Destreza: 6d12 daño radiante, mitad si salva). El cilindro da luz brillante y, al moverte en tu turno, podés moverlo hasta 30 ft. Podés bañar con una luz a la criatura cuyo espacio toque el cilindro, o que entre o termine su turno en él; una criatura se ve afectada una vez por turno. A niveles superiores: +1d12 de curación y daño por cada nivel de espacio por encima de 7."},
{name:"Delayed Blast Fireball", nivel:7, edicion:"ambas", etiquetas:["daño", "fuego", "salvación"], escuela:"Evocación", tiempo:"1 Acción", alcance:"150 ft", componentes:"V, S, M (una pequeña bola de guano de murciélago y azufre)", duracion:"Conc., hasta 1 min", clases:["Hechicero", "Mago"], desc:"Un haz de luz amarilla sale de tu dedo y se condensa en un punto a tu alcance como una cuenta brillante mientras dure. Cuando el conjuro termina (por perder la concentración o porque lo decidís), la cuenta explota en llamas que doblan esquinas: cada criatura en una esfera de 20 ft de radio hace una salvación de Destreza y sufre daño de fuego igual al daño acumulado total si falla, la mitad si supera. El daño base es 12d6; si al final de tu turno la cuenta no detonó, el daño aumenta en 1d6. Si una criatura toca la cuenta antes de tiempo, hace una salvación de Destreza: si falla, el conjuro termina y explota; si supera, puede arrojarla hasta 40 ft y al golpear una criatura u objeto sólido el conjuro termina y explota. El fuego daña objetos del área y enciende los inflamables que nadie lleve puestos ni cargue. A niveles superiores: el daño base aumenta 1d6 por nivel de espacio sobre 7."},
{name:"Divine Word", nivel:7, edicion:"ambas", etiquetas:["control", "salvación", "daño"], escuela:"Evocación", tiempo:"1 Acción Adicional", alcance:"30 ft", componentes:"V", duracion:"Instantáneo", clases:["Clérigo"], desc:"Pronunciás una palabra divina impregnada del poder que dio forma al mundo. Elegís cualquier número de criaturas que veas a tu alcance; cada una que pueda oírte hace una tirada de salvación de Carisma. Si falla, sufre un efecto según sus PG actuales: 50 o menos, Ensordecida 1 minuto; 40 o menos, Ensordecida y Cegada 10 minutos; 30 o menos, Cegada, Ensordecida y Aturdida 1 hora; 20 o menos, muere al instante. Sin importar sus PG, un celestial, elemental, feérico o demonio que falle es devuelto a su plano de origen (si no está allí) y no puede volver a tu plano durante 24 horas por ningún medio salvo Wish.", desc2024:"En 2024 elegís las criaturas a tu alcance (ya no necesitan oírte ni verlas) y cada una hace una salvación de Carisma; si falla y tiene 50 PG o menos, sufre un efecto según sus PG actuales: 0-20, muere; 21-30, Cegada, Ensordecida y Aturdida 1 hora; 31-40, Ensordecida y Cegada 10 minutos; 41-50, Ensordecida 1 minuto. Un celestial, elemental, feérico o demonio que falle (sin importar sus PG) es devuelto a su plano de origen y no puede volver a este plano durante 24 horas salvo con Wish."},
{name:"Etherealness", nivel:7, edicion:"ambas", etiquetas:["utilidad"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"Personal", componentes:"V, S", duracion:"8 horas", clases:["Bardo", "Clérigo", "Hechicero", "Brujo", "Mago"], desc:"Entrás en el Etéreo Fronterizo, donde el Plano Etéreo se superpone con tu plano, hasta que termine el hechizo o lo disipes con tu acción. Te movés en cualquier dirección (subir o bajar cuesta 1 ft extra por pie). Ves y oís tu plano de origen en gris, hasta 60 ft. Solo afectás y te afectan criaturas del Plano Etéreo; las demás no te perciben ni interactúan con vos salvo habilidad o magia especial. Ignorás objetos y efectos que no estén en el Etéreo, por lo que atravesás objetos del plano de origen. Al terminar volvés a tu plano en el punto que ocupás; si hay un objeto sólido o criatura, sos desplazado al espacio libre más cercano y sufrís daño de fuerza igual al doble de pies desplazados. No tiene efecto si lo lanzás en el Plano Etéreo o en un plano que no lo limite (como los Exteriores). A niveles superiores: hasta tres criaturas voluntarias (incluyéndote) a 10 ft de vos por cada nivel de espacio por encima de 7.", desc2024:"En 2024 es de escuela Conjuración, dura hasta 8 horas y ya no se puede disipar con una acción ni se describe atravesar objetos del plano de origen. Entrás en el Etéreo Fronterizo y te movés en cualquier dirección (subir o bajar cuesta 1 ft extra por pie); percibís el plano que dejaste en gris, hasta 60 ft. Solo afectás y te afectan criaturas, objetos y efectos de ese plano. Al terminar volvés al plano de origen en el espacio correspondiente; si está ocupado, te desplazan al espacio libre más cercano con daño de fuerza igual al doble de pies movidos. Termina al instante si lo lanzás en el Plano Etéreo o en un plano que no lo limite. A niveles superiores: hasta tres criaturas voluntarias (incluyéndote) por cada nivel de espacio por encima de 7, a 10 ft de vos."},
{name:"Finger of Death", nivel:7, edicion:"ambas", etiquetas:["daño", "necrótico", "salvación", "invocación"], escuela:"Necromancia", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S", duracion:"Instantáneo", clases:["Hechicero", "Brujo", "Mago"], desc:"Enviás energía negativa por el cuerpo de una criatura que veas en alcance. Hace salvación de Constitución y sufre 7d8 + 30 de daño necrótico si falla (mitad si salva). Un humanoide muerto por este conjuro se levanta al comienzo de tu próximo turno como un zombi permanentemente bajo tu mando, que sigue tus órdenes verbales lo mejor que puede.", desc2024:"En 2024: salvación de Constitución, 7d8 + 30 de daño necrótico si falla (mitad si salva). Un Humanoide muerto por el conjuro se levanta al comienzo de tu próximo turno como un Zombi que sigue tus órdenes verbales (el texto ya no dice que sea permanente)."},
{name:"Forcecage", nivel:7, edicion:"ambas", etiquetas:["control", "protección"], escuela:"Evocación", tiempo:"1 Acción", alcance:"100 ft", componentes:"V, S, M (polvo de rubí por valor de 1500 po)", duracion:"1 hora", clases:["Bardo", "Brujo", "Mago"], desc:"Una prisión inmóvil, invisible y cúbica de fuerza mágica surge alrededor de un área a alcance; podés elegir jaula o caja sólida. La jaula mide hasta 20 ft de lado, con barrotes de 1/2 pulgada de diámetro separados 1/2 pulgada. La caja mide hasta 10 ft de lado y es una barrera sólida que impide el paso de materia y bloquea conjuros lanzados hacia dentro o fuera. Las criaturas completamente dentro quedan atrapadas; las que están solo parcialmente o son demasiado grandes son empujadas fuera. Quien está dentro no puede salir por medios no mágicos; si intenta teletransportarse o viajar entre planos, hace antes salvación de Carisma: si la supera, usa la magia para salir; si falla, desperdicia el efecto. También se extiende al Plano Etéreo. No se puede disipar con Dispel Magic.", desc2024:"En 2024 requiere concentración (hasta 1 hora) y el polvo de rubí de 1500+ po se consume. El efecto es el mismo: prisión invisible de fuerza, jaula de hasta 20 ft de lado o caja sólida de hasta 10 ft; atrapa a las criaturas completamente dentro, quienes solo salen por magia de teletransporte o viaje entre planos tras superar una salvación de Carisma; se extiende al Plano Etéreo y no se puede disipar con Dispel Magic."},
{name:"Magnificent Mansion", nivel:7, edicion:"ambas", etiquetas:["invocación", "utilidad"], escuela:"Conjuración", tiempo:"1 minuto", alcance:"300 ft", componentes:"V, S, M (un portal en miniatura de marfil, un trozo de mármol pulido y una cucharita de plata, cada uno de 5 po como mínimo)", duracion:"24 horas", clases:["Bardo", "Mago"], desc:"Conjurás una morada extradimensional con una entrada de 5 ft de ancho y 10 ft de alto que elegís dónde ubicar. Vos y las criaturas que designes pueden entrar mientras el portal esté abierto; lo abrís o cerrás a 30 ft de él (cerrado es invisible). Adentro hay un vestíbulo con numerosas cámaras, hasta 50 cubos de 10 ft, amoblado como quieras, con comida para un banquete de nueve platos para 100 personas y 100 sirvientes casi transparentes, obedientes, que hacen cualquier tarea de un sirviente humano pero no pueden atacar ni dañar, ni salir de la mansión. Los objetos creados se disipan en humo si salen. Al terminar, quienes estén adentro son expulsados a los espacios libres más cercanos a la entrada."},
{name:"Prismatic Spray", nivel:7, edicion:"ambas", etiquetas:["daño", "fuego", "ácido", "rayo", "veneno", "frío", "salvación", "control"], escuela:"Evocación", tiempo:"1 Acción", alcance:"Personal (cono de 60 ft)", componentes:"V, S", duracion:"Instantáneo", clases:["Hechicero", "Mago"], desc:"Ocho rayos multicolores salen de tu mano. Cada criatura en un cono de 60 ft hace una tirada de salvación de Destreza; por cada objetivo tirás 1d8 para determinar su rayo. 1 Rojo: 10d6 daño de fuego. 2 Naranja: 10d6 de ácido. 3 Amarillo: 10d6 de relámpago. 4 Verde: 10d6 de veneno. 5 Azul: 10d6 de frío (todos: mitad si salva). 6 Índigo: si falla, queda Apresado y hace una salvación de Constitución al final de cada uno de sus turnos; con tres éxitos el conjuro termina, con tres fallos se convierte en piedra permanentemente (Petrificado); los éxitos y fallos no tienen que ser consecutivos. 7 Violeta: si falla, queda Cegado y hace una salvación de Sabiduría al inicio de tu siguiente turno: si salva, termina la ceguera; si falla, es transportado a otro plano a elección del DM y deja de estar Cegado. 8 Especial: lo golpean dos rayos; tirá dos veces más, volviendo a tirar los 8.", desc2024:"En 2024 también la tiene el Bardo. Los rayos rojo, naranja, amarillo, verde y azul infligen 12d6 de daño (mitad si salva). Índigo: si falla, queda Apresado y hace una salvación de Constitución al final de cada uno de sus turnos; con tres éxitos la condición termina, con tres fallos queda Petrificado hasta que lo libere un efecto como Greater Restoration. Violeta, si falla: Cegado, con salvación de Sabiduría al inicio de tu siguiente turno (si salva, termina la condición; si falla, termina y es transportado a otro plano a elección del DM). 8 Especial: dos rayos, volviendo a tirar los 8."},
{name:"Project Image", nivel:7, edicion:"ambas", etiquetas:["ilusión", "utilidad"], escuela:"Ilusión", tiempo:"1 Acción", alcance:"500 mi", componentes:"V, S, M (una pequeña réplica tuya hecha con materiales que valgan al menos 5 po)", duracion:"Conc., hasta 24 horas", clases:["Bardo", "Mago"], desc:"Creás una copia ilusoria de vos mismo que dura mientras dure el hechizo. Puede aparecer en cualquier lugar de alcance que hayas visto antes, sin importar los obstáculos; se ve y suena como vos pero es intangible, y si recibe cualquier daño desaparece y el hechizo termina. Con tu acción la movés hasta el doble de tu velocidad y la hacés gesticular, hablar y comportarse como quieras. Podés ver y oír a través de ella; con una acción adicional alternás entre sus sentidos y los tuyos (mientras usás los suyos estás Cegado y Ensordecido respecto de tu entorno). La interacción física revela la ilusión; una criatura que use su acción para examinarla la discierne con una prueba exitosa de Inteligencia (Investigación) contra tu CD de conjuro, y entonces ve a través de ella y sus sonidos le suenan huecos.", desc2024:"En 2024 la duración es hasta 1 día y la estatuilla debe valer 5 po o más. Con una acción de Magia movés la ilusión hasta 60 ft (ya no el doble de tu velocidad) y la hacés gesticular, hablar y comportarse como quieras. Ves y oís a través de ella como si estuvieras en su espacio. Una criatura que use la acción Estudiar la discierne con una prueba exitosa de Inteligencia (Investigación) contra tu CD de conjuro."},
{name:"Resurrection", nivel:7, edicion:"ambas", etiquetas:["curación", "utilidad"], escuela:"Necromancia", tiempo:"1 hora", alcance:"Toque", componentes:"V, S, M (un diamante de al menos 1.000 gp, que el hechizo consume)", duracion:"Instantáneo", clases:["Bardo", "Clérigo"], desc:"Tocás a una criatura muerta hace no más de un siglo, que no murió de vejez y que no es no-muerta. Si su alma es libre y está dispuesta, revive con todos sus PG. Neutraliza los venenos y cura las enfermedades normales que la afectaban al morir, pero no quita enfermedades mágicas ni maldiciones (si no se eliminaron antes, la afectan al revivir). Cierra todas las heridas mortales y restaura las partes del cuerpo faltantes. Volver de la muerte es duro: -4 a todas las tiradas de ataque, de salvación y pruebas de característica; cada descanso largo reduce la penalización en 1 hasta que desaparece. Si la criatura lleva muerta un año o más, te agota: hasta que termines un descanso largo no podés lanzar hechizos y tenés desventaja en todas las tiradas de ataque, pruebas de característica y salvaciones.", desc2024:"En 2024: tocás a una criatura muerta hace no más de un siglo, que no murió de vejez y que no era No-muerta al morir; revive con todos sus PG. Neutraliza los venenos (ya no menciona curar enfermedades), cierra todas las heridas mortales y restaura partes faltantes. Sufre -4 a las pruebas de d20; cada descanso largo reduce la penalización en 1 hasta llegar a 0. Si lleva muerta 365 días o más, te agota: hasta que termines un descanso largo no podés lanzar hechizos y tenés desventaja en las pruebas de d20."},
{name:"Sequester", nivel:7, edicion:"ambas", etiquetas:["utilidad", "protección"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S, M (polvo de diamante, esmeralda, rubí y zafiro por 5.000 po como mínimo, que se consume)", duracion:"Hasta que se disipe", clases:["Mago"], desc:"Escondés a una criatura voluntaria u objeto que tocás, a salvo de detección: se vuelve invisible y no puede ser objetivo de conjuros de adivinación ni percibida por sensores de escudriñamiento. Si es una criatura, entra en animación suspendida: el tiempo no fluye para ella y no envejece. Podés fijar una condición para que termine antes (debe ocurrir o ser visible a 1 mi del objetivo, p. ej. \"dentro de 1.000 años\" o \"cuando despierte la tarrasca\"). También termina si el objetivo recibe daño.", desc2024:"En 2024: el objetivo queda Invisible y no puede ser objetivo de conjuros de adivinación, detectado por magia ni visto remotamente con magia. Si es una criatura, entra en animación suspendida: queda Inconsciente, no envejece y no necesita comida, agua ni aire. Misma condición opcional de fin (a 1 mi) y termina si el objetivo recibe daño."},
{name:"Simulacrum", nivel:7, edicion:"ambas", etiquetas:["invocación", "ilusión"], escuela:"Ilusión", tiempo:"12 horas", alcance:"Toque", componentes:"V, S, M (nieve o hielo suficiente para una copia a tamaño real de la criatura; un poco de pelo, uñas u otra parte de su cuerpo dentro del hielo; y rubí en polvo por valor de 1.500 po, que el hechizo consume)", duracion:"Hasta que se disipe", clases:["Mago"], desc:"Durante todo el lanzamiento moldeás un duplicado ilusorio de una bestia o humanoide en alcance: una criatura parcialmente real hecha de hielo o nieve que actúa y es afectada como una normal. Parece idéntica al original, con la mitad de su máximo de PG y sin equipo; por lo demás usa todas sus estadísticas. Es amistosa con vos y con quienes designes, obedece tus órdenes verbales y actúa en tu turno en combate. No puede aprender ni mejorar (no sube de nivel) ni recuperar espacios de conjuro gastados. Si recibe daño, podés repararla en un laboratorio alquímico con hierbas y minerales raros por 100 po por PG recuperado. Dura hasta llegar a 0 PG (se vuelve nieve y se derrite). Si lo lanzás de nuevo, los duplicados activos que hayas creado se destruyen al instante.", desc2024:"En 2024: la criatura debe estar a 10 ft de vos durante el lanzamiento y terminás tocándola junto con una pila de hielo o nieve de su mismo tamaño, que se transforma en el simulacro. Usa las estadísticas del original al momento de lanzarlo, pero es un Constructo, con la mitad del máximo de PG, y no puede lanzar este hechizo. Es Amistoso con vos y con quienes designes, obedece tus órdenes y actúa en tu turno. No gana niveles ni puede tomar descansos cortos o largos. Para restaurar sus PG hay que repararlo mientras hacés un descanso largo, gastando componentes por 100 po por PG, y debe estar a 5 ft de vos. Dura hasta 0 PG; si lo lanzás de nuevo, el simulacro anterior se destruye. El único material es rubí en polvo de 1.500+ po, que se consume."},
{name:"Symbol", nivel:7, edicion:"ambas", etiquetas:["daño", "necrótico", "control", "salvación", "protección"], escuela:"Abjuración", tiempo:"1 minuto", alcance:"Toque", componentes:"V, S, M (mercurio, fósforo y polvo de diamante y ópalo con un valor total de al menos 1.000 po, que el conjuro consume)", duracion:"Hasta que se disipe", clases:["Bardo", "Clérigo", "Mago"], desc:"Inscribís un glifo dañino sobre una superficie (hasta 10 ft de diámetro) o dentro de un objeto que pueda cerrarse (libro, pergamino, cofre); el objeto debe quedarse en su lugar: si se mueve a más de 10 ft, el glifo se rompe y el conjuro termina sin activarse. Es casi invisible: encontrarlo requiere una prueba de Inteligencia (Investigación) contra tu CD. Definís el disparador (tocarlo, pisarlo, acercarse, abrir el objeto, verlo o leerlo…), que podés refinar por características físicas o tipo de criatura, y excepciones (quien diga una contraseña). Al activarse, brilla con luz tenue en una esfera de 60 ft de radio durante 10 minutos y luego el conjuro termina; afecta a cada criatura en la esfera al activarse y a quien entre por primera vez en un turno o termine ahí su turno. Efecto a elegir: Muerte (salvación de Constitución, 10d10 daño necrótico, mitad si supera); Discordia (Constitución; si falla, discute con otros 1 minuto, sin comunicación útil y con desventaja en ataques y pruebas); Miedo (Sabiduría; Asustado 1 minuto, suelta lo que sostiene y debe alejarse 30 ft del glifo cada turno); Desesperanza (Carisma; 1 minuto no puede atacar ni apuntar a criaturas con efectos dañinos); Locura (Inteligencia; 1 minuto no puede actuar, entender, leer, solo balbucea y el DM controla su movimiento errático); Dolor (Constitución; Incapacitado 1 minuto); Sueño (Sabiduría; Inconsciente 10 minutos, despierta si sufre daño o alguien lo sacude con una acción); Aturdimiento (Sabiduría; Aturdido 1 minuto).", desc2024:"Mismo glifo (10 ft de diámetro, sobre superficie u objeto que se cierre; se rompe si lo movés a más de 10 ft), pero detectarlo requiere una prueba de Sabiduría (Percepción) contra tu CD, solo se consume polvo de diamante de 1.000+ po y dura hasta que se disipe o se active. Se pueden refinar los disparadores por tipo de criatura. Efectos: Muerte (Constitución, 10d10 necrótico, mitad si supera), Discordia (ahora salvación de Sabiduría; 1 minuto sin comunicación útil, desventaja en ataques y pruebas), Miedo (Sabiduría; Asustado 1 minuto, debe alejarse 30 ft del glifo), Dolor (Constitución; Incapacitado 1 minuto), Sueño (Sabiduría; Inconsciente 10 minutos) y Aturdimiento (Sabiduría; Aturdido 1 minuto). Se eliminan Desesperanza y Locura. Una criatura es objetivo solo una vez por turno. En 2024 también es conjuro de Druida."},
{name:"Teleport", nivel:7, edicion:"ambas", etiquetas:["teletransporte", "utilidad"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"10 ft", componentes:"V", duracion:"Instantáneo", clases:["Bardo", "Hechicero", "Mago"], desc:"Transportás al instante a vos y hasta ocho criaturas voluntarias que veas a tu alcance, o a un objeto que veas (debe caber en un cubo de 10 ft y no ser llevado por una criatura reacia), a un destino que conozcas en el mismo plano. El DM tira 1d100 según tu familiaridad: Círculo permanente u objeto asociado: llegás a destino. Muy familiar: 01-05 percance, 06-13 área similar, 14-24 desviado, 25-100 en destino. Visto casualmente: 01-33, 34-43, 44-53, 54-100. Visto una vez o por descripción: 01-43, 44-53, 54-73, 74-100. Destino falso: 01-50 percance, 51-100 área similar. Desviado: aparecés a 1d10 x 1d10 % de la distancia recorrida, en dirección aleatoria (1d8). Área similar: aparecés en el lugar parecido más cercano. Percance: cada criatura sufre 3d10 daño de fuerza y el DM vuelve a tirar (puede repetirse).", desc2024:"En 2024 el objeto debe ser Grande o menor. Se unifican las categorías de familiaridad: círculo permanente y objeto vinculado (poseído desde hace menos de seis meses) llevan siempre a destino; Visto una vez o descrito usa la misma columna (01-43 percance, 44-53 área similar, 54-73 desviado, 74-100 en destino). Desviado: aparecés a 2d12 millas del destino en una dirección aleatoria (1d8: 1 este, 2 sudeste, 3 sur, 4 sudoeste, 5 oeste, 6 noroeste, 7 norte, 8 noreste). Área similar: el lugar parecido más cercano. Percance: 3d10 daño de fuerza a cada criatura y nueva tirada."},

// ===== NIVEL 8 =====
{name:"Animal Shapes", nivel:8, edicion:"ambas", etiquetas:["buff"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, S", duracion:"Conc., hasta 24 horas", clases:["Druida"], desc2024:"En 2024 no requiere concentración y dura 24 horas. Elegís cualquier número de criaturas voluntarias que veas en alcance; cada una se transforma en una Bestia Grande o menor de CR 4 o menos (puede ser distinta para cada una), y en turnos posteriores podés usar una acción de Magia para transformarlas de nuevo. Las estadísticas del objetivo pasan a ser las de la bestia, pero conserva tipo de criatura, PG, Dados de Golpe, alineamiento, capacidad de comunicarse e Inteligencia, Sabiduría y Carisma; no puede lanzar conjuros y su equipo se funde con la forma. Recibe PG temporales iguales a los PG de la primera forma, que se pierden al terminar. La transformación dura el hechizo o hasta que el objetivo la termine con una acción adicional.", desc:"Hasta ocho criaturas voluntarias a tu alcance se transforman en bestias de CR 4 o menor durante la duración."},
{name:"Antipathy/Sympathy", nivel:8, edicion:"ambas", etiquetas:["control"], escuela:"Encantamiento", tiempo:"1 hora", alcance:"60 ft", componentes:"V, S, M (una piedra de imán y aceite/hierbas)", duracion:"10 días", clases:["Druida","Mago"], desc2024:"En 2024: al lanzarlo elegís antipatía o simpatía, y apuntás a una criatura u objeto Enorme o menor; especificás un tipo de criatura (p. ej. dragones rojos, goblins, vampiros). Una criatura de ese tipo que se acerque a 120 ft del objetivo hace una salvación de Sabiduría. Antipatía: si falla, queda Asustada y debe usar su movimiento para alejarse lo más posible del objetivo por la ruta más segura. Simpatía: si falla, queda Hechizada y debe usar su movimiento para acercarse lo más posible; a 5 ft o menos no puede alejarse voluntariamente, y si el objetivo la daña puede repetir la salvación para terminar el efecto. Si la criatura termina su turno a más de 120 ft del objetivo, repite la salvación y, si la supera, el efecto termina. Quien supera la salvación es inmune 1 minuto. El hechizo también está en la lista de Bardo y ya no admite un área de hasta 200 ft.", desc:"Encantás un objeto o lugar para atraer o repeler fuertemente a un tipo de criatura elegido durante la duración."},
{name:"Control Weather", nivel:8, edicion:"ambas", etiquetas:["utilidad"], escuela:"Transmutación", tiempo:"10 minutos", alcance:"Personal", componentes:"V, S, M (quemar incienso y ofrecer plumas)", duracion:"Conc., hasta 8 horas", clases:["Clérigo","Druida","Mago"], desc:"Cambiás gradualmente el clima en un radio de 5 millas (precipitación, temperatura y viento) durante la duración."},
{name:"Earthquake", nivel:8, edicion:"ambas", etiquetas:["daño","contundente","control"], escuela:"Evocación", tiempo:"1 Acción", alcance:"500 ft", componentes:"V, S, M (piedrita de cualquier tipo)", duracion:"Conc., hasta 1 min", clases:["Clérigo","Druida","Hechicero","Mago"], desc2024:"En 2024 es de escuela Transmutación y el temblor (círculo de 100 ft de radio, terreno difícil) lo manejás así: al lanzarlo y al final de cada uno de tus turnos, cada criatura en el suelo hace salvación de Destreza; si falla queda Derribada y pierde la concentración. Fisuras: 1d6 que abrís al final del turno en que lo lanzás, en lugares que elegís (no bajo estructuras), de 1d10 × 10 ft de profundidad y 10 ft de ancho; quien esté en su espacio debe superar una salvación de Destreza o caer. Estructuras: reciben 50 de daño contundente al lanzarlo y al final de cada uno de tus turnos; al llegar a 0 PG se derrumban. Las criaturas a una distancia igual a la mitad de su altura hacen salvación de Destreza: si fallan sufren 12d6 daño contundente (en vez de 5d6), quedan Derribadas y enterradas (prueba de Fuerza (Atletismo) CD 20 como acción para salir); si salvan, la mitad del daño.", desc:"Un temblor violento sacude un área de 100 ft de radio; estructuras pueden derrumbarse y el suelo puede agrietarse durante la duración."},
{name:"Feeblemind", nivel:8, edicion:"2014", etiquetas:["daño","psíquico","control"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"150 ft", componentes:"V, S, M (semilla de amapola)", duracion:"Instantáneo", clases:["Bardo","Druida","Brujo","Mago"], desc:"Una criatura hace salvación de Inteligencia o su Inteligencia y Carisma quedan en 1 hasta ser curado con Greater Restoration o similar."},
{name:"Sunburst", nivel:8, edicion:"ambas", etiquetas:["daño","radiante","salvación"], escuela:"Evocación", tiempo:"1 Acción", alcance:"Personal (60 ft radio)", componentes:"V, S, M (trozo de piedra solar)", duracion:"Instantáneo", clases:["Druida","Hechicero","Mago"], desc2024:"En 2024 también lo lanzan los Clérigos y ya no hay desventaja en la salvación para no-muertos y cienos. Luz solar brillante en una esfera de 60 ft de radio: cada criatura hace salvación de Constitución; si falla sufre 12d6 daño radiante y queda Cegada 1 minuto (mitad del daño y sin Cegado si salva). Una criatura Cegada repite la salvación al final de cada uno de sus turnos. Disipa la oscuridad creada por cualquier hechizo en el área.", desc:"Luz radiante brillante estalla en un radio de 60 ft; cada criatura ahí hace salvación de Constitución, sufriendo 12d6 daño radiante (mitad si salva) y quedando cegada por 1 minuto."},
{name:"Antimagic Field", nivel:8, edicion:"ambas", etiquetas:["protección", "control"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"Personal", componentes:"V, S, M (una pizca de hierro en polvo o limaduras de hierro)", duracion:"Conc., hasta 1 hora", clases:["Clérigo", "Mago"], desc:"Una esfera invisible de antimagia de 10 ft de radio te rodea y se mueve contigo. Dentro no se pueden lanzar conjuros, las criaturas invocadas desaparecen y hasta los objetos mágicos se vuelven mundanos. Los conjuros y efectos mágicos (salvo los de un artefacto o deidad) quedan suprimidos y no pueden entrar; un espacio gastado en un conjuro suprimido se consume y el tiempo suprimido cuenta para su duración. Los efectos dirigidos a algo dentro no tienen efecto; las áreas de otros conjuros no se extienden adentro; las propiedades de los objetos mágicos se suprimen (un arma mágica que sale de la esfera recupera su magia al salir). Teletransporte y viaje planar fallan hacia o desde la esfera; los portales y espacios extradimensionales se cierran temporalmente. Las criaturas u objetos creados o invocados por magia desaparecen mientras estén dentro. Dispel Magic no la afecta y varias esferas no se anulan entre sí.", desc2024:"En 2024: es un aura de 10 ft de emanación; nadie dentro puede lanzar conjuros, usar acciones Magia ni crear otros efectos mágicos, y esas cosas no pueden apuntar ni afectar nada adentro. Las propiedades mágicas de los objetos no funcionan dentro del aura ni sobre lo que esté en ella. Las áreas de efecto mágicas no se extienden adentro, nadie puede teletransportarse hacia o desde ella ni usar viaje planar, y los portales se cierran. Los conjuros en curso (salvo los de un artefacto o deidad) quedan suprimidos y el tiempo suprimido cuenta para su duración. Dispel Magic no la afecta."},
{name:"Befuddlement", nivel:8, edicion:"2024", etiquetas:["daño", "psíquico", "salvación", "control"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"150 ft", componentes:"V, S, M (un llavero sin llaves)", duracion:"Instantáneo", clases:["Bardo", "Druida", "Brujo", "Mago"], desc:"Atacás la mente de una criatura que veas a alcance, que hace salvación de Inteligencia. Si falla, sufre 10d12 daño psíquico y no puede lanzar conjuros ni realizar la acción Magia; al final de cada 30 días repite la salvación y el efecto termina si la supera (también lo terminan Greater Restoration, Heal o Wish). Si salva, sufre solo la mitad del daño."},
{name:"Clone", nivel:8, edicion:"ambas", etiquetas:["utilidad", "invocación"], escuela:"Necromancia", tiempo:"1 hora", alcance:"Toque", componentes:"V, S, M (un diamante de 1.000 po y al menos 1 pulgada cúbica de carne de la criatura a clonar, que se consumen, y un recipiente de 2.000 po con tapa sellable, lo bastante grande para una criatura Mediana)", duracion:"Instantáneo", clases:["Mago"], desc:"Hacés crecer un duplicado inerte de una criatura viva como resguardo contra la muerte. El clon se forma dentro de un recipiente sellado y alcanza tamaño y madurez completos a los 120 días (también podés elegir que sea una versión más joven). Permanece inerte indefinidamente mientras el recipiente no se perturbe. Si el original muere después de que el clon madure, su alma se transfiere al clon si está libre y dispuesta a volver. El clon es físicamente idéntico, con la misma personalidad, recuerdos y habilidades, pero sin su equipo. Los restos del original quedan inertes y no pueden revivirse."},
{name:"Demiplane", nivel:8, edicion:"ambas", etiquetas:["utilidad", "invocación"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"60 ft", componentes:"S", duracion:"1 hora", clases:["Brujo", "Mago"], desc:"Creás una puerta sombría, lo bastante grande para criaturas Medianas, sobre una superficie sólida y plana que veas a tu alcance. Al abrirla da a un semiplano con forma de sala vacía de 30 ft por lado, de madera o piedra. Cuando el conjuro termina, la puerta desaparece y cualquier criatura u objeto dentro queda atrapado, porque la puerta también desaparece del otro lado. Cada vez que lo lanzás podés crear un semiplano nuevo o conectar la puerta con uno que hayas creado antes; también con el de otra criatura, si conocés su naturaleza y contenido.", desc2024:"La puerta sombría Mediana puede abrirse y cerrarse; el semiplano es una sala vacía de 30 ft por lado de madera o piedra (a tu elección). Al terminar el conjuro la puerta desaparece: los objetos dentro permanecen, y las criaturas también, salvo que opten por ser expulsadas por la puerta al desaparecer, cayendo Derribadas en los espacios desocupados más cercanos al espacio de la puerta (ya no quedan atrapadas por fuerza). Podés crear un semiplano nuevo o conectar con uno propio previo o ajeno que conozcas. En 2024 también es conjuro de Hechicero."},
{name:"Dominate Monster", nivel:8, edicion:"ambas", etiquetas:["control", "salvación"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S", duracion:"Conc., hasta 1 hora", clases:["Bardo", "Hechicero", "Brujo", "Mago"], desc:"Intentás subyugar a una criatura que veas a tu alcance: debe superar una tirada de salvación de Sabiduría o queda Hechizada durante la duración (con ventaja en la salvación si vos o tus aliados están peleando contra ella). Mientras esté Hechizada tenés un vínculo telepático con ella en el mismo plano y podés darle órdenes sin gastar acción (simples y generales: «Atacá a esa criatura», «Corré para allá»), que cumple lo mejor posible; si completa la orden sin nuevas indicaciones, se defiende y preserva. Con tu acción tomás control total y preciso hasta el final de tu siguiente turno: solo hace lo que permitís y puede usar una reacción, pero gastando también la tuya. Cada vez que recibe daño hace una nueva salvación de Sabiduría; si la supera, el conjuro termina. A niveles superiores: con un espacio de nivel 9, la concentración dura hasta 8 horas.", desc2024:"En 2024 ya no existe la acción de control total: el objetivo sigue tus órdenes telepáticas (sin acción) lo mejor que pueda en su turno, y si completa una orden sin nuevas indicaciones actúa y se mueve a su gusto, cuidándose a sí mismo. Podés ordenarle usar una reacción, pero gastando la tuya. Cada vez que recibe daño repite la salvación; si la supera, el conjuro termina. Con un espacio de nivel 9, la concentración dura hasta 8 horas."},
{name:"Glibness", nivel:8, edicion:"ambas", etiquetas:["buff", "utilidad"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"Personal", componentes:"V", duracion:"1 hora", clases:["Bardo", "Brujo"], desc:"Mientras dure, cuando hacés una prueba de Carisma podés reemplazar el número que sacás por un 15. Además, diga lo que digas, la magia que determine si decís la verdad indica que sos sincero."},
{name:"Holy Aura", nivel:8, edicion:"ambas", etiquetas:["protección", "buff", "salvación"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"Personal", componentes:"V, S, M (un diminuto relicario por valor de al menos 1000 po que contenga una reliquia sagrada, como un trozo de tela de la túnica de un santo o un pedazo de pergamino de un texto religioso)", duracion:"Conc., hasta 1 min", clases:["Clérigo"], desc:"Luz divina emana de vos y forma un suave resplandor de 30 ft de radio. Las criaturas a tu elección dentro de ese radio al lanzarlo emiten luz tenue en 5 ft de radio, tienen ventaja en todas las tiradas de salvación y las demás criaturas tienen desventaja en las tiradas de ataque contra ellas mientras dure. Además, cuando un infernal o un muerto viviente impacta con un ataque cuerpo a cuerpo a una criatura afectada, el aura destella: el atacante debe superar una salvación de Constitución o queda Cegado hasta que termine el conjuro.", desc2024:"En 2024 emitís un aura en una emanación de 30 ft: las criaturas a tu elección dentro de ella tienen ventaja en todas las tiradas de salvación y las demás criaturas tienen desventaja en las tiradas de ataque contra ellas. Cuando un infernal o un muerto viviente impacta con una tirada de ataque cuerpo a cuerpo a una criatura afectada, el atacante debe superar una salvación de Constitución o queda Cegado hasta el final de su próximo turno (ya no hasta que termine el conjuro). Ya no emiten luz tenue."},
{name:"Incendiary Cloud", nivel:8, edicion:"ambas", etiquetas:["daño", "fuego", "salvación"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"150 ft", componentes:"V, S", duracion:"Conc., hasta 1 min", clases:["Hechicero", "Mago"], desc:"Una nube de humo con brasas candentes aparece en una esfera de 20 ft de radio a 150 ft; se extiende por las esquinas y está muy oscurecida. Dura hasta que termine el conjuro o un viento moderado o más fuerte (10+ mph) la disperse. Al aparecer, cada criatura dentro hace salvación de Destreza y sufre 10d8 daño de fuego (mitad si salva); también la hace al entrar por primera vez en un turno al área o terminar su turno ahí. Al inicio de cada uno de tus turnos la nube se mueve 10 ft directamente alejándose de vos, en la dirección que elijas.", desc2024:"En 2024: también está en la lista del Druida. La nube (esfera de 20 ft de radio, muy oscurecida) la dispersa un viento fuerte (como Gust of Wind). Cada criatura dentro hace salvación de Destreza y sufre 10d8 daño de fuego (mitad si salva); la salvación también se hace cuando la esfera se mueve a su espacio, al entrar o al terminar su turno ahí, pero solo una vez por turno. La nube se mueve 10 ft alejándose de vos al inicio de cada uno de tus turnos."},
{name:"Maze", nivel:8, edicion:"ambas", etiquetas:["control"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S", duracion:"Conc., hasta 10 min", clases:["Mago"], desc:"Desterrás a una criatura que veas en alcance a un semiplano laberíntico, donde permanece mientras dure o hasta que escape. Puede usar su acción para intentar escapar con una prueba de Inteligencia CD 20; si la supera, escapa y el hechizo termina (un minotauro o un demonio goristro lo logra automáticamente). Al terminar, reaparece en el espacio que dejó o, si está ocupado, en el espacio libre más cercano.", desc2024:"En 2024: para intentar escapar la criatura usa la acción Estudiar y hace una prueba de Inteligencia (Investigación) CD 20; si la supera, escapa y el hechizo termina. Ya no hay excepción automática para minotauros ni demonios goristro. Al terminar reaparece en el espacio que dejó o en el libre más cercano."},
{name:"Mind Blank", nivel:8, edicion:"ambas", etiquetas:["protección"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"Toque", componentes:"V, S", duracion:"24 horas", clases:["Bardo", "Mago"], desc:"Hasta que termine el conjuro, una criatura voluntaria que tocás es inmune al daño psíquico, a cualquier efecto que perciba sus emociones o lea sus pensamientos, a los conjuros de adivinación y a la condición Hechizado. Frustra incluso Wish y conjuros o efectos de poder similar usados para afectar su mente u obtener información sobre ella."},
{name:"Power Word Stun", nivel:8, edicion:"ambas", etiquetas:["control"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"60 ft", componentes:"V", duracion:"Instantáneo", clases:["Bardo", "Hechicero", "Brujo", "Mago"], desc:"Pronunciás una palabra de poder que abruma la mente de una criatura que veas a tu alcance. Si tiene 150 PG o menos, queda Aturdida; si no, el conjuro no tiene efecto. La criatura Aturdida hace una tirada de salvación de Constitución al final de cada uno de sus turnos; si la supera, el aturdimiento termina.", desc2024:"En 2024, si el objetivo tiene más de 150 PG no queda sin efecto: su velocidad pasa a 0 hasta el inicio de tu siguiente turno. Con 150 PG o menos queda Aturdido, y hace una salvación de Constitución al final de cada uno de sus turnos, terminando la condición si la supera."},
{name:"Tsunami", nivel:8, edicion:"2024", etiquetas:["daño", "contundente", "salvación", "control"], escuela:"Conjuración", tiempo:"1 minuto", alcance:"1 mi", componentes:"V, S", duracion:"Conc., hasta 6 turnos", clases:["Druida"], desc:"Una pared de agua surge en un punto en alcance (hasta 300 ft de largo, 300 ft de alto y 50 ft de grosor). Al aparecer, cada criatura en el área hace salvación de Fuerza, sufriendo 6d10 de daño contundente (mitad si salva). Al inicio de cada uno de tus turnos, la pared y las criaturas en ella se mueven 50 ft alejándose de vos; toda criatura Enorme o menor dentro o en cuyo espacio entre la pared debe superar salvación de Fuerza o sufrir 5d10 de daño contundente (una vez por asalto). Al final del turno, la altura baja 50 ft y el daño de asaltos posteriores baja 1d10; con altura 0 el conjuro termina. Quien está dentro se mueve nadando, pero debe superar una prueba de Fuerza (Atletismo) contra tu CD o no puede moverse. Quien sale de la pared cae al suelo."},

// ===== NIVEL 9 =====
{name:"Foresight", nivel:9, edicion:"ambas", etiquetas:["buff"], escuela:"Adivinación", tiempo:"1 minuto", alcance:"Toque", componentes:"V, S, M (águila con plumas)", duracion:"8 horas", clases:["Bardo","Druida","Brujo","Mago"], desc:"La criatura tocada no puede ser sorprendida y tiene ventaja en tiradas de ataque, pruebas de característica y salvaciones durante la duración; otros tienen desventaja al atacarla."},
{name:"Shapechange", nivel:9, edicion:"ambas", etiquetas:["buff"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"Personal", componentes:"V, S, M (jade de 1500+ gp)", duracion:"Conc., hasta 1 hora", clases:["Druida","Mago"], desc2024:"En 2024 te transformás en otra criatura (que hayas visto, no Constructo ni Muerto viviente) de CR no mayor a tu nivel o CR, hasta que termine el conjuro o uses la acción Magia para adoptar otra forma elegible. Al lanzarlo ganás PG temporales iguales a los PG de la primera forma, que desaparecen al terminar el conjuro. Tus estadísticas se reemplazan por las de la forma, pero conservás tipo de criatura, alineamiento, personalidad, Inteligencia, Sabiduría y Carisma, PG, dados de golpe, competencias y capacidad de comunicarte (y Spellcasting si lo tenés). Al transformarte decidís si tu equipo cae al suelo o cambia de tamaño y forma para ajustarse a la nueva forma.", desc:"Te transformás en cualquier criatura conocida de CR igual o menor a tu nivel, con todas sus capacidades, durante la duración."},
{name:"Storm of Vengeance", nivel:9, edicion:"ambas", etiquetas:["daño","trueno","rayo","ácido","frío"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"Vista", componentes:"V, S", duracion:"Conc., hasta 1 min", clases:["Druida"], desc2024:"En 2024: alcance 1 milla y radio de 300 ft (antes 360 ft a la vista). Cada criatura bajo la nube debe superar una salvación de Constitución o sufre 2d6 daño de trueno y queda Ensordecida. Al inicio de cada uno de tus turnos siguientes: turno 2, lluvia ácida, 4d6 daño de ácido a cada criatura y objeto (antes 1d6); turno 3, seis rayos sobre seis objetivos distintos (salvación de Destreza, 10d6 daño de relámpago, mitad si salva); turno 4, granizo, 2d6 daño contundente; turnos 5-10, ráfagas y lluvia helada: terreno difícil, muy oscurecido, 1d6 daño de frío, ataques a distancia con arma imposibles y viento fuerte.", desc:"Una tormenta apocalíptica se forma sobre un radio de 360 ft, causando efectos crecientes turno a turno (trueno, granizo, relámpagos, viento y lluvia ácida)."},
{name:"True Resurrection", nivel:9, edicion:"ambas", etiquetas:["utilidad"], escuela:"Necromancia", tiempo:"1 hora", alcance:"Toque", componentes:"V, S, M (diamantes de 25000+ gp, consumidos)", duracion:"Instantáneo", clases:["Clérigo","Druida"], desc2024:"En 2024 la criatura (muerta hace no más de 200 años, por cualquier causa menos vejez) revive con todos sus PG. Cierra todas las heridas, neutraliza todo veneno, cura todos los contagios mágicos (en vez de todas las enfermedades) y levanta las maldiciones que la afectaban al morir; reemplaza órganos y miembros dañados o faltantes. Si era un muerto viviente, se restaura a su forma original, dejando de ser un muerto viviente. Puede proveer un cuerpo nuevo si el original ya no existe (debés decir su nombre); aparece en un espacio libre a 10 ft de vos.", desc:"Devolvés a la vida a una criatura muerta hasta 200 años, incluso sin cuerpo, con HP completo y curada de toda condición previa."},
{name:"Astral Projection", nivel:9, edicion:"ambas", etiquetas:["utilidad", "teletransporte"], escuela:"Necromancia", tiempo:"1 hora", alcance:"10 ft", componentes:"V, S, M (por cada criatura afectada, un jacinto de al menos 1.000 gp y una barra de plata finamente tallada de al menos 100 gp; el hechizo los consume)", duracion:"Especial", clases:["Clérigo", "Brujo", "Mago"], desc:"Vos y hasta ocho criaturas voluntarias a tu alcance proyectan sus cuerpos astrales al Plano Astral (si ya estás ahí, el hechizo falla y se desperdicia). Los cuerpos materiales quedan inconscientes en animación suspendida: sin comida ni aire, sin envejecer. El cuerpo astral replica tus estadísticas y posesiones y suma un cordón plateado entre los omóplatos (invisible a 1 ft), tu lazo con el cuerpo; si se corta (solo si un efecto lo indica), morís al instante. La forma astral viaja por el Plano Astral y sus portales a otros planos; al entrar a un plano nuevo, tu cuerpo y posesiones viajan por el cordón y reingresás a tu cuerpo. El daño y los efectos sobre la forma astral no afectan al cuerpo físico ni persisten al volver. El hechizo termina cuando lo despedís con una acción; la criatura vuelve a su cuerpo y despierta. Termina antes si un dispel magic exitoso afecta un cuerpo astral o físico, o si el cuerpo o la forma astral llegan a 0 PG (para esa criatura). Si volvés prematuramente, tus compañeros siguen astrales y deben hallar su camino de vuelta (normalmente cayendo a 0 PG).", desc2024:"En 2024 la duración es hasta que se disipe, y si ya estás en el Plano Astral el hechizo termina al instante. Vos y hasta ocho criaturas voluntarias proyectan sus formas astrales; cada cuerpo queda en animación suspendida (condición Inconsciente, sin necesidad de comida ni aire, sin envejecer). La forma astral replica estadísticas y posesiones, con un cordón plateado que se desvanece a 1 ft; si se corta (solo si un efecto lo indica), mueren el cuerpo y la forma astral. En el instante en que la forma astral sale del Plano Astral, el cuerpo y las posesiones viajan por el cordón y el objetivo reingresa a su cuerpo en el nuevo plano. El daño y efectos sobre la forma astral no afectan al cuerpo y viceversa. Si el cuerpo o la forma astral llegan a 0 PG, el hechizo termina para ese objetivo; termina para todos si lo despedís con una acción de Magia. Al terminar para un objetivo que no está muerto, reaparece en su cuerpo y sale de la animación suspendida."},
{name:"Gate", nivel:9, edicion:"ambas", etiquetas:["teletransporte", "utilidad", "invocación"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S, M (un diamante de 5.000 po como mínimo)", duracion:"Conc., hasta 1 min", clases:["Clérigo", "Hechicero", "Mago"], desc:"Conjurás un portal que une un espacio libre que veas a 60 ft con un lugar preciso en otro plano de existencia. Es una abertura circular de 5 a 20 ft de diámetro, orientada como quieras, que dura toda la duración. Tiene frente y dorso en cada plano; solo se viaja cruzando el frente, y quien lo hace aparece en el espacio libre más cercano al portal del otro lado. Las deidades y otros gobernantes planares pueden impedir que se abra en su presencia o dominios. Al lanzarlo podés decir el nombre de una criatura específica (no sirven seudónimos ni apodos); si está en otro plano, el portal se abre junto a ella y la arrastra al espacio libre más cercano de tu lado. No ganás poder sobre ella: puede irse, atacarte o ayudarte, a criterio del DM."},
{name:"Imprisonment", nivel:9, edicion:"ambas", etiquetas:["control", "salvación"], escuela:"Abjuración", tiempo:"1 minuto", alcance:"30 ft", componentes:"V, S, M (una representación en vitela o una estatuilla tallada a imagen del objetivo, y un componente especial según la versión, por valor de al menos 500 po por Dado de Golpe del objetivo)", duracion:"Hasta que se disipe", clases:["Brujo", "Mago"], desc:"Creás una sujeción mágica para una criatura que veas en alcance: salvación de Sabiduría o queda atada (si salva, es inmune a este hechizo si lo lanzás de nuevo). Atada, no respira, come ni bebe, no envejece y las adivinaciones no pueden ubicarla ni percibirla. Elegís una forma: Entierro (esfera de fuerza bajo tierra; nada entra ni sale, ni por teletransporte; orbe de mithral), Encadenamiento (cadenas arraigadas; queda Apresado e inamovible; cadena fina de metal precioso), Prisión Cercada (semiplano protegido contra teletransporte y viaje planar; miniatura de jade), Contención Mínima (1 pulgada dentro de una gema que no se corta ni rompe; gema grande y transparente), Letargo (duerme y no despierta; hierbas soporíferas raras). Al lanzarlo podés fijar una condición razonable, observable, que lo libere (el DM decide). Dispel magic solo lo termina con espacio de nivel 9 sobre la prisión o el componente; cada componente sostiene una sola prisión.", desc2024:"En 2024: el objetivo hace salvación de Sabiduría; si la supera no es afectado y es inmune 24 horas; si falla queda apresado (no respira, come ni bebe, no envejece, las adivinaciones no lo hallan y no puede teletransportarse) y sufre una forma a tu elección: Entierro (globo hueco de fuerza bajo tierra), Encadenamiento (Apresado e inamovible), Prisión Cercada (semiplano protegido contra teletransporte y viaje planar), Contención Mínima (1 pulgada, atrapado en una gema indestructible; la luz pasa, nada más), Letargo (Inconsciente, no despierta). Material: una estatuilla del objetivo de 5.000+ po. Al lanzarlo fijás un detonante observable que termine el hechizo y que el DM juzgue muy probable que ocurra en la próxima década. Dispel Magic solo lo termina con espacio de nivel 9 sobre la prisión o el componente."},
{name:"Mass Heal", nivel:9, edicion:"ambas", etiquetas:["curación"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S", duracion:"Instantáneo", clases:["Clérigo"], desc:"Un torrente de energía curativa fluye de vos hacia las criaturas heridas a tu alrededor. Restaurás hasta 700 PG, divididos como quieras entre cualquier cantidad de criaturas que veas a tu alcance. Las criaturas curadas también quedan curadas de todas las enfermedades y de cualquier efecto que las deje Cegadas o Ensordecidas. No tiene efecto sobre no-muertos ni constructos.", desc2024:"Restaurás igualmente hasta 700 PG divididos entre las criaturas que veas a tu alcance, pero ahora las criaturas curadas dejan de estar Cegadas, Ensordecidas y Envenenadas (ya no cura enfermedades). La versión 2024 no menciona la exclusión de no-muertos y constructos. Pasa a ser conjuro de Abjuración."},
{name:"Meteor Swarm", nivel:9, edicion:"ambas", etiquetas:["daño", "fuego", "contundente", "salvación"], escuela:"Evocación", tiempo:"1 Acción", alcance:"1 mi", componentes:"V, S", duracion:"Instantáneo", clases:["Hechicero", "Mago"], desc:"Orbes de fuego ardiente caen en cuatro puntos distintos que veas a tu alcance. Cada criatura en una esfera de 40 ft de radio centrada en cada punto hace una tirada de salvación de Destreza; la esfera se extiende alrededor de esquinas. Si falla, sufre 20d6 daño de fuego y 20d6 daño contundente; si salva, la mitad. Una criatura en el área de más de una explosión se ve afectada una sola vez. El conjuro daña objetos en el área y enciende los inflamables que nadie lleve puestos o en mano."},
{name:"Power Word Heal", nivel:9, edicion:"2024", etiquetas:["curación"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"60 ft", componentes:"V", duracion:"Instantáneo", clases:["Bardo", "Clérigo"], desc:"Una ola de energía curativa envuelve a una criatura que veas en alcance: recupera todos sus PG. Si tiene la condición Hechizado, Asustado, Paralizado, Envenenado o Aturdido, esa condición termina. Si está Derribada, puede usar su reacción para ponerse de pie."},
{name:"Power Word Kill", nivel:9, edicion:"ambas", etiquetas:["daño", "control"], escuela:"Encantamiento", tiempo:"1 Acción", alcance:"60 ft", componentes:"V", duracion:"Instantáneo", clases:["Bardo", "Hechicero", "Brujo", "Mago"], desc:"Pronunciás una palabra de poder que obliga a morir a una criatura que veas en alcance. Si tiene 100 PG o menos, muere; si no, el conjuro no tiene efecto.", desc2024:"En 2024: obligás a morir a una criatura que veas en alcance. Si tiene 100 PG o menos, muere; si no, sufre 12d12 de daño psíquico."},
{name:"Prismatic Wall", nivel:9, edicion:"ambas", etiquetas:["protección", "control", "daño", "fuego", "ácido", "rayo", "veneno", "frío", "salvación"], escuela:"Abjuración", tiempo:"1 Acción", alcance:"60 ft", componentes:"V, S", duracion:"10 minutos", clases:["Mago"], desc:"Un muro vertical opaco de luz multicolor de hasta 90 x 30 ft y 1 pulgada de grosor (o una esfera de hasta 30 ft de diámetro) se forma en un punto que veas a tu alcance. Si atraviesa el espacio de una criatura, el hechizo falla y se pierden acción y espacio. Emite luz brillante a 100 ft y tenue otros 100 ft. Vos y los que designes pasan sin daño; otra criatura que lo vea a 20 ft o menos (o empiece su turno ahí) hace salvación de Constitución o queda Cegada 1 minuto. Tiene siete capas; quien lo atraviesa pasa de a una y en cada una hace salvación de Destreza o sufre su efecto. Se destruye capa por capa, de rojo a violeta (una destruida lo sigue toda la duración); una vara de cancelación lo destruye, un campo antimagia no lo afecta. Rojo: 10d6 de fuego (mitad si salva), frena ataques a distancia no mágicos, lo destruyen 25+ de daño de frío. Naranja: 10d6 de ácido, frena ataques a distancia mágicos, lo destruye viento fuerte. Amarillo: 10d6 de relámpago, lo destruyen 60+ de daño de fuerza. Verde: 10d6 de veneno, lo destruye passwall o un hechizo igual o mayor que abra un portal. Azul: 10d6 de frío, lo destruyen 25+ de daño de fuego. Índigo: si falla, queda Apresado y hace salvación de Constitución al final de cada turno (3 éxitos terminan el efecto; 3 fallos lo Petrifican para siempre; no hace falta que sean seguidos); impide lanzar hechizos a través; lo destruye la luz de daylight o similar. Violeta: si falla, queda Cegado y hace salvación de Sabiduría al inicio de tu próximo turno (si la supera, termina la ceguera; si falla, es enviado a otro plano a elección del DM); lo destruye dispel magic o similar.", desc2024:"En 2024 también está en la lista de Bardo; si el muro se coloca en el espacio de una criatura, el hechizo termina al instante sin efecto. Mismo muro de luz (90 x 30 ft x 1 pulgada, o globo de 30 ft), 10 minutos, luz brillante 100 ft y tenue 100 ft más, mismas reglas de Cegado por salvación de Constitución a 20 ft y de siete capas con salvación de Destreza. El muro tiene CA 10 y se destruye capa por capa de rojo a violeta; Antimagic Field no lo afecta y Dispel Magic solo afecta a la capa violeta. Las capas de daño hacen 12d6 (en vez de 10d6; mitad si salva): naranja de ácido (frena ataques mágicos a distancia; lo destruye viento fuerte como Gust of Wind) y verde de veneno (lo destruye Passwall o similar); rojo, amarillo y azul conservan sus tipos de daño y condiciones de destrucción. Índigo: si falla, queda Apresado y hace salvación de Constitución al final de cada turno; 3 éxitos terminan la condición, 3 fallos lo dejan Petrificado hasta que lo libere un efecto como Greater Restoration (no hace falta que sean consecutivos); impide lanzar hechizos a través; lo destruye la luz brillante de Daylight."},
{name:"Time Stop", nivel:9, edicion:"ambas", etiquetas:["utilidad", "buff"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"Personal", componentes:"V", duracion:"Instantáneo", clases:["Hechicero", "Mago"], desc:"Detenés brevemente el flujo del tiempo para todos menos vos: no pasa tiempo para las demás criaturas, mientras vos tenés 1d4 + 1 turnos seguidos en los que actuás y te movés normalmente. El hechizo termina si una de tus acciones, o un efecto que crees en ese lapso, afecta a una criatura que no seas vos o a un objeto que lleve puesto o cargado otra criatura. También termina si te alejás más de 1.000 ft del lugar donde lo lanzaste."},
{name:"True Polymorph", nivel:9, edicion:"ambas", etiquetas:["control", "utilidad"], escuela:"Transmutación", tiempo:"1 Acción", alcance:"30 ft", componentes:"V, S, M (una gota de mercurio, una cucharada de goma arábiga y una voluta de humo)", duracion:"Conc., hasta 1 hora", clases:["Bardo", "Brujo", "Mago"], desc:"Elegís una criatura u objeto no mágico que veas a tu alcance y transformás la criatura en otra criatura, la criatura en objeto o el objeto (no puesto ni cargado por otra criatura) en criatura. Dura hasta que termine el conjuro o el objetivo llegue a 0 PG o muera; si mantenés la concentración toda la duración, la transformación es permanente. No afecta a cambiaformas. Una criatura involuntaria puede superar una salvación de Sabiduría para no ser afectada. Criatura en criatura: la nueva forma puede ser cualquiera con CR igual o menor al del objetivo (o a su nivel); sus estadísticas, incluidas las mentales, se reemplazan por las de la nueva forma, pero conserva alineamiento y personalidad. Asume los PG de la nueva forma y, al revertir, vuelve a sus PG previos (el exceso de daño al llegar a 0 pasa a su forma normal sin dejarla inconsciente mientras no la reduzca a 0). Está limitada por la naturaleza de su forma, no puede hablar, lanzar conjuros ni hacer acciones que requieran manos o habla salvo que la forma pueda; su equipo se fusiona y no puede usarlo. Objeto en criatura: cualquier criatura de tamaño no mayor al del objeto y CR 9 o menor; es amistosa con vos y tus compañeros, actúa en cada uno de tus turnos y vos decidís su acción y movimiento. Si es permanente, dejás de controlarla. Criatura en objeto: se transforma con lo que lleva puesto y cargado; sus estadísticas pasan a ser las del objeto y no recuerda el tiempo en esa forma.", desc2024:"Mismos tres usos y mismas reglas de duración (permanente si mantenés la concentración toda la duración; la salvación de Sabiduría de las criaturas involuntarias se mantiene). Criatura en criatura: la nueva forma tiene CR igual o menor al CR o nivel del objetivo; reemplaza sus estadísticas por el bloque de la nueva forma, pero conserva sus PG, dados de golpe, alineamiento y personalidad, y gana tantos PG temporales como PG tenga la nueva forma (desaparecen al terminar el conjuro). No puede hablar ni lanzar conjuros; su equipo se fusiona y no puede usarlo. Objeto en criatura: CR 9 o menor, tamaño no mayor al del objeto; amistoso con vos y tus aliados, actúa justo después de vos y obedece tus órdenes; si el conjuro dura más de una hora, dejás de controlarlo. Criatura en objeto: solo si el tamaño del objeto no es mayor al de la criatura; sus estadísticas pasan a ser las del objeto y no recuerda el tiempo en esa forma."},
{name:"Weird", nivel:9, edicion:"ambas", etiquetas:["ilusión", "daño", "psíquico", "salvación", "control"], escuela:"Ilusión", tiempo:"1 Acción", alcance:"120 ft", componentes:"V, S", duracion:"Conc., hasta 1 min", clases:["Mago"], desc:"Aprovechando los miedos más profundos de un grupo, creás criaturas ilusorias en sus mentes, visibles solo para ellas. Cada criatura en una esfera de 30 ft de radio centrada en un punto de alcance hace salvación de Sabiduría; si falla, queda Asustada mientras dure, enfrentando sus peores pesadillas como una amenaza implacable. Al inicio de cada turno de una criatura Asustada, debe superar una salvación de Sabiduría o sufrir 4d10 daño psíquico; si salva, el hechizo termina para ella.", desc2024:"En 2024 también lo lanzan los Brujos y el daño es mayor y también inicial. Cada criatura de tu elección en una esfera de 30 ft de radio hace salvación de Sabiduría: si falla sufre 10d10 daño psíquico y queda Asustada mientras dure (mitad del daño si salva). Una criatura Asustada hace una salvación de Sabiduría al final de cada uno de sus turnos: si falla sufre 5d10 daño psíquico; si salva, el hechizo termina para ella."},
{name:"Wish", nivel:9, edicion:"ambas", etiquetas:["utilidad", "curación", "protección", "buff"], escuela:"Conjuración", tiempo:"1 Acción", alcance:"Personal", componentes:"V", duracion:"Instantáneo", clases:["Hechicero", "Mago"], desc:"El conjuro más poderoso que puede lanzar un mortal. Uso básico: duplicar cualquier otro conjuro de nivel 8 o menor, sin cumplir sus requisitos ni componentes costosos. También podés crear uno de estos efectos: un objeto no mágico de hasta 25.000 gp y 300 ft por lado, en un espacio libre que veas; hasta 20 criaturas que veas recuperan todos sus PG y termina en ellas todo lo de Greater Restoration; resistencia a un tipo de daño para hasta 10 criaturas; inmunidad a un conjuro o efecto mágico por 8 horas para hasta 10 criaturas; o deshacer un evento reciente forzando a repetir cualquier tirada del último asalto (con ventaja o desventaja a tu elección, y elegís cuál conservar). Otros deseos los resuelve el DJ con gran libertad: cuanto mayor, más probable que algo salga mal (falle, se cumpla en parte o con consecuencias imprevistas). Usarlo para algo distinto de duplicar un conjuro te desgasta: cada conjuro que lances hasta terminar un descanso largo te inflige 1d10 de daño necrótico por nivel (no se reduce ni evita); tu Fuerza baja a 3 durante 2d4 días (cada día de reposo ligero reduce la recuperación en 2 días); y hay 33% de probabilidad de no poder lanzarlo nunca más.", desc2024:"En 2024: duplicar un conjuro de nivel 8 o menor, o elegir uno de estos efectos: crear un objeto no mágico de hasta 25.000 gp (300 ft por lado); Salud instantánea (vos y hasta 20 criaturas recuperan todos sus PG y termina lo de Greater Restoration); Resistencia permanente a un tipo de daño para hasta 10 criaturas; Inmunidad a un conjuro o efecto mágico 8 horas para hasta 10 criaturas; Aprendizaje súbito (cambiás una dote por otra elegible que no sea prerrequisito de otras tuyas); Repetir tirada (rehacer cualquier tirada del último asalto, con Ventaja o Desventaja, y elegís cuál usar); o Reformar la realidad (un deseo libre que arbitra el DJ: puede fallar, cumplirse en parte o tener consecuencias imprevistas; consecuencias a escala de comunidad o mundo atraen enemigos poderosos, los dioses pueden intervenir y deshacer el multiverso falla). Usarlo para algo distinto de duplicar un conjuro te desgasta: 1d10 de daño necrótico por nivel por cada conjuro hasta un descanso largo (no se reduce ni evita), tu Fuerza pasa a ser 3 por 2d4 días (reposo ligero reduce la recuperación 2 días por día) y 33% de probabilidad de no poder lanzarlo más."},

];

// Edición del texto de los hechizos. Cada entrada trae `desc` (SRD 5.1, 2014; o la 2024 si el hechizo solo existe
// en 2024) y, cuando la versión 2024 cambió la mecánica, `desc2024`. `edicion` = '2014' | '2024' | 'ambas'
// (ausente en los hechizos viejos del grupo = 'ambas'). Fuente: SRD 5.1 y SRD 5.2, CC-BY-4.0 (Wizards of the Coast).
const EDICIONES_HECHIZOS = ['2014', '2024'];
function edicionPreferida() {
  try { const e = localStorage.getItem('rol-edicion-hechizos'); if (EDICIONES_HECHIZOS.includes(e)) return e; } catch (e) {}
  return '2014';
}
function guardarEdicionPreferida(ed) { try { localStorage.setItem('rol-edicion-hechizos', ed); } catch (e) {} }
function descDeHechizo(s, ed) { return (ed || edicionPreferida()) === '2024' && s.desc2024 ? s.desc2024 : s.desc; }
function etiquetaEdicion(s) { return s.edicion === '2014' ? 'solo 2014' : s.edicion === '2024' ? 'solo 2024' : ''; }

